export const SEARCH_INDEX: SearchEntry[] = [{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Account, routes & story ownership","id":"","text":""},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Account, routes & story ownership","id":"","text":""},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Routes (lib/routes.ts is the single source of truth)","id":"routes-libroutests-is-the-single-source-of-truth","text":"URL Page / Search landing (or the story page if a story is loaded) /story/[id] A story's own page — refresh-safe and shareable; story cards link here /dashboard, /profile/[userId] Home dashboard, public profile /reading-history Every story read, grouped by date, paginated /analytics Speed / comprehension charts /history Past test attempts (also in the hamburger menu) /settings Theme, reading font, reading speed Navbar: the reading-mode toggle and the story-title link were removed; the profile menu rows are real routes."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Story ownership","id":"story-ownership","text":"An uploaded story belongs to the user whose personal library holds it. SessionManager.findCustomStoryOwner(id) finds that user; getContentAuthorId asks it first (via registerCustomStoryOwnerResolver, wired in lib/session/composition.ts) and only falls back to the demo mapping for built-in stories. The resolver is injected so contentMeta never imports the session layer (which depends on the store that imports contentMeta — a cycle otherwise). Test: npm test."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Profile photo","id":"profile-photo","text":"lib/avatar.ts centre-crops to 256px JPEG; devDataStore.setAvatar/getAvatar persist it (own photo only). components/ui/Avatar.tsx shows photo → initial → icon; used in the navbar, profile menu and profile page. Upload/remove: profile menu or profile page (useAvatarUpload)."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Edit story","id":"edit-story","text":"EditStoryModal reuses the Add-story modal parts (StoryFormParts, StoryCoverPicker, QuestionsInput, rich editor) so both look identical. Replaced/removed cover videos are deleted only when the edit is saved."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Navbar layout & audience section","id":"navbar-layout-audience-section","text":"Navbar: left hamburger menu company name; right notifications, dark-mode switch (ThemeSwitch), profile. The centre slot still hosts the search box / reading timer. Landing \"For every ambitious mind.\" is an Apple-style carousel (components/Landing/AudienceMarquee.tsx): tall dark cards, caption below with a bold lead, previous/next buttons bottom-right, scroll-snap and touch swipe."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Profile button, logout, carousel","id":"profile-button-logout-carousel","text":"The navbar profile button opens your profile page directly (no dropdown). Dashboard / Reading history / Analytics / Past test attempts / Settings are quick links on your own profile page; Log out is at the bottom of the hamburger menu. Landing story carousel: translucent glass covers sit outside the two vertical guide lines (under the arrows); each card's arrow button starts auto-scroll reading at /reader (StoryCard arrowStartsReader), everything else on the card is unchanged."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Deployment","id":"","text":""},{"slug":"deployment","title":"Deployment","folder":"","heading":"Deployment","id":"","text":""},{"slug":"deployment","title":"Deployment","folder":"","heading":"Requirements","id":"requirements","text":"Node.js 18.17 (20 recommended, see .nvmrc), npm 9."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Environment","id":"environment","text":"Variable When Purpose NEXTPUBLICAPIURL build time Backend base URL incl. /api/v1. Empty standalone frontend. See .env.production.example. NEXTPUBLIC values are baked into the bundle, so change them → rebuild."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Build and run (any Linux server)","id":"build-and-run-any-linux-server","text":"npm ci npm run typecheck && npm test # gates npm run build npm start # serves on :3000 (PORT… to change), binds 0.0.0.0 Keep it alive with systemd or PM2 (pm2 start npm --name speed-reader -- start) behind nginx/Caddy that terminates TLS and proxies to 127.0.0.1:3000."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Docker","id":"docker","text":"docker build -t speed-reader --build-arg NEXTPUBLICAPIURLhttps://api.example.com/api/v1 . docker run -d -p 3000:3000 --restart unless-stopped speed-reader Multi-stage, non-root, with a healthcheck."},{"slug":"deployment","title":"Deployment","folder":"","heading":"nginx (example)","id":"nginx-example","text":"server { listen 443 ssl http2; servername app.example.com; location / { proxypass http://127.0.0.1:3000; proxysetheader Host $host; proxysetheader X-Forwarded-For $remoteaddr; proxysetheader X-Forwarded-Proto $scheme; } }"},{"slug":"deployment","title":"Deployment","folder":"","heading":"Landing video","id":"landing-video","text":"Put your file at public/videos/landing-hero.mp4 (optional .webm landing-hero-poster.jpg). Served with a long-lived cache header; rename the file when you replace it so browsers refetch."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Conventions that keep the build green","id":"conventions-that-keep-the-build-green","text":"CSS: plain .css files are imported only in app/layout.tsx (Next.js rejects global CSS imported from components). New component styles: use Tailwind, or a Name.module.css imported by the component. Browser-only reads (localStorage, window) happen in useEffect, never during render, to avoid hydration mismatches. Hook/browser files start with \"use client\". Lint runs in CI (npm run lint), not during next build."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Smoke test after deploy","id":"smoke-test-after-deploy","text":"/ (hero, carousel, sections) · /dashboard · open a story → /reader · reading mode → /read · sign-in · theme switch · 404 page (/nope)."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Security headers","id":"security-headers","text":"Set in next.config.js (nosniff, frame options, referrer policy, permissions policy with microphone allowed for voice search). Add HSTS at the proxy once HTTPS is final."},{"slug":"deployment","title":"Deployment","folder":"","heading":"PDF support (pdf.js)","id":"pdf-support-pdfjs","text":"next build fails with \"failed to parse input file / Syntax Error\" if pdf.js's modern build or worker goes through the SWC minifier. So: the app imports pdfjs-dist/legacy/build/pdf.mjs (pinned to 4.4.168) and loads the worker from /pdf.worker.min.mjs, which scripts/copy-pdf-worker.mjs copies into public/ automatically before npm run dev and npm run build. After upgrading pdfjs-dist, just rebuild."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Troubleshooting","id":"troubleshooting","text":"Cannot find module '.next/server/middleware-manifest.json' and every page is a 500: a stale .next folder (usually left by a failed npm run build) is being reused by next dev. npm run dev now clears it automatically; manually: stop the server, rm -rf .next, start again. Use Node 20 LTS (nvm use), and keep the project in a folder path without spaces or brackets (not speed-reader-frontend (3)); both avoid odd dev-server failures."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Browser storage used by the app","id":"browser-storage-used-by-the-app","text":"localStorage (stories, history, per-user sessions, theme settings), IndexedDB speed-reader-media (story hover videos) and speed-reader-backgrounds (landing theme uploads). Nothing is sent to a server unless NEXTPUBLICAPIURL is set."},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Landing-page themes (\"Add theme\")","id":"","text":""},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Landing-page themes (\"Add theme\")","id":"","text":"Open the hamburger menu → Add theme. It changes the background of the landing page hero only; nothing else in the app. Theme What it is Dots (default) The twinkling dot grid (no mouse interaction). Grainient Animated-free WebGL gradient from components/ui/Grainient.tsx, configured in components/Landing/LandingBackground.tsx. Your uploads Any photo (PNG/JPEG/WebP/GIF/AVIF, ≤ 25 MB) or video (MP4/WebM/MOV, ≤ 80 MB). Videos play muted and looping. Hover a tile to delete it. Adjustments (apply to every theme): Contrast 0.5–1.5, Brightness 0.4–1.6, Saturation 0–2, Dim 0–0.8 (black scrim for text legibility). \"Reset adjustments\" restores neutral values."},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Where things live","id":"where-things-live","text":"lib/landingTheme.ts – selected theme adjustments, saved in localStorage (speed-reader.landing-theme.v1); useLandingTheme() keeps the menu and the landing page in sync. lib/landingMedia.ts – uploaded files, stored in IndexedDB (speed-reader-backgrounds). components/Navigation/ThemePanel.tsx – the menu UI. components/Search/SearchLanding.tsx – renders the chosen background. \"Reset everything\" in the menu also clears the saved theme and uploads."},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Notes","id":"notes","text":"Grainient needs WebGL2; without it the hero simply shows the page background. Defaults leave the original dot background untouched (no filter is applied at neutral values). The Grainient theme is dark by design; on the light site theme use Brightness/Dim to keep the headline readable."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"OOP Architecture & Per-User Sessions","id":"","text":""},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"OOP Architecture & Per-User Sessions","id":"","text":"This document explains how user data is isolated per user, which object-oriented principles and patterns are used, why, and exactly where. Every class and file named here exists in the repo; nothing is described that isn't implemented. 1. What changed and why 2. What \"a session\" contains (feature → class → screen) 3. Class diagram 4. How a user switch flows through the system 5. OOP principles — what, why, where 6. SOLID — one by one 7. Design patterns used 8. Where OOP is deliberately not used 9. Storage layout, migration and the guest session 10. Design decisions and trade-offs 11. How to add a new per-user feature 12. Testing 13. Known limitations and next steps"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"1. What changed and why","id":"1-what-changed-and-why","text":"Before: every persisted feature wrote to one global, un-namespaced localStorage key (srt:history, srt:daily, srt:streak, …). Anyone who logged in on the same browser saw and changed the same history, calendar, streaks, pace graphs, bookmarks and uploads. Backend login tokens were browser-wide too, so user B's reading sessions could be synced into user A's backend account. Now: every signed-in user has their own isolated UserSession — a bundle of repositories that can only read and write that user's data. Switching user switches the session and remounts the React tree, so no screen or in-memory state leaks across users. Requirements this satisfies: Requirement How Separate session per user for graphs, consistency/streak calendar, pace, etc. DailyActivityRepository, StreakRepository, HistoryRepository are constructed per user (§2) \"Everything\" separate, not just some features Bookmarks, achievements, uploads, search history, backend tokens, and the reader's in-memory state are all per-user too Proper OOP Abstract base hierarchy, encapsulated repositories, interfaces, composition, DI (§5–§7) Documented This file"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"2. What \"a session\" contains","id":"2-what-a-session-contains","text":"One UserSession (lib/session/UserSession.ts) composes one repository per feature. Each repository owns exactly one slot in the user's storage namespace. Feature Class Storage slot (srt:v2:u:<userId>:…) Screens that read/write it Reading quiz history, quiz stats HistoryRepository history /history (Past test attempts), /results, reader completion Daily activity — feeds the contribution/streak calendar, the daily pace (WPM) chart, the efficiency/break trends, dashboard totals DailyActivityRepository daily ContributionHeatmap, DailyTrendChart, EfficiencyTrends, Dashboard, useBreakTracker Streak counter StreakRepository streak Landing page, reader completion Lifetime stats (current/longest streak, averages, efficiency) LifetimeStatsCalculator (pure, via UserSession.lifetimeStats()) — (derived from daily) Dashboard, ContributionHeatmap header Bookmarks BookmarkRepository bookmarks Landing page Achievements AchievementRepository achievements — Uploaded / custom stories CustomStoryRepository customStories Library, search, AddStoryModal, EditStoryModal, \"Clear all uploaded stories\" Search history SearchHistoryRepository searchHistory SearchBar, HamburgerMenu Backend (JWT) tokens ScopedTokenStore apiAccessToken, apiRefreshToken lib/api/, AuthProvider, notification stream Reader state (current story, phase, answers, fonts) React tree remount via SessionBoundary in memory everything under the reader Social data (follows, likes, comments, shares, notifications, playlists) already lived in lib/devData/store.ts as records keyed by userId, so it was per-user by construction and is unchanged."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"3. Class diagram","id":"3-class-diagram","text":"classDiagram direction LR class KeyValueStore { <<interface>> getItem(key) string null setItem(key, value) void removeItem(key) void keys() string[] } class BrowserKeyValueStore class MemoryKeyValueStore KeyValueStore < .. BrowserKeyValueStore KeyValueStore < .. MemoryKeyValueStore class UserNamespace { <<value object>> userId key(feature) string owns(key) bool parse(key)$ forUser(id)$ UserNamespace } class UserScopedRepositoryT { <<abstract>> #feature() string #emptyValue() T #deserialize(raw) T #read() T #write(value) void clear() void } class ListRepositoryTItem { <<abstract>> getAll() TItem[] #mutate(fn) TItem[] } UserScopedRepository < -- ListRepository UserScopedRepository < -- StreakRepository UserScopedRepository < -- DailyActivityRepository ListRepository < -- HistoryRepository ListRepository < -- BookmarkRepository ListRepository < -- AchievementRepository ListRepository < -- CustomStoryRepository ListRepository < -- SearchHistoryRepository UserScopedRepository o-- KeyValueStore : injected UserScopedRepository o-- UserNamespace : injected class DailyActivityEntry { <<immutable entity>> merge(input) DailyActivityEntry } class LifetimeStatsCalculator { compute(daily, now) LifetimeStats } DailyActivityRepository ..> DailyActivityEntry : uses class UserSession { <<aggregate / facade>> history streak daily bookmarks achievements customStories searchHistory lifetimeStats() clearAllData() } UserSession -- HistoryRepository UserSession -- StreakRepository UserSession -- DailyActivityRepository UserSession -- BookmarkRepository UserSession -- AchievementRepository UserSession -- CustomStoryRepository UserSession -- SearchHistoryRepository UserSession o-- LifetimeStatsCalculator class IdentityProvider { <<interface>> currentUserId() string null subscribe(listener) unsubscribe } class DevStoreIdentityProvider IdentityProvider < .. DevStoreIdentityProvider class SessionManager { <<registry observer>> active() UserSession sessionFor(userId) UserSession activeUserId() string subscribe(listener) getVersion() number findCustomStoryAnywhere(id) } SessionManager o-- IdentityProvider : injected SessionManager o-- KeyValueStore : injected SessionManager o-- LegacyDataMigrator SessionManager \"1\" o-- \"\" UserSession : one per user id class ScopedTokenStore ScopedTokenStore o-- KeyValueStore : injected File map: lib/session/ storage/KeyValueStore.ts KeyValueStore, BrowserKeyValueStore, MemoryKeyValueStore, factory UserNamespace.ts key scheme (value object) UserScopedRepository.ts UserScopedRepository (abstract) ListRepository (abstract) repositories/.ts History, Streak, DailyActivity, Bookmark, Achievement, CustomStory, SearchHistory analytics/DailyActivityEntry.ts one day's aggregate (immutable) analytics/LifetimeStatsCalculator.ts streak average math (stateless) UserSession.ts aggregate of all repositories for one user SessionManager.ts active-user resolution, session cache, change notification LegacyDataMigrator.ts one-time move of pre-session global data identity/IdentityProvider.ts interface: who is signed in? identity/DevStoreIdentityProvider.ts adapter over the dev login composition.ts composition root (the only place concrete classes are wired) useUserSession.ts React bindings (useSyncExternalStore) lib/api/ScopedTokenStore.ts per-user backend tokens lib/storage.ts facade: old storage. API → active user's session components/Session/SessionBoundary.tsx remounts the tree on user change"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"4. How a user switch flows through the system","id":"4-how-a-user-switch-flows-through-the-system","text":"Login / logout (DevLoginGate → devDataStore.login / logout) │ devDataStore notifies its subscribers ▼ DevStoreIdentityProvider.subscribe ──► SessionManager.onIdentityMaybeChanged() │ compares resolved user id with the last one; │ unrelated store noise (a like, a comment) is ignored ▼ SessionManager.version → notifies subscribers ▼ useActiveUserId() (useSyncExternalStore) → SessionBoundary re-renders ▼ <Fragment key{userId}> → React unmounts & remounts the whole subtree ▼ Every component re-runs its effects → storage. / sessionManager.active() ▼ Resolves the NEW user's UserSession (created once, then cached) Two things make this robust: 1. Resolution at call time. storage.getHistory() calls sessionManager.active() each time; nothing captures \"the current user\" at import. A stale reference to the wrong user's repositories cannot exist. 2. Remount, not just re-read. Persisted data is isolated by the session layer, but React state (the reader's current story, answers, cached useState reads) would otherwise survive a switch. Keying a Fragment by user id resets all of it. Same user ⇒ same key ⇒ no remount, so ordinary navigation is unaffected."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5. OOP principles — what, why, where","id":"5-oop-principles-what-why-where","text":""},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.1 Encapsulation","id":"51-encapsulation","text":"Hide state and representation behind a small, intention-revealing public API. Where What is hidden Public surface UserScopedRepository storage key, JSON parsing, defensive fallbacks (read/write/storageKey are protected) clear() each subclass's verbs HistoryRepository the 50-entry cap and newest-first ordering add, update, quizAttempts, quizStats StreakRepository that count last-read date are stored as one record (they can't be written out of step) get, bump BrowserKeyValueStore window may not exist (SSR), access may throw (private mode), quota errors the 4 KeyValueStore methods that never throw UserNamespace the key format (srt:v2:u:<id>:<feature>) and URL-encoding of ids key(), owns(), parse() DailyActivityEntry the 12 raw counters and how a session folds into them merge(), toJSON() ScopedTokenStore namespaced keys, guest adoption, legacy-key migration get/set/clear token methods UserSession that repositories are constructed with this namespace (readonly fields, no setters) repository properties Why: callers can't produce a wrong key, skip the cap, or mutate a half-built record. The isolation guarantee is structural — no call site has to \"remember\" to include the user id. export abstract class UserScopedRepository<T> { constructor( protected readonly store: KeyValueStore, protected readonly namespace: UserNamespace ) {} protected storageKey(): string { return this.namespace.key(this.feature()); } protected read(): T { const raw this.store.getItem(this.storageKey()); if (raw null) return this.emptyValue(); try { return this.deserialize(JSON.parse(raw)); } catch { return this.emptyValue(); } } }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.2 Abstraction","id":"52-abstraction","text":"Program against what something does, not how. KeyValueStore abstracts \"where bytes live\" (browser, memory, later IndexedDB/API). IdentityProvider abstracts \"who is signed in\" (dev login now, backend JWT later). UserScopedRepository<T> abstracts \"a persisted per-user value\" — UserSession.clearAllData() clears seven different repositories through this one type without knowing which is which. Why: the session layer has no knowledge of localStorage or of the dev login, so either can be replaced without touching a single repository. export interface KeyValueStore { getItem(key: string): string null; setItem(key: string, value: string): void; removeItem(key: string): void; keys(): string[]; }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.3 Inheritance (used sparingly, two levels)","id":"53-inheritance-used-sparingly-two-levels","text":"Reuse an invariant algorithm; specialise only what varies. UserScopedRepository<T> read / write / clear / key building (abstract) ├─ StreakRepository object value ├─ DailyActivityRepository map value └─ ListRepository<TItem> array value: getAll / mutate (abstract) ├─ HistoryRepository cap 50, update-in-place, quiz stats ├─ BookmarkRepository toggle ├─ AchievementRepository idempotent unlock ├─ CustomStoryRepository upsert by id, ownership check └─ SearchHistoryRepository cap 30, case-insensitive de-dupe Why inheritance here: seven repositories share one real \"is-a\" relationship and one algorithm. ListRepository exists because five of them are lists and would otherwise each re-write the empty-array default, the \"is it really an array?\" guard and read-modify-write. The hierarchy stops at two levels on purpose — deeper trees get brittle. export class SearchHistoryRepository extends ListRepository<SearchHistoryEntry> { static readonly MAXENTRIES 30; protected feature(): string { return \"searchHistory\"; } protected deserialize(raw: unknown): SearchHistoryEntry[] { if (!Array.isArray(raw)) return []; const now new Date().toISOString(); return raw.map((entry) > (typeof entry \"string\" ? { term: entry, date: now } : (entry as SearchHistoryEntry))); } }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.4 Polymorphism","id":"54-polymorphism","text":"One call, different behavior depending on the concrete type. Template Method hooks. The base class's read() calls this.deserialize(...) and this.emptyValue(). SearchHistoryRepository overrides deserialize to upgrade the older string[] shape; StreakRepository overrides it to validate an object; the base flow never changes. Interface polymorphism. BrowserKeyValueStore and MemoryKeyValueStore are interchangeable behind KeyValueStore (the tests use the memory one in place of localStorage). Uniform treatment. UserSession.clearAllData() loops ReadonlyArray<UserScopedRepository<unknown>> and calls clear() on each. private readonly repositories: ReadonlyArray<UserScopedRepository<unknown>>; / Wipes every feature's data for this user only. / clearAllData(): void { this.repositories.forEach((repo) > repo.clear()); }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.5 Composition over inheritance","id":"55-composition-over-inheritance","text":"Build big things by combining small collaborators. UserSession has seven repositories and a LifetimeStatsCalculator — it doesn't inherit from them. DailyActivityRepository uses DailyActivityEntry for the merge rule instead of embedding it. SessionManager has a store, an identity provider and a migrator, all injected. Why: \"a user's session\" isn't a kind of repository; it's a bundle of them. Composition keeps each piece independently testable and replaceable. constructor( readonly namespace: UserNamespace, store: KeyValueStore, private readonly stats: LifetimeStatsCalculator new LifetimeStatsCalculator() ) { this.history new HistoryRepository(store, namespace); // …one repository per feature, same namespace }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.6 Immutability / value objects","id":"56-immutability-value-objects","text":"UserNamespace and DailyActivityEntry never change after construction (merge returns a new entry). Why: a half-applied update can't be observed or saved, and equal namespaces are interchangeable. export class UserNamespace { static readonly GUESTID \"guest\"; private constructor(readonly userId: string) {} static forUser(userId: string null undefined): UserNamespace { const trimmed userId?.trim(); return new UserNamespace(trimmed ? trimmed : UserNamespace.GUESTID); } }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"6. SOLID — one by one","id":"6-solid-one-by-one","text":"Principle Where it shows up Single Responsibility LifetimeStatsCalculator only computes (no storage); repositories only persist (no stat math); SessionManager only resolves/caches/notifies; LegacyDataMigrator only migrates; UserNamespace only knows the key scheme. Open/Closed New per-user feature new subclass one registration in UserSession (§11). No existing repository is edited. A new store or identity source new class implementing an interface. Liskov Substitution Any KeyValueStore works anywhere one is expected; any ListRepository subclass honours getAll()/mutate(); MemoryKeyValueStore is a drop-in for the browser store (proved by the test suite running with no browser). Interface Segregation KeyValueStore is 4 methods; IdentityProvider is 2; DevIdentitySource (what the adapter needs from the dev store) is 2. Nothing is forced to depend on methods it doesn't use. Dependency Inversion Repositories depend on KeyValueStore UserNamespace, not on localStorage. SessionManager depends on IdentityProvider, not on the dev store. Concrete classes are chosen in exactly one place: composition.ts."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"7. Design patterns used","id":"7-design-patterns-used","text":"Pattern Class / file Purpose Repository all Repository classes One object per feature owns reading/writing that data; UI never touches storage. Template Method UserScopedRepository (feature, emptyValue, deserialize, serialize hooks) Fixed read/write algorithm, varying steps in subclasses. Facade UserSession; lib/storage.ts UserSession gives one entry point to seven repositories. storage. keeps the old API so the 34 existing call sites became per-user with zero edits. Aggregate / Composition Root UserSession; composition.ts One consistent unit per user; one place that wires concrete classes. Observer SessionManager.subscribe/getVersion ( useSyncExternalStore) React re-renders when the active user changes. Same shape as devDataStore. Registry / Flyweight-style cache SessionManager.sessions (Map<userId, UserSession>) Exactly one session object per user, created lazily and reused. Adapter DevStoreIdentityProvider Presents the dev login as an IdentityProvider; a future ApiIdentityProvider slots in beside it. Factory createDefaultKeyValueStore() Picks browser vs memory store for the runtime (SSR-safe). Value Object UserNamespace, DailyActivityEntry Immutable, compared by value. Singleton (by module scope) sessionManager, tokenStore One instance per page. Created in composition.ts/tokenStore.ts, injected with its dependencies — so classes stay testable (tests build their own instances)."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"8. Where OOP is deliberately not used","id":"8-where-oop-is-deliberately-not-used","text":"Honest scope, so nothing here is overstated: React components and hooks stay function components. Class components are deprecated in modern React and fight hooks/Server Components. OOP is applied to the domain and data layer underneath them — which is where stateful logic and invariants live. (DevDataStore in lib/devData/store.ts was already a class with the Observer pattern; it's unchanged.) ReadingContext is a reducer. A finite-state machine (useReducer) is the right model for the reading-flow transitions; wrapping it in classes would add ceremony, not clarity. The backend (speed-reader-backend) was not refactored in this change. Its user-owned data is already per-user at the database level: reading history and stats (where: { userId }), notifications (by recipientId), playlists (ownership-checked), and refresh-token sessions (a RefreshToken table with revokedAt, rotated on use, with reuse detection). Public content — stories and feeds — is intentionally shared across users. It already uses OOP where it matters: the AppError hierarchy (NotFoundError, UnauthorizedError, ForbiddenError, ConflictError, ValidationError) is classic inheritance polymorphism, consumed by the central error handler. Its services are module-level functions. Converting them to classes with a constructor-injected Prisma client is the natural next step (§13), but I could not type-check backend changes in the environment this was built in (npm registry unreachable, so no Express/Prisma types), and I would rather not ship an unverified refactor of auth/data code."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"9. Storage layout, migration and the guest session","id":"9-storage-layout-migration-and-the-guest-session","text":""},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Key scheme","id":"key-scheme","text":"srt:v2:u:<encodeURIComponent(userId)>:<feature> srt:v2:u:user-1:history srt:v2:u:user-1:daily srt:v2:u:user-2:history ← a different key by construction; collisions are impossible UserNamespace.parse(key) is the inverse, used to discover other users' namespaces."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Legacy data (no data loss)","id":"legacy-data-no-data-loss","text":"Old builds wrote global keys (srt:history, srt:daily, …). LegacyDataMigrator: 1. Runs when a non-guest user's session is first created. 2. Copies each legacy key into that user's namespace (the two-key streak becomes one record), never overwriting data the user already has. 3. Deletes the legacy keys and writes srt:v2:legacy-claimed-by <userId>. 4. So the first real user to sign in after the update inherits the old data, and no second user can."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Guest session","id":"guest-session","text":"When nobody is signed in, the active namespace is guest. It never claims legacy data. (In practice the app shows the login gate, so nothing is persisted as guest — except a backend login made on the login screen, which is adopted by the next user, see below.)"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Backend tokens","id":"backend-tokens","text":"ScopedTokenStore keeps each user's JWT pair in their own namespace. The login screen allows connecting a backend account before choosing a demo persona, so those tokens land in the guest slot; the first real user who reads tokens with none of their own adopts them (moved, not copied). Pre-session browser-wide tokens are adopted the same way. AuthProvider sits inside SessionBoundary so it re-restores the backend login for each user."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"10. Design decisions and trade-offs","id":"10-design-decisions-and-trade-offs","text":"Logical isolation, not a security boundary. All of it lives in the same browser's localStorage; anyone with dev-tools can read any namespace. This stops accidental mixing between users and gives each user a clean, consistent experience. The real security boundary is the backend (JWT where: { userId }). Uploads are per-user; shared stories still open. Each user's uploaded stories live only in their own library, search and feed. But a notification only carries a content id, so getStoryById() falls back to a read-only lookup across users (SessionManager.findCustomStoryAnywhere) so a story someone shared with you can open. That grants no ownership — edit/delete buttons use isCustomStory(), which checks only the active user's own uploads. Facade over rewrite. Keeping storage. unchanged made the isolation change zero-risk for every screen. New code should use useUserSession() / the repositories directly. Lazy session resolution. sessionManager.active() is resolved per call, not captured, so a stale session can't be used after a switch. Remount on switch. Slightly more work than re-reading, but it is the only way to guarantee no in-memory state (current story, quiz answers, cached reads) leaks between users. Limited inheritance depth. Two levels, justified by a true shared algorithm; everything else is composition."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"11. How to add a new per-user feature","id":"11-how-to-add-a-new-per-user-feature","text":"Example: remembering each user's last-used reading speed. // lib/session/repositories/PreferenceRepository.ts import { UserScopedRepository } from \"@/lib/session/UserScopedRepository\"; export class PreferenceRepository extends UserScopedRepository<{ wpm: number }> { protected feature() { return \"preferences\"; } protected emptyValue() { return { wpm: 250 }; } getWpm() { return this.read().wpm; } setWpm(wpm: number) { this.write({ wpm }); } } Then register it in UserSession: readonly preferences: PreferenceRepository; // constructor: this.preferences new PreferenceRepository(store, namespace); // and add this.preferences to the repositories array so clearAllData() covers it. That's the whole change — isolation, caching, user switching and tests-by-substitution come free. Use it from React with const { preferences } useUserSession();."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"12. Testing","id":"12-testing","text":"npx tsx scripts/session-isolation.test.ts # or: npm run test:session Runs under plain Node (no browser, no framework) because the layer depends only on interfaces (MemoryKeyValueStore a fake IdentityProvider). 21 tests, covering: history, quiz attempts/stats, daily activity (calendar/pace/efficiency source), streaks, bookmarks, achievements, search history and uploads never cross users caps (50 history / 30 searches), update-in-place, idempotent unlock, case-insensitive search de-dupe streak rules (same day / next day / gap) and lifetime-streak math incl. the \"today not yet read\" grace clear() / clearAllData() affect only one user old string[] search history is upgraded; corrupt JSON degrades to empty, never throws namespace keys round-trip, even for ids containing : / %; no prefix collisions user switching, session caching, version bumps only on real user change (not on unrelated store noise) data survives sign-out/sign-in and a simulated reload shared-story lookup is read-only; ownership stays per user legacy migration: first real user claims once, guest never claims, never overwrites backend tokens: per-user, guest-login adopted by exactly one user, legacy tokens adopted once Additionally, a one-off differential test compared the new LifetimeStatsCalculator DailyActivityRepository against the original storage.ts on 300 randomized histories — all outputs identical, so the refactor changed where data lives, not what the numbers are. The session layer and the changed API files also pass tsc --strict."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"13. Known limitations and next steps","id":"13-known-limitations-and-next-steps","text":"1. Backend class-based refactor (not done — see §8). Plan: one class per module (HistoryService, PlaylistService, …) taking PrismaClient (and Redis/S3 where needed) in the constructor; controllers as classes receiving the service; a small composition root replacing the module-level import { prisma }. Do it where npm run build can verify it. 2. Social store remains one shared in-browser store. DevDataStore is a single class holding records for all 20 demo users (keyed by userId), which is what the social features need. When the real backend takes over, it is replaced, not extended. 3. Reader preferences (font, theme, speed) are not persisted — they never were, and they reset per user via the remount. §11 shows how to persist them per user if wanted. 4. A future ApiIdentityProvider (backend JWT as the identity source) is a one-class addition in composition.ts; no repository changes."},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"Production checklist","id":"","text":""},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"Production checklist","id":"","text":"Behaviour is unchanged by everything below; these are safety, quality and operability measures."},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"In the repo","id":"in-the-repo","text":"Security headers (next.config.js): nosniff, frame-options, referrer policy, permissions policy, HSTS, COOP; X-Powered-By removed. Error handling: app/error.tsx (route errors), app/global-error.tsx (layout errors), app/not-found.tsx. Metadata: title template, Open Graph, viewport/theme colour, metadataBase from NEXTPUBLICSITEURL; app/robots.ts keeps account pages out of search. Accessibility: skip-to-content link and a <main> landmark; icon buttons carry aria-labels. Dead code removed: unused ThumbnailPicker and ReadingModeToggle. CI (.github/workflows/ci.yml): typecheck → lint → tests → build on every PR. Locally: npm run check. Editor settings: .editorconfig."},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"Before go-live (needs your infrastructure)","id":"before-go-live-needs-your-infrastructure","text":"1. Set NEXTPUBLICSITEURL and the API base URL (.env.production.example). 2. Serve over HTTPS (HSTS is on); put a CDN in front of /next/static and /videos. 3. Replace the dev login/dev store with the real backend auth (see docs/DEPLOYMENT.md). 4. Add a Content-Security-Policy once tested against your hosts (Google Fonts are the only third-party origin). 5. Add error monitoring (e.g. Sentry) in app/error.tsx / app/global-error.tsx. 6. Run npm install to create a lockfile and commit it; use npm ci in CI afterwards."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz tracker, quiz-only mode, and profile tabs","id":"","text":""},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz tracker, quiz-only mode, and profile tabs","id":"","text":""},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz page (app/questions/page.tsx)","id":"quiz-page-appquestionspagetsx","text":"Two columns: the question on the left, components/Quiz/QuestionTracker.tsx on the right (stacks on small screens). Tracker components/ui/AnimatedList.tsx (React Bits, themed with the app tokens through its style prop, so it follows dark/light/sepia). Each question shows: Completed, Marked for review, Skipped or Not answered; header shows \"X of N completed\". Rows show the question text. Three round green buttons under the list filter it: Completed / Marked for review / Not completed (click again to clear; each shows a count). Clicking a row jumps to that question. The quiz is finished with Finish on the last question. The panel is borderless, translucent and blurred, and the page uses the same inertial scrolling as the home page. \"Begin quiz\" now dispatches the chosen question count (GOTOQUESTIONS), preserving quizOnly."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz only (no reading)","id":"quiz-only-no-reading","text":"\"Quiz only\" button in the story hero → GOTOQUESTIONS { quizOnly: true }. Results are saved as a history entry with wpm: 0 (excluded from the speed chart); no reading session is created; ResultCard hides the reading/speed rows."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Profile tabs (own profile only)","id":"profile-tabs-own-profile-only","text":"Dashboard / Reading history / Analytics / Past test attempts / Settings now swap the content area in place of \"Content posted by you\"; click the active pill again to return. Content lives in components/Account/Panel.tsx; the old routes (/history, /reading-history, /analytics, /settings) reuse the same panels and look unchanged. Other users' profiles still show posts only. Note: AnimatedList's demo icon imports (hugeicons) were removed; not verified in a browser (no build available in the sandbox)."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Analytics layout (apple.com-inspired)","id":"analytics-layout-applecom-inspired","text":"Reading speed / Accuracy: two large rounded cards side by side (stacked on mobile) with a centred title, a trend line, an average in brand blue, and the graph below. Consistency (streaks / active days / reading time) and Daily pace: a left-aligned display heading with a blue note on the right, one large card with a two-line caption, then a pill of dots round play button (components/Analytics/PagerPill.tsx). Dots step through the stats (or the latest days for pace); play auto-advances, and starts paused for reduced-motion users. Data, calculations and tooltips are unchanged. Efficiency, Dashboard, Reading history and Past test attempts use the same rounded-[32px] card language (blue notes, display headings, pager on Efficiency)."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Notes, QR code and public link","id":"notes-qr-code-and-public-link","text":"New Notes tab (between Dashboard and Reading history): how CN, OS, OOP and DBMS are used in this project, each with a \"Used here\" and a \"Tradeoff\" line. Content lives in lib/notesContent.ts; one view (components/Notes/NotesView.tsx) serves the tab and the public page. On your own profile a QR code (components/Profile/ProfileQr.tsx) replaced the Change photo button; click your avatar to change the photo. The QR is built from the signed-in user's id (lib/qr.ts, no dependency, tested by decoding), so each user gets a different one. Under it, \"Copy notes link\". The QR opens /notes/<userId>, which now needs a sign-in like every other page (DevLoginGate); it keeps its own header and no app navbar (lib/publicRoutes.ts). The link always points at the deployed app; set NEXTPUBLICSITEURL to override; the default is the deployed Vercel address in lib/publicRoutes.ts (SITEORIGIN), so the QR works from a phone even when running locally."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Uploaded-PDF owner fix","id":"uploaded-pdf-owner-fix","text":"A PDF's pages are images, so a big one can exceed the 5 MB browser storage quota; the save failed silently and the story then looked like it belonged to someone else. CustomStoryRepository now also records the uploader's id in a tiny separate list (customStoryClaims), and SessionManager.findCustomStoryOwner checks it. Test: scripts/session-isolation.test.ts. A PDF too big to store still opens for the session but is not kept in the library."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Test timing (start to finish)","id":"test-timing-start-to-finish","text":"ReadingContext stores quizStartedAt (set when \"Begin quiz\" is pressed, via GOTOQUESTIONS) and quizFinishedAt (set by GOTORESULTS). Total test time finish - start, shown on the results page, the quiz panel (live), and in history. Per-question time is the sum of every visit to that question (flushDwell in app/questions/page.tsx), so revisits and unanswered questions are counted. History entries have quizStartedAt; \"Past test attempts\" shows \"Started 10:42 AM · took 12:03\". Each finished test adds its duration to that day's testMs (DailyActivityRepository.recordTestTime); the consistency tracker's hover card shows total reading time and total test time, and a test-only day counts as active. Leaving mid-quiz without finishing records nothing (there is no result to attach it to)."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Results page and visual system","id":"results-page-and-visual-system","text":"Results use the site width (max-w-6xl) and the apple.com home-page tile grid: one score tile (rating, copy, two pills, all numbers), then Reading speed and Accuracy tiles side by side (TrendTiles), Time per question (10 rows at a time, \"Show 10 more\" / \"Show less\"), efficiency, and the remaining analytics. The Analytics page uses the same width (PageShell wide). The pager under showcase cards is dots only (no play/pause, no auto-advance). Hover cards share one style (lib/chartStyle.ts). Quiz panel: progress shown like the macOS volume HUD inside a liquid-glass container (components/ui/LiquidGlass.tsx, the navbar's GlassSurface), a separate live \"Total test time\", and white round filter buttons with green strokes. Sign-in / sign-up screens use the same card, display heading, underlined fields and pill tabs as the rest of the app. Behaviour is unchanged."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Public notes site (QR code) - documents as web pages","id":"public-notes-site-qr-code---documents-as-web-pages","text":"/notes/<userId> (after signing in) shows the notes, then every document of this docs/ folder; /notes/<userId>/docs/<slug> shows one document as a web page. Links between documents work, and #section links jump to headings. The page has the landing navbar (glass bar, hamburger and name on the left, theme switch on the right). The hamburger has no personal data (no playlists, search history, uploads or sign-out); it lists the notes and one row per docs folder (Project docs, Interview prep). Opening a folder lists its documents; the one being read is highlighted. How it works: scripts/build-docs.mjs bundles docs//.md into lib/docs/generated.ts (full text, server only) and lib/docs/index.generated.ts (titles only, used by the menu). It runs automatically before dev and build, so new or edited docs appear without extra steps; run npm run docs:build to refresh by hand. lib/docs/markdown.ts turns Markdown into escaped HTML (tests: npm run test:docs). Only .md files are published. docs/DEMOACCOUNTS.csv (demo passwords) is deliberately excluded. Anything you write in a docs/.md file becomes public through the QR link, so keep secrets out of those files."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Document pages (public notes)","id":"document-pages-public-notes","text":"Diagrams written as Mermaid blocks are interactive: drag to pan, arrow pad, zoom in/out (Ctrl/⌘ scroll), reset, expand to full screen, copy source. Needs the mermaid package (npm install). Navbar on document pages hides when scrolling down and returns on any scroll up. Research has its own section in the hamburger menu, fed by docs/research/.md. Writing tools for authors: underline, strike, bold italic. (text is accepted but shows as plain text; readers have no select-to-highlight tool on document pages.) Code blocks use a larger font. Search in the centre of the public navbar: a pill that widens on hover/focus; it searches all text on the pages (titles, headings, body, code), shows a snippet with the match highlighted and opens that section; Enter opens the first result. The index is generated into lib/docs/search.generated.ts by scripts/build-docs.mjs and loaded only when the search is used. Diagrams now load Mermaid the ELK layout from a CDN (no npm install needed) and draw like GitHub's viewer (orthogonal arrows). Code blocks are syntax-coloured with indentation kept. Write ts title\"path/to/file.ts\" principle\"What principle it shows\" to show the file path on top and the principle underneath. Any mermaid block becomes an interactive diagram, so new block diagrams can be added the same way. The search bar sits in the centre of the navbar."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Question types (quiz JSON)","id":"question-types-quiz-json","text":"Besides single-choice, the quiz JSON can contain: Select all that apply — \"correctAnswer\": [0, 2] (indexes, letters or option texts). Marked right only when exactly that set is chosen. Typed number — \"options\": [] and \"correctAnswer\": 4.25. Whole numbers must match exactly; decimals are accepted within ±0.01 (set \"tolerance\" to change). The quiz shows checkboxes or a number box with a Check answer button (leaving the question submits what was entered), and results, timing and accuracy use the same grading (lib/grading.ts). A sample is in scripts/fixtures/gate-cs1-2026.json; tests are in scripts/quiz.test.ts."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz JSON: optional labels and code in questions","id":"quiz-json-optional-labels-and-code-in-questions","text":"Each question may also carry these optional fields (none are required): chapter, topic, year (year the previous-year question appeared, e.g. 2026; also accepted as pyqYear) and note (shown on the results page after the test). Chapter, topic and year appear as small chips above the question while taking the quiz. The one-by-one editor has matching optional boxes. Code in a question is shown as a code block with its indentation and line breaks kept and syntax colours. Write it in the JSON with \\n line breaks (and spaces for indentation), or wrap it in a Markdown fence inside the string ( c … ). Plain-text questions with pasted code lines are detected automatically. Options that span several lines are shown as code too."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Syllabus section, layering, and the quiz schema panel","id":"syllabus-section-layering-and-the-quiz-schema-panel","text":"Syllabus: a menu section (below Research) fed by docs/syllabus/.md: chapter 1 Pacewise (sub-systems A–T and the hard engineering areas) and placeholders for chapters 2–8; docs/syllabus/README.md is the index. Layering on doc pages (top to bottom): menu drawer (z 110) → its backdrop (100) → navbar and its search dropdown (95) → full-screen diagram (90, sits under the navbar) → page content. Quiz schema panel: the JSON / file tab of the question uploader (shared by Add story, Edit story and the PDF questions dialog) lists every accepted field, its type, whether it is required, and a full example."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"System design notes in the Syllabus","id":"system-design-notes-in-the-syllabus","text":"Syllabus chapters now hold: System Design (latency vs throughput vs bandwidth in a 3-column table, the cheatsheet image and its 8 sections in 3 columns), Insights (10 algorithms inside system-design boxes), Challenges (8 hidden problems, post link and image). Docs can embed local images with !caption (files in public/docs/); tables accept <br> for line breaks inside cells. Embeds: ::linkedin urn:li:share:<id> <height> \"title\" on its own line embeds a LinkedIn post (only LinkedIn embed URLs are possible). Used in Syllabus › Insights, Syllabus › System Design and Research › Apple AirTag case study. System design folder (docs/system-design/): its own menu group with three embedded LinkedIn posts."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"HTML & CSS interview page","id":"html-css-interview-page","text":"Added docs/interview/13-html-css.md (Interview prep). Code blocks are captioned index.html / styles.css, keep exact indentation, and HTML/XML/SVG now get syntax colouring in lib/docs/highlight.ts."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Search engine system design","id":"search-engine-system-design","text":"Added section 3 \"Pacewise Search Engine\" to docs/syllabus/06-system-design.md with five SVG diagrams in public/docs/search-.svg, capacity estimates, ingestion for docs/PDFs/images (OCR), tenant-routed index, query flow, ranking and failure modes."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Cleanup","id":"cleanup","text":"Insights and Challenges are cleared (placeholders), Syllabus \"System Design 1\" removed, and the three Case studies posts plus the other saved LinkedIn posts now live on one page, docs/system-design/social-media.md."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Time analysis","id":"time-analysis","text":"Profile → Time spent, the story-page speed wheel, overtime clock, hero Prev/Next, the opening-glitch fix and the docs footer are described in docs/TIMEANALYSIS.md and docs/STORYPAGE.md."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Docs pages: path, inertia, rail","id":"docs-pages-path-inertia-rail","text":"Every docs page shows its path (Folder > Tab > Page, each level a link) above the reading time and again just above the footer; the page uses the same eased inertia scrolling as the reading page; the bar-line rail rides up with the footer instead of overlapping it; search results open as a full-width, borderless panel with the rest of the screen blurred below it."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Leadership principles","id":"leadership-principles","text":"docs/leadership-principles/ is a new Documents folder with a sub-folder amazon/ (\"Amazon's Leadership\"): an overview page and one interview-prep page for each of the 16 principles. The menu lists the sub-folder inside its parent."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Leadership principles folder","id":"leadership-principles-folder","text":"Added docs/leadership-principles/ (Documents menu) with sub-folders amazon/ and google/: the headings follow each company's published list and every explanation is original, written for Pacewise."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Reading status, total reading time, theme & uploads","id":"","text":""},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Reading status, total reading time, theme & uploads","id":"","text":""},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Reading status (heartbeat)","id":"reading-status-heartbeat","text":"lib/readingPresence.ts works like WhatsApp's \"online\". Every 5 seconds a heartbeat checks: 1. the person is on a reading surface (story article in view, /read, or the playing /reader), 2. the tab is visible, and 3. they did something (scroll, key, pointer, touch) in the last 60 seconds. All true → the navbar shows ● Reading beside the clock and the beat adds its elapsed time to the user's total. Any false → status drops to idle on the next beat and nothing is added. A sleeping laptop adds at most two beats. Totals are stored per user (speed-reader:reading-time:<userId>) and shown next to the profile photo (hover for the full text). components/Session/PresenceTracker.tsx wires the browser in; tests: npm run test:presence."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Theme","id":"theme","text":"The default follows the system light/dark setting and updates live. Choosing a theme yourself (switch or Settings) is remembered and wins from then on."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Uploading","id":"uploading","text":"PDF/image upload now opens a modal in the same design as \"Add your own story\"; quiz questions can be typed one by one or pasted / loaded as JSON. Dragging a story .json, PDF or image onto the landing page behaves exactly like the upload button (it shows a \"Drop to upload\" overlay)."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Story page","id":"story-page","text":"The stats, About, reading-speed card and Start/Bookmark block below the article were removed; the navbar no longer shows WPM readouts."},{"slug":"story_page","title":"Story page","folder":"","heading":"Story page","id":"","text":""},{"slug":"story_page","title":"Story page","folder":"","heading":"Story page","id":"","text":"The page at / once a story is loaded (components/Dashboard/Dashboard.tsx)."},{"slug":"story_page","title":"Story page","folder":"","heading":"Layout (top to bottom)","id":"layout-top-to-bottom","text":"1. Hero (components/Dashboard/StoryHero.tsx) – the story's uploaded video plays muted/looping, with the thumbnail as poster (falls back to the thumbnail, then a gradient). Title, a stats pill, Read below and a blue Start reading (practice mode) button. 2. Author / follow / content actions / Edit. 3. The full story, in reading mode by default (ReadingModePage with embedded) – no toggle needed. 4. Reading stats, About this story, Reading speed, Start reading Bookmark."},{"slug":"story_page","title":"Story page","folder":"","heading":"Reading extras (only while the article is in view)","id":"reading-extras-only-while-the-article-is-in-view","text":"Progress bar fixed at bottom-0, in BRANDBLUE (#306fdb, lib/brand.ts). Section rail on the right (ScrollRail side\"right\"), active mark in the same blue. Text size A−/A pill (80%–180%), remembered in localStorage (speed-reader.story-font-scale); implemented with the --sr-scale CSS variable in readingMode.css (.sr-embedded)."},{"slug":"story_page","title":"Story page","folder":"","heading":"Moved","id":"moved","text":"\"Past test attempts\" now lives in the hamburger menu and opens /history."},{"slug":"story_page","title":"Story page","folder":"","heading":"Unchanged","id":"unchanged","text":"/read (the toggled reading mode) still uses the left rail and the navbar progress bar."},{"slug":"story_page","title":"Story page","folder":"","heading":"Section list & speed wheel","id":"section-list-speed-wheel","text":"The right-hand section list is always open on wide screens; clicking one of the dashes scrolls to that section and hides/shows the list (ScrollRail alwaysOpen). A speed wheel (components/ui/OptionWheel.tsx, from React Bits; wrapped by ReadingMode/SpeedWheel.tsx) used to sit at the left edge of the article; it now lives on the landing hero (see below). Turn it to pick any reading speed. The navbar clock counts down from words ÷ wpm in real time. It starts when the controls appear and never depends on scrolling. The reading controls (section list, text size, bottom progress bar) appear once the hero has scrolled away and hide again as it returns from the top."},{"slug":"story_page","title":"Story page","folder":"","heading":"Speed, clock and navigation on the story page","id":"speed-clock-and-navigation-on-the-story-page","text":"Speed wheel on the landing hero. The words-per-minute wheel sits above the \"day streak\" line in the hero, so the speed is chosen before reading starts. The wheel is only on the landing hero (it is gone from the article). The speed buttons stay where they were: the reader's controls and shortcuts, and the navbar -/ in reading mode. Clock with overtime. The navbar clock counts down from words ÷ speed. At 0 an alert appears once, the clock turns red and counts up with a \"\" (for example 0:07), so you can see how late you are. The maths is clockFace in lib/readingMode/progress.ts; the alert is useOvertimeAlert. Previous / Next on the hero. Round icon-only buttons step the highlighted action between Read below, Quiz and Start reading; hover shows which action each one selects. They do not move on hover or click. Opening glitch fixed. The app sets scroll-behavior: smooth on the page, so opening a story from a scrolled landing page showed the article first and then glided up to the hero. useScrollToTopOnMount now jumps to the top instantly before the first paint. Time analysis. See TIMEANALYSIS.md."},{"slug":"story_page","title":"Story page","folder":"","heading":"Navigation loader","id":"navigation-loader","text":"The signed-in app covers the screen with the theme colour and a centred tick spinner while a page loads (contexts/NavLoaderContext.tsx): any internal link is covered automatically and useNavLoader().push covers code-driven navigation (story cards, the logo, the menu). A load under 150 ms never shows it. Docs pages do not get the full-screen loader: only their hamburger-menu rows show a small spinner, and the Prev / Next buttons keep their own. The logo now reaches the landing page in one click (the story route no longer reloads a story that was just cleared)."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"Story text editor — design, OOP, CN, OS and DBMS","id":"","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"Story text editor — design, OOP, CN, OS and DBMS","id":"","text":"This document covers the rich text editor that replaced the plain <textarea> in Add your own story and Edit story. Only the text box changed. The guided form fields, the question editor, the JSON tab, the reading engine, the design system and the per-user session layer are untouched. Everything below describes code that exists in this repo. Section 9 lists what is not done, so nothing here should be read as a claim beyond it."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"1. What the user gets","id":"1-what-the-user-gets","text":"Area Implemented Text bold, italic, underline, strike, sub/superscript, font family (any name, with suggestions), font size (any px value), font colour and highlight (palette, recent colours, HEX / rgb() / hsl() entry, reset), clear formatting Blocks Title, Subtitle, Heading 1–6, Quote, alignment (left/centre/right/justify), bullet, numbered (nesting via Tab/ShiftTab), checklists (clickable), indent/outdent, line spacing, space before/after, paragraph background Insert links (CtrlK, scheme allow-list), images, tables, code blocks, horizontal rule, page break, symbols, equations (LaTeX-lite → Unicode), footnotes Code blocks a real code-editor widget per block (see §4.3): 17 languages incl. JS/TS/Python/Java/C/C/C#/Go/Rust/PHP/HTML/CSS/JSON/SQL/Bash/Markdown, highlighting, auto-indent/dedent, bracket/quote pairing, Tab/ShiftTab, Ctrl/ comment, line numbers, current-line highlight, find/replace, wrap, visible whitespace, indent width 2/4/tab, dark/light code theme, copy, clear, delete, \"convert selection to code block\", js Enter shortcut Images file picker, drag & drop, paste; downscaled to ≤1600 px; corner-handle resize (Shift free aspect); left/centre/right; S/M/L; alt text; caption; border; spacing; replace; crop 1:1 / 4:3 / 16:9; delete Tables insert R×C; add/delete rows and columns; merge right/down; split; cell colour; borders toggle; Tab moves between cells (adds a row at the end) Review / View find & replace (match case, highlight), word / character / paragraph / code-block counts, reading time, document properties; continuous or page view, zoom 50–200 %, outline navigation, paper size, orientation, margins, header/footer text, page background, three paper themes Fullscreen Expand button, F11, Esc to exit; caret, selection, scroll and unsaved edits survive (§5.2) Documents title rename inline, autosave status, Save (CtrlS) / Save as copy / New / Open / Delete, crash recovery, import .txt .md .html .json, export .docx .md .html .txt, PDF through the browser print dialog Keyboard: CtrlZ / CtrlY (own history), CtrlB/I/U, CtrlK, CtrlF, CtrlS, F11, Tab / ShiftTab."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"2. How it plugs into the existing app","id":"2-how-it-plugs-into-the-existing-app","text":"AddStoryModal / EditStoryModal │ <StoryTextEditor draftSlot onChange initial> components/Editor/StoryTextEditor.tsx │ builds DocumentStore from sessionManager.active().namespace ▼ EditorView (React shell: ribbon, status bar, menus) components/Editor/EditorView.tsx │ EditorSurface (contenteditable history paste/drop) components/Editor/engine/ │ getHtml() → RichDocument.withHtml() → sanitize ▼ RichDocument (immutable) ──► Blocks (typed model) ──► exporters / stats / reading text │ DocumentStore ──► KeyValueStore UserNamespace (existing session layer, not modified) storyBridge.ts is the only adapter between a story and the editor. On save the story keeps its normal story: [{ paragraph }] (the reading engine is unchanged) and gains an optional richDocument snapshot. If the plain paragraphs are edited elsewhere (for example in the JSON tab) the snapshot no longer matches and is ignored, so what the reader shows is always the source of truth. The JSON tab is unchanged. Pasting JSON still goes through addCustomStory, and richDocument in JSON is treated as untrusted input like everything else. Sessions: nothing in lib/session was edited. DocumentStore borrows the active user's UserNamespace, so another user's documents are unreachable by key construction. SessionBoundary remounts the tree on user switch, so the store is rebuilt for the new user."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"3. File map","id":"3-file-map","text":"lib/editor/ html/ entities, HtmlNode, HtmlParser, HtmlSerializer, SanitizePolicy, HtmlSanitizer model/ Blocks (Block hierarchy BlockVisitor), BlockExtractor, RichDocument export/ Exporter (interface), TextExporters (txt/md/html), DocxExporter, ZipWriter, ExporterRegistry import/ Importers (txt, md, html) ImporterRegistry code/ Tokenizer, languages, CodeEditingEngine persistence/ DocumentStore, ImageStore logic (inside DocumentStore), AutosaveScheduler, EditLock, EditorPrefs format/ TexLite util/ LruCache, crc32, hash storyBridge.ts components/Editor/ StoryTextEditor.tsx (composition root) EditorView.tsx (React shell) editor.css engine/ EditorSurface, CodeBlockWidget, ImageResizer, TableOps, commands, HistoryStack, SelectionMemento, FullscreenController ui/ Ribbon, ColorPopover, icons scripts/editor.test.ts (40 tests, npm run test:editor) lib/editor has no React and no DOM dependency (it runs under Node in the tests); components/Editor is the only layer that touches the browser."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4. OOP — where and why","id":"4-oop-where-and-why","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.1 Document model (lib/editor/model)","id":"41-document-model-libeditormodel","text":"Concept Where Why Abstraction inheritance abstract class Block with ParagraphBlock, HeadingBlock, ListBlock, CodeBlock, ImageBlock, TableBlock, RuleBlock, PageBreakBlock, FootnotesBlock one contract (kind, accept, isEmpty) for every kind of content Immutability / value objects every block field is readonly; InlineRun is a value; RichDocument.withHtml/withMeta/withPage return new instances undo history, autosave diffing and React state can never see a half-mutated object Visitor (double dispatch) BlockVisitor<R> implemented by PlainTextVisitor, MarkdownVisitor, DocxVisitor, StatsVisitor, PlainParagraphVisitor format-specific behaviour lives outside the blocks. A new export format is a new visitor and no block class changes (Open/Closed) Encapsulation RichDocument has a private constructor and static factories (fromHtml, fromSnapshot, empty). fromHtml always sanitizes it is impossible to build a document holding unsanitized HTML Single responsibility BlockExtractor is the only code that understands HTML structure; the sanitizer only filters; the serializer only prints a fix to \"how nested lists are read\" is made once Lazy cached derivation RichDocument.blocks and .stats computed once per immutable instance"},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.2 Pipeline objects","id":"42-pipeline-objects","text":"HtmlSanitizer(parser, serializer, stylePolicy) takes its collaborators through the constructor (Dependency Inversion), so a stricter policy can be injected. StylePolicy and SanitizePolicy.ts express the allow-list as data plus a small object. DocumentExporter / DocumentImporter are Strategy interfaces; ExporterRegistry / ImporterRegistry hold them (Open/Closed, Liskov: every exporter is substitutable). ListNumbering owns the numbering rule once and is shared by the text and Markdown visitors."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.3 Editing layer (components/Editor/engine)","id":"43-editing-layer-componentseditorengine","text":"Concept Where Command EditorCommand, ExecCommand, FnCommand, CommandRegistry. Ribbon buttons, shortcuts and tests all call registry.run(id) Memento HistoryStack (bounded snapshot history) and SelectionMemento (caret survives focus loss and fullscreen) Facade EditorSurface hides contenteditable quirks behind setHtml / getHtml / exec / insertImageFile / find…; React only talks to it Adapter CodeBlockWidget adapts a <textarea> highlight overlay to the editor. The editing rules are in the DOM-free CodeEditingEngine, so a CodeMirror adapter could replace the widget only Data-driven polymorphism one Tokenizer class driven by a LanguageSpec object per language instead of 17 lexers Pure functions as strategy CodeEditingEngine.tab/enter/type/backspace/toggleComment take state and return new state, so they are tested with no DOM State machine encapsulation FullscreenController (idle → native-fullscreen or fallback → exit) and ImageResizer (pointer drag) own their lifecycles and dispose() their listeners Static utility class TableOps builds a grid (a spanning cell occupies several slots) before every operation"},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.4 Persistence","id":"44-persistence","text":"DocumentStore, EditorPrefsRepository, EditLock, AutosaveScheduler<T> (generic), LruCache<K,V> (generic) are small single-purpose classes composed in StoryTextEditor.tsx, the composition root of this feature, in the same style as lib/session/composition.ts."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5. OS concepts (as implemented)","id":"5-os-concepts-as-implemented","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.1 Scheduling, buffering, write coalescing","id":"51-scheduling-buffering-write-coalescing","text":"AutosaveScheduler is a debounced write-back buffer: a burst of keystrokes becomes one write 800 ms after the last, like OS page-cache write-back. flush() runs on pagehide and visibilitychange → hidden and on unmount, so the last keystrokes are not lost. Heavy work is deferred with timers: document sync is trailing-throttled to 180 ms, history records after 450 ms of quiet, resize handles use pointer events and ResizeObserver."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.2 Resources, limits, memory","id":"52-resources-limits-memory","text":"History is bounded (150 snapshots); LruCache (8 entries) keeps recently opened bodies; images are downscaled to ≤ 1600 px before storing; images > 12 MB are refused; storage quota failures raise StorageFullError instead of crashing. The fullscreen controller first uses the Fullscreen API without moving DOM. If it is denied, the root node is re-parented to <body> (a position: fixed element inside a transformed modal would not cover the viewport) and the selection is restored from the memento."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.3 Synchronisation and mutual exclusion","id":"53-synchronisation-and-mutual-exclusion","text":"EditLock is a lease lock: the holder renews a timestamp every lease/3; a crashed tab's lease expires, so the lock cannot deadlock. The second tab opens the document read-only. After the write it re-reads to detect a racing writer. (This is cooperative locking over localStorage, not a kernel mutex.) DocumentStore.save also uses optimistic versions (see §7) so even without the lock a stale tab gets VersionConflictError."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.4 Process/lifecycle","id":"54-processlifecycle","text":"Page lifecycle hooks (pagehide, visibilitychange) are used the way an OS uses shutdown hooks. Every long-lived object has dispose() (listeners, observers, locks)."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"6. CN (computer networks) concepts (as implemented)","id":"6-cn-computer-networks-concepts-as-implemented","text":"The editor is offline by design; it makes no network requests. The networking ideas that are in the code: Concept Where Untrusted input at a trust boundary pasted HTML, JSON-supplied HTML, imported files and even localStorage are parsed and sanitized (§8). Same stance as validating an HTTP request body URL / scheme handling isSafeUrl strips control characters inside the scheme (blocks java\\tscript:), then allows http/https/mailto/tel for links and http/https/data(image only)/sr-img for images. Links opened in a new tab get rel\"noopener noreferrer\" Media types (MIME) image type allow-list (png jpeg gif webp avif), data: URL parsing (RFC 2397 base64), correct export MIME types (application/vnd.openxmlformats-officedocument.wordprocessingml.document, text/markdown;charsetutf-8…) Content negotiation analogue paste prefers text/html, falls back to text/plain, handles Files — like choosing a representation from an Accept list Error detection crc32.ts is the IEEE CRC-32 used in each ZIP entry (same polynomial as Ethernet's FCS), checked against the standard test vector 123456789 → 0xCBF43926 Framing / binary container ZipWriter writes local headers, central directory and end-of-central-directory records byte by byte (little-endian) Character encoding UTF-8 via TextEncoder for ZIP names and parts; names flagged UTF-8 Content addressing / idempotency an image's id is a SHA-256 prefix of its bytes (sr-img:<hash>), so storing it twice is a no-op, like a content-addressed cache Download semantics Blob object URL download attribute, the client-side analogue of Content-Disposition: attachment Not implemented: no sockets, no server sync for documents, no retry/backoff (there is nothing remote to retry). The backend still accepts only paragraphs: string[]."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"7. DBMS concepts (as implemented)","id":"7-dbms-concepts-as-implemented","text":"DocumentStore is a tiny per-user database over the app's KeyValueStore (localStorage). It is not SQL and not crash-proof ACID; it applies the ideas that fit a key-value medium. Logical schema (per user namespace srt:v2:u:<user>:docs:…) Table (key) Row Notes index {id PK, title, words, updatedAt, version, bytes}[] small, read often (a covering index for the Documents menu) body:<id> RichDocumentSnapshot large, read on open. Split from index on purpose (normalisation / vertical partitioning), so listing never parses document bodies img:<hash> data URL content-addressed: natural de-duplication; n:m with bodies draft:<slot> snapshot write-ahead style recovery copy lock:<id> {owner, until} lease row (§5.3) prefs editor UI preferences Mechanisms Primary key / uniqueness: newId(); save replaces by id. Transaction with rollback: save writes body then index; if the index write fails (quota) the body is restored to its previous value. Tested. Optimistic concurrency: each row has version; save(id, doc, expected) throws VersionConflictError if it changed. Tested. Referential integrity / GC: collectGarbage() scans bodies and drafts for sr-img: references and deletes unreferenced images (reference counting by scan); remove() calls it. Tested. Consistency check (fsck): repair() drops index rows without a body. Tested. Caching: LruCache in front of body reads. Tenant isolation: the namespace prefix; the test proves a second user sees nothing (documents are isolated per user). Integrity constraints on read: stored snapshots are re-validated (fromSnapshot clamps margins, whitelists enums) and re-sanitized; a tampered localStorage value cannot inject script (tested). Normal form of content: documents are stored as sanitized HTML plus metadata; the typed Block model is derived (not stored twice), avoiding update anomalies. Limits: localStorage is ≈ 5 MB per origin and synchronous; there is no multi-statement durability guarantee if the browser dies mid-write."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"8. Security: the sanitizer is the trust boundary","id":"8-security-the-sanitizer-is-the-trust-boundary","text":"HTML can reach the editor from the JSON tab, paste, imports, shared stories and storage. It is later assigned to innerHTML, so HtmlSanitizer is a white-list: unknown tags are unwrapped; script style iframe object embed svg math form input … are removed with their content; attributes: only per-tag allow-list plus style/class/title/lang/dir and a fixed set of data- (no on ever survives); classes must match sr-; CSS: per-property validators; any value with url(, expression(, javascript:, @import, backslashes or <> is dropped; URLs: see §6; SVG data URLs are rejected; nesting deeper than 64 is flattened to text (stack-exhaustion guard); the result is idempotent (sanitize(sanitize(x)) sanitize(x), tested). Code blocks are stored as <pre data-lang><code>text</code></pre> with the text escaped, and are rebuilt from the textarea value on save, so code survives save / reopen / export (tested, including in a real browser)."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"9. Honest gaps and trade-offs","id":"9-honest-gaps-and-trade-offs","text":"1. No Monaco / CodeMirror. The package registry was unreachable in the build environment, so the code widget is hand-written (textarea over a highlighted <pre>). It is structured so CodeMirror 6 can replace CodeBlockWidget alone. 2. Code folding has no UI. CodeEditingEngine.foldRanges() computes brace/indent ranges (tested) but the widget does not render fold markers. Autocomplete is not implemented. 3. Page view is visual, not true pagination. It shows paper width, margins, page guide lines, header and footer once. Real per-page numbering and automatic page breaking happen only in the exported .docx / print output. 4. document.execCommand (deprecated but universal) does the inline formatting. Undo/redo is the editor's own snapshot history so widget and table changes undo correctly; caret restoration after undo is by text offset. 5. Find matches within a single text node, so a hit spanning bold/plain boundaries is missed. Find inside code blocks uses the widget's own bar (CtrlF in the block). 6. Tables: table-level border toggle and per-cell colour, but no column-width dragging or per-cell border styles. 7. Multilevel lists: nesting works; the editor shows the browser default markers, the .docx uses decimal / letter / roman by depth. 8. Equations are a LaTeX-lite → Unicode renderer, not a TeX engine. 9. Footnotes are numbered on insertion and not renumbered after deletion. 10. Images are stored in localStorage (downscaled); many large images will hit the quota (a clear error is shown). No cropping beyond centre aspect presets. 11. DOCX/PDF import is not supported. Import: .txt .md .html .json. PDF export uses the browser's print dialog. 12. Backend: the standalone API accepts only paragraphs: string[], so the rich snapshot stays on the device; the plain text is what a backend would receive. 13. Verification: logic is covered by npm run test:editor (40 tests, Node) and the DOCX was opened with LibreOffice and python-docx. The UI was exercised in headless Chromium (typing, undo, headings, code-block editing, table merge/split, image resize, fullscreen, find/replace, XSS paste, save/export). It was not tested in Firefox/Safari, and a full next build could not be run here (no dependency install possible), so run npm install && npm run build once."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"10. Running the tests","id":"10-running-the-tests","text":"npm run test:editor # model, sanitizer, exporters, code engine, store, lock, autosave npm run test:session # existing per-user session isolation (unchanged)"},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"11. Reader support (images, tables, code) and quiz-question input","id":"11-reader-support-images-tables-code-and-quiz-question-input","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"11.1 The reader now shows what you wrote","id":"111-the-reader-now-shows-what-you-wrote","text":"components/Reader/Reader.tsx renders a story written in the editor from its rich snapshot instead of flat paragraphs, so images, captions, tables, headings, lists, links and highlighted code blocks appear in the reading view. Stories without a snapshot (JSON stories, built-in stories) render exactly as before. StoryContentRenderer (lib/editor/reader/) is a pure class: sanitized HTML tree → resolve sr-img: references → syntax-highlight <pre> with the same Tokenizer the editor uses → drop neutral text/background colours → sanitize again → string. Nothing it produces can contain a tag, attribute, class, style or URL the allow-list forbids (tested with a hostile snapshot). createStoreImageResolver looks an image up in the active user's namespace first, then in any other user's row with the same content hash (so an adopted story keeps its pictures). Whatever it finds is re-validated as a base64 raster data URL; a tampered value becomes an \"Image unavailable\" note, never a javascript:/SVG source. Black/white/grey text colours are removed in the reader so author-chosen black text cannot disappear on the dark theme; chromatic colours (red, blue …) are kept. The reading engine is untouched: progress is time-based and the scroll position is derived from the live track height (ResizeObserver), so taller content such as images needs no engine change. The \"paragraph x of N\" label counts the plain paragraphs (code text and captions included). The snapshot is used only while it still matches story.story (richDocFor), so text edited elsewhere (for example the JSON tab) is always what the reader shows. GC fix: DocumentStore.collectGarbage() now scans the user's whole namespace, including saved stories, so an image used by a story is never deleted when its editor draft or document is removed (tested). Images live in browser storage per user; a story JSON copied to another browser does not carry its images (they show as \"Image unavailable\")."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"11.2 Adding quiz questions: one by one or JSON / file","id":"112-adding-quiz-questions-one-by-one-or-json-file","text":"components/Search/QuestionsInput.tsx is used by both Add story and Edit story (media stories keep their existing flow). A toggle switches between: One by one — question, options (add/remove), correct-answer radio, explanation, delete question. JSON / file — type or paste JSON, drop a .json/.txt file onto the box, or use Load file; Insert example gives a template. Both views edit the same list, so you can paste 30 questions, switch to \"One by one\" and fix one, and switch back; edits show up in the JSON. The JSON pane is live: valid JSON replaces the list immediately; invalid JSON keeps the last good list, shows what is wrong by question number, and disables Add story / blocks Save until fixed. Accepted JSON (lib/questionImport.ts, tested): an array, { \"questions\": [...] } (so a whole story JSON works), or a single question; optionally inside a json fence. Per question: question (q, text), options (choices, answers; 2–12, no blanks or duplicates), correctAnswer (answer, correct, correctIndex, correctOption) and explanation (explain, rationale). The answer may be a 0-based number, a letter (\"B\") or the exact option text; anything else is reported, never guessed. Limits: 200 questions, 1 MB file. The existing story validation still requires at least one question for a text story."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"12. Code in the reader: IDE-style formatting","id":"12-code-in-the-reader-ide-style-formatting","text":"Every code snippet is shown on its own lines with indentation kept, highlighted, in a scrollable block (white-space: pre, 4-wide tabs, no ligatures, no inherited letter-spacing). Editor code blocks: dedented, language guessed if \"plaintext\", and code whose line breaks were lost (one long line) is re-flowed by beautifyIfCollapsed (brace languages and JSON; strings and comments are never touched; code that already has several lines is never rewritten). Stories without a rich snapshot (JSON, PDF, old saves): plainStoryToHtml finds fences and multi-line paragraphs that look like code (looksLikeCode, a conservative line-scoring heuristic) and renders them the same way. Other multi-line prose keeps its line breaks. Stories with no code keep the original plain layout. Code lives in lib/editor/code/CodeHeuristics.ts, lib/editor/reader/CodeFormatter.ts, lib/editor/reader/plainStoryHtml.ts; 6 tests cover it."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"13. One-click \"Format code\"","id":"13-one-click-format-code","text":"Each code block has a { } button (and ShiftAltF inside the block) that formats the whole block in its language. If the block is plain text, the language is guessed first and the block switches to it. CtrlZ undoes a format. lib/editor/code/formatCode.ts (Strategy pattern, one strategy per language family): JSON: parse and pretty-print (invalid JSON falls back to bracket indentation). HTML: tag-depth layout; <script> / <style> bodies are formatted as JS / CSS; <pre> / <textarea> stay untouched. Python: indentation levels are re-derived and re-emitted with the chosen indent (tabs and mixed widths fixed). Lines are never joined or split, because indentation is Python's meaning. SQL: keywords upper-cased, one clause per line, one column per line, AND/OR indented. Bash: if/fi, do/done, case/esac, { } blocks. JS, TS, Java, C, C, C#, Go, Rust, PHP, CSS and anything else: re-indent by bracket depth; a single collapsed line is split into statements first. Strings and comments are never changed (decided by the language Tokenizer). Formatting is idempotent, and on any internal error the original code is kept. Uses the block's indent setting (2 / 4 / tab). Also fixed: unterminated-string/comment matching in the Tokenizer used $ with the multiline flag, which ended triple-quoted strings at the first line; Python ''' strings are now recognised."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"13.1 Code whose line breaks were lost","id":"131-code-whose-line-breaks-were-lost","text":"The ✦ Format button sits right next to the language selector. Code pasted or saved as a single line usually keeps the old indentation as a run of 2 spaces where each newline was. splitOnWideGaps turns those gaps back into line breaks (after ;, {, } and after a // comment; also ;}), never inside strings, and the result is then re-indented. If the block is \"Plain text\" and looks like C-family code (typed declarations, generics, braces), it is detected as Java. The reader uses the same logic for one-line code."},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"Time analysis (profile → Time spent)","id":"","text":""},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"Time analysis (profile → Time spent)","id":"","text":"How much time a person spends reading and testing, story by story and page by page. It is built on the per-user session layer described in OOPARCHITECTURE.md, so every number belongs to exactly one user and nothing leaks between accounts."},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"What the profile shows","id":"what-the-profile-shows","text":"Where What Five cards Total time, reading time, testing time, documentation time, number of stories Documentation, page by page Every documentation page you opened: time spent, visits and last visit, longest first Story by story Reading time, test time, sessions, last activity, and a bar splitting reading from testing Open a story Page-by-page bars (about 250 words per page, or the real page of an uploaded PDF or image story) with the longest page in red The tab is Profile → Time spent, next to Analytics."},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"What is recorded, and when","id":"what-is-recorded-and-when","text":"Event Written by Recorded Reading in reading mode (the story page and /read) ReadingModePage Real visible reading time, plus time per page. Saved when you press Finished, or when you leave the page Reading with the auto-scroll reader app/reader/page.tsx Total time (minus breaks) when the story completes. No page detail, because the page scrolls by itself A test app/results/page.tsx The whole test duration, once per result A documentation page DocTimeTracker on every docs page Time with the page visible and some activity in the last 2 minutes, saved when you leave, hide the tab or close it; visits under 3 seconds are ignored Rules that keep the numbers honest: Only real time. The clock stops while the tab is hidden or while the article is not on screen. Page under the reading line. Every 250 ms the elapsed slice is added to the page at 40% of the viewport height, the same reading line the progress bar uses. Short visits are dropped. A reading under 3 seconds is not logged, so opening and closing a story does not pollute the totals. Saved once. A flag guards the save, so Finished followed by the page unmounting does not count twice."},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"Documentation needs a sign-in","id":"documentation-needs-a-sign-in","text":"The notes and docs pages (the ones a QR code opens) are no longer public: anyone who opens them signs in first, and then sees the page. That is what lets documentation reading be attributed to a person. The pages keep their own header and footer; only the login gate changed (DevLoginGate)."},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"Class diagram","id":"class-diagram","text":"classDiagram class UserScopedRepositoryT { <<abstract>> #feature() string #emptyValue() T #read() T #write(value) } class TimeLogRepository { getAll() StoryTimeRecord[] find(storyId) StoryTimeRecord recordReading(storyId, title, ms, pageMs) recordTest(storyId, title, ms) } class StoryTimeRecord { <<value object>> withReading(ms, pageMs) StoryTimeRecord withTest(ms) StoryTimeRecord slowestPage() number toJSON() StoryTimeData } class TimeSummaryCalculator { compute(records) TimeSummary } class UserSession { timeLog TimeLogRepository timeSummary() TimeSummary } class PageDwellTracker { tick(index, dtMs) snapshot() number[] reset() } UserScopedRepository < -- TimeLogRepository TimeLogRepository --> StoryTimeRecord : stores UserSession -- TimeLogRepository UserSession ..> TimeSummaryCalculator : uses PageDwellTracker ..> TimeLogRepository : snapshot saved through storage facade"},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"OOP principles, where they show up","id":"oop-principles-where-they-show-up","text":"Principle Where Encapsulation StoryTimeRecord hides its data behind getters; TimeLogRepository is the only code that reads or writes the stored JSON Abstraction The UI asks session.timeSummary() and timeLog.getAll(), never for keys or JSON Inheritance TimeLogRepository extends UserScopedRepository, so key building, safe parsing and fall-backs come from the base Polymorphism UserSession.clearAllData() clears the time log with the others through the shared base type Composition UserSession composes the repository and the calculator; both can be swapped in tests Immutability StoryTimeRecord.with… returns a new record, so a stored row can never change under a caller Single responsibility The tracker only counts, the record only merges, the repository only stores, the calculator only sums, the panel only draws export class TimeLogRepository extends UserScopedRepository<Record<string, StoryTimeData>> { static readonly MINMS 3000; protected feature(): string { return \"timelog\"; } recordReading(storyId: string, title: string, ms: number, pageMs: readonly number[] []): void { if (ms < TimeLogRepository.MINMS) return; // ignore accidental opens this.save((this.find(storyId) ?? StoryTimeRecord.empty(storyId, title)).withReading(ms, pageMs, title)); } } export function pageIndexAt(y: number, starts: number[]): number { if (starts.length 0) return 0; let lo 0; let hi starts.length - 1; while (lo < hi) { const mid (lo hi 1) >> 1; if (starts[mid] < y) lo mid; else hi mid - 1; } return lo; }"},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"Files","id":"files","text":"File Role lib/readingMode/PageDwellTracker.ts paginate, pageIndexAt, PageDwellTracker lib/session/analytics/StoryTimeRecord.ts Immutable per-story record lib/session/repositories/TimeLogRepository.ts Per-user storage (timelog slot) lib/session/analytics/DocTimeRecord.ts, lib/session/repositories/DocTimeRepository.ts Time per documentation page (doctime slot) components/Notes/DocTimeTracker.tsx Measures real reading time on a docs page lib/session/analytics/TimeSummaryCalculator.ts Totals, documentation included lib/session/UserSession.ts Composes the repository; timeSummary() lib/storage.ts Facade methods recordStoryReading, recordStoryTest components/Profile/TimeAnalysisPanel.tsx The Time spent tab scripts/timelog.test.ts Tests (npm run test:timelog)"},{"slug":"time_analysis","title":"Time analysis (profile → Time spent)","folder":"","heading":"Limits","id":"limits","text":"Data lives in this browser's storage, like the rest of the session layer. Another device does not see it until there is a backend. The auto-scroll reader records a total only. Page boundaries follow word counts, so changing the text size does not change which words belong to a page."},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"01 · JavaScript & TypeScript","id":"","text":""},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"01 · JavaScript & TypeScript","id":"","text":""},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"Easy","id":"easy","text":"1. var vs let vs const? var is function-scoped and hoisted (initialised undefined); let/const are block-scoped with a temporal dead zone. const forbids rebinding, not mutation. 2. vs ? coerces types; doesn't. Use ; the one idiom for is x null. 3. What is a closure? A function plus the variables of the scope it was created in. Used for private state, memoisation, debouncing. Here: useInertiaScroll keeps target in a closure shared by the wheel/key handlers. 4. map / filter / reduce? Pure array transforms returning new values; forEach returns nothing. 5. null vs undefined? undefined never assigned; null intentionally empty. 6. TS: interface vs type? Both describe shapes; interfaces merge and extend, types do unions/intersections/mapped types."},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"Medium","id":"medium","text":"1. Explain the event loop. Call stack → microtask queue (promises, queueMicrotask) drained fully → one macrotask (timers, I/O, events) → render → repeat. await continues as a microtask. Consequence: a never-ending microtask chain starves rendering. 2. How does this work? Determined by call-site: method call, call/apply/bind, new, default (undefined in strict mode). Arrow functions capture lexical this. 3. Debounce vs throttle — implement debounce. const debounce <A extends unknown[]>(fn: (...a: A) > void, ms: number) > { let t: ReturnType<typeof setTimeout>; return (...a: A) > { clearTimeout(t); t setTimeout(() > fn(...a), ms); }; }; 4. Promise combinators. all (fails fast), allSettled (never rejects), race (first to settle), any (first to fulfil). Know which to use for \"load all or fail\" vs \"best effort\". 5. Prototype chain & class. Classes are syntax over prototypes; method lookup walks proto. Here: the editor engine and backend classes use ES classes — see docs/OOPARCHITECTURE.md. 6. TS generics & narrowing. Discriminated unions exhaustive switch with a never check. Here: ReadingContext actions are a discriminated union on type. 7. Why does TS narrow let x: T null null to null? Control-flow analysis sees only the assignment, not closure writes — cast null as T null (fixed in formatCode.ts)."},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"Hard","id":"hard","text":"1. Implement Promise.all / a promise pool with concurrency N. Maintain an index and N workers each pulling the next task; resolve when all settle; keep result order by index. 2. Memory leaks in SPAs. Detached DOM nodes, un-removed listeners/intervals, closures holding big objects, unbounded caches. Detect: heap snapshots, \"detached\" filter. Here: every useEffect that adds a listener/requestAnimationFrame returns a cleanup. 3. Deep clone / deep equal edge cases. Cycles (WeakMap), Dates, Maps/Sets, property descriptors, structuredClone limits (no functions). 4. TS advanced types. Build DeepReadonly<T>, Pick-by-value-type, a typed EventEmitter<Events>; explain variance, infer, template-literal types. 5. Module systems. ESM (static, live bindings, tree-shakable) vs CJS (dynamic, copies); dual-package hazards; why Next needs \"use client\" boundaries. 6. Design an undo/redo stack for a rich-text editor. Command pattern coalescing of typing bursts selection snapshots. Here: the dependency-free editor in lib/editor/."},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"02 · React","id":"","text":""},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"02 · React","id":"","text":""},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"Easy","id":"easy","text":"1. Props vs state? Props flow down and are read-only; state is owned by a component and triggers re-render when changed. 2. Why key in lists? Stable identity so reconciliation reuses/moves the right DOM state. Never use array index for reorderable lists. 3. Controlled vs uncontrolled inputs? Controlled: value in state. Uncontrolled: DOM owns it, read via ref. 4. useEffect dependency array? Re-run when deps change; [] mount/unmount only. Return a cleanup. 5. What is lifting state up? Move shared state to the nearest common parent."},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"Medium","id":"medium","text":"1. useMemo / useCallback — when? Only for referential stability to memoised children/effects or expensive computation. Measure first; they cost memory and complexity. 2. useReducer vs useState? Reducer for related transitions and testable logic. Here: ReadingContext is a reducer (SETREADINGMODE is ignored during reading/completed — a business rule living in one place). 3. Context pitfalls? Every consumer re-renders when the value changes. Split state/dispatch contexts (done here: useReadingState / useReadingDispatch), memoise values, or use selector libraries. 4. Why do effects run twice in dev? StrictMode double-invokes mount/unmount to expose missing cleanups. Fix the effect, don't remove StrictMode. 5. Stale closure bug? Handler captured an old state value. Fix with functional updates (setN(n > n1)), refs, or correct deps. 6. Hydration mismatch causes? Different server/client output (Date.now, window, localStorage). Read browser-only data in useEffect. Here: PlatformShowcase loads history in an effect, not during render. 7. Error boundaries? Class/error.tsx catch render errors in the subtree (not event handlers or async). See app/error.tsx."},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"Hard","id":"hard","text":"1. Explain reconciliation, Fiber and concurrent rendering. Fiber makes work interruptible; transitions mark updates low-priority; useDeferredValue/startTransition keep input responsive; renders must be pure because they can be repeated/abandoned. 2. Optimise a 10k-row list. Virtualise (windowing), memoise rows, stable keys, avoid inline object props, move state down, batch updates, use content-visibility. 3. Design a custom hook that drives a rAF loop safely. Keep mutable state in refs, one requestAnimationFrame chain, cancel on unmount, respect prefers-reduced-motion, pause when hidden. Here: useInertiaScroll, useReadingEngine. 4. Server Components vs Client Components. RSC render on server, ship no JS, can't use state/effects; client components hydrate. Push \"use client\" to the leaves; pass server data down as props. 5. State management at scale. Server cache (React Query/SWR) vs UI state vs URL state vs form state; avoid one global store for everything. 6. Accessible custom widget. Roles, keyboard map, focus management/trapping, aria-live; Here: the scroll rail uses buttons with labels; the carousel buttons have aria-labels and disabled states."},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"03 · Next.js & Web Platform","id":"","text":""},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"03 · Next.js & Web Platform","id":"","text":""},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"Easy","id":"easy","text":"1. App Router vs Pages Router? app/ uses nested layouts, Server Components by default, loading/error/not-found conventions; pages/ uses getServerSideProps etc. 2. What is \"use client\"? Marks a module (and its imports) as part of the client bundle; needed for hooks, browser APIs, event handlers. 3. CSS box model; position values? content/padding/border/margin; static, relative, absolute, fixed, sticky. 4. Flexbox vs Grid? Flex one dimension; Grid two. 5. What does next build do? Compiles, type-checks, statically renders what it can, emits .next."},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"Medium","id":"medium","text":"1. Why does importing plain .css in a component error? Next.js only allows global (non-module) CSS to be imported from the root layout (and app in Pages). Anywhere else the build rejects it to keep global CSS order predictable. Fixes: (a) import in app/layout.tsx (what this project does, in a fixed order after globals.css), (b) use .module.css, (c) Tailwind utilities. Rule here: components never import .css. 2. Rendering modes. SSG, SSR, ISR, CSR, streaming; when to pick each (SEO freshness cost). 3. Data fetching & caching in App Router. fetch caching, revalidate, cache: \"no-store\", route segment config, revalidatePath/Tag. 4. Core Web Vitals. LCP (largest image/text — preload hero, optimise fonts), INP (long tasks — split work, startTransition), CLS (reserve space for images/fonts). 5. Specificity & stacking contexts. Here: a positioned footer painted over a fixed page with no in-flow content, hiding /reader; fix was to not render the footer on that route. 6. Tailwind pros/cons. Design tokens via CSS variables (rgb(var(--ink))) enable three themes without duplicating classes; purge keeps CSS small; drawback: long class strings → extract components. 7. env handling. Only NEXTPUBLIC reaches the browser and is inlined at build time; server secrets never get that prefix."},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"Hard","id":"hard","text":"1. Walk through what happens from typing a URL to pixels. DNS, TCP/TLS, HTTP/2-3, HTML parse, preload scanner, CSSOMDOM → render tree → layout → paint → composite; JS blocks parsing unless async/defer/module. 2. Make a marketing page score 95 on Lighthouse. Self-host/subset fonts with font-display, next/image, lazy below-the-fold video (preload\"none\"/IntersectionObserver), avoid layout shift, defer third-party scripts, cache headers (see next.config.js). 3. Build smooth inertia scrolling without hijacking everything. Move a target on wheel/keys, ease real scrollTop with rAF lerp, step aside for inner scrollers, fixed overlays, dialogs, touch, reduced motion. Here: useInertiaScroll. 4. CSP, CORS and security headers. Know what each blocks; why Permissions-Policy: microphone(self) is needed for voice search; trade-offs of inline styles with CSP. 5. Hydration & streaming deep dive. Suspense boundaries stream HTML; selective hydration prioritises interacted regions; why browser-only reads belong in effects. 6. Migrate a large CSS codebase safely. Codemods, visual regression tests, strangler approach, tokenise colours first."},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"04 · Data Structures & Algorithms","id":"","text":""},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"04 · Data Structures & Algorithms","id":"","text":"Target pace at this level: Easy ≤ 10 min, Medium ≤ 25 min, Hard ≤ 40 min, always stating complexity and edge cases. Pattern > problem count."},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Easy","id":"easy","text":"Problem Pattern Key idea Two Sum Hash map store value→index, one pass, O(n) Valid Parentheses Stack push open, match on close Merge Two Sorted Lists Two pointers dummy head Best Time to Buy/Sell Stock Running min one pass Binary Search Binary search lo<hi, avoid overflow Reverse Linked List Pointers prev/curr/next Valid Anagram / Palindrome Counting / two pointers Maximum Depth of Binary Tree DFS recursion"},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Medium","id":"medium","text":"Problem Pattern Key idea Longest Substring Without Repeating Sliding window map char→last index 3Sum Sort two pointers skip duplicates Group Anagrams Hashing sorted key / count tuple Top K Frequent Elements Heap / bucket O(n log k) or O(n) Number of Islands BFS/DFS / DSU grid flood fill Course Schedule Topological sort Kahn's / DFS colours LRU Cache Hash map doubly linked list O(1) get/put Merge Intervals Sort sweep Kth Largest in Array Quickselect / heap avg O(n) Coin Change 1-D DP dp[a]min(dp[a-c]1) Word Break DP trie/set Lowest Common Ancestor Tree recursion Rotting Oranges Multi-source BFS"},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Hard","id":"hard","text":"Problem Pattern Key idea Median of Two Sorted Arrays Binary search on partition O(log min(m,n)) Trapping Rain Water Two pointers / monotonic stack Sliding Window Maximum Monotonic deque O(n) Merge K Sorted Lists Heap O(N log k) Word Ladder BFS (bidirectional) Edit Distance 2-D DP Longest Increasing Subsequence DP patience sort O(n log n) Serialize/Deserialize Binary Tree Preorder markers Alien Dictionary Graph topo sort Minimum Window Substring Sliding window counts Dijkstra / Network Delay Time Heap graph Design a Text Editor / Autocomplete Trie heap"},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Project-flavoured problems (talk about these from real code)","id":"project-flavoured-problems-talk-about-these-from-real-code","text":"Tokenizer (lib/editor/code/Tokenizer.ts): a spec-driven lexer whose tokens concatenate back to the source — prove it with a property test (join(tokens) source). Code formatter (formatCode.ts): bracket-depth indentation with a stack of per-line open counts; idempotent (format(format(x)) format(x)) and never touches strings/comments. Sliding window / interpolation: easeToward is an exponential lerp: x (target-x) (1 - e^(-k·dt)) — frame-rate independent. Reading time & WPM: wpmFromElapsed(words, ms); edge cases: zero elapsed, finishing early, clamping."},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Complexity cheat-sheet","id":"complexity-cheat-sheet","text":"Array access O(1) · hash avg O(1) · balanced BST O(log n) · heap push/pop O(log n) · sort O(n log n) · BFS/DFS O(VE) · Dijkstra O((VE) log V)."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"05 · System Design","id":"","text":""},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"05 · System Design","id":"","text":"Framework (use every time): requirements → estimates → API → data model → high-level design → deep dives → bottlenecks/failure modes → trade-offs."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Easy (components and vocabulary)","id":"easy-components-and-vocabulary","text":"1. Load balancer? Spreads traffic (L4/L7), health-checks, enables rolling deploys. 2. Cache — where and why? Browser, CDN, app (Redis), DB buffer. Cuts latency/load; costs staleness. 3. SQL vs NoSQL? Relations/transactions vs flexible schema/horizontal scale; choose by access patterns. 4. What is a CDN? Edge cache for static assets and videos (this project's landing video). 5. Horizontal vs vertical scaling?"},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Medium","id":"medium","text":"1. Design a URL shortener. Base62 of a counter/ID service; read-heavy → cache; 301 vs 302; abuse limits. 2. Design a rate limiter. Token bucket in Redis (atomic Lua), per-user/IP keys, headers Retry-After; distributed clock caveats. 3. Design a notification system. Producer → queue (Kafka/SQS) → workers per channel; idempotency keys; retries with backoff DLQ; user preferences. 4. Design this Speed Reader platform. Stories (CRUD, tags, thumbnails), per-user sessions/history, quizzes, comments/likes. Postgres Prisma, object storage (S3) for PDFs/images, CDN, Redis for hot lists, search via Postgres FTS → OpenSearch later. Frontend: Next.js; session isolation per user (SessionBoundary remounts on user change). 5. Pagination. Offset vs keyset (cursor); why keyset scales and stays stable under inserts. 6. Design a comment system with replies/likes. Adjacency list depth, denormalised counters with async reconciliation."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Hard","id":"hard","text":"1. Design Google Docs / collaborative editor. OT vs CRDT; operation log, presence, cursors, offline merge, snapshots compaction, permissions; WebSocket fan-out by document shard. (Relevant to \"teams and shared notes\" on this roadmap.) 2. Design YouTube/Netflix streaming. Upload → transcode ladder (HLS/DASH) → segments on object store → CDN; adaptive bitrate; recommendation as a separate pipeline. 3. Design a ride-dispatch system (your DispatchHub project). Geo-index (H3/geohash), matching with batching windows, supply/demand surge, at-least-once events with idempotent consumers. 4. Design a global feed ranking. Candidate generation → ranking → re-ranking; fan-out on write vs read; hot-key (celebrity) handling. 5. Design a payments system. Idempotency keys, double-entry ledger, sagas, reconciliation, exactly-once effects via outbox. 6. Multi-region active-active. Conflict resolution, data residency, failover drills, consistency levels (PACELC)."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Cross-cutting talking points","id":"cross-cutting-talking-points","text":"CAP/PACELC, consistency models, idempotency, backpressure, circuit breakers, observability (RED/USE metrics, tracing), SLOs and error budgets, capacity maths (QPS DAU × actions / 86 400, ×3–5 for peak)."},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"06 · Backend, APIs & Databases","id":"","text":""},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"06 · Backend, APIs & Databases","id":"","text":""},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"Easy","id":"easy","text":"1. REST verbs/status codes? GET/POST/PUT/PATCH/DELETE; 200/201/204, 400/401/403/404/409/422, 429, 500/503. 2. PUT vs PATCH? Idempotency? PUT replaces (idempotent); PATCH partial (may not be). 3. Primary key vs foreign key vs unique? 4. SQL joins. INNER, LEFT, RIGHT, FULL; know what each returns on missing matches. 5. What is middleware in Express? Functions in the request pipeline: parse, auth, validate, error handler last."},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"Medium","id":"medium","text":"1. Index design. B-tree on filtersort columns; composite order equality first, then range/sort; covering indexes; cost on writes. Read EXPLAIN ANALYZE. 2. Transactions & isolation. ACID; read committed vs repeatable read vs serializable; phantom reads; lost update → SELECT … FOR UPDATE or optimistic version column. 3. N1 queries. Prisma include/select, IN batching, DataLoader. 4. Validation & error handling. Schema-validate at the edge (Zod), map domain errors to codes, never leak stack traces, central error middleware. 5. Pagination & filtering API. Cursor tokens, stable sort keys, max page size. 6. File uploads. Presigned URLs straight to object storage; validate type/size; scan; thumbnails async. Here: thumbnails are validated/sanitised by safeThumbnail on the client; the backend must re-validate. 7. Migrations. Expand → migrate → contract; never drop a column in the same release that stops using it."},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"Hard","id":"hard","text":"1. Zero-downtime schema change on a 500M-row table. Online DDL, shadow table dual writes backfill cutover, feature flags. 2. Distributed transaction without 2PC. Saga (choreography vs orchestration), outbox pattern, idempotent consumers. 3. Exactly-once? Impossible end-to-end; at-least-once idempotency keys dedupe tables. 4. Caching strategies & invalidation. Cache-aside, write-through, stampede protection (single-flight, jittered TTL), versioned keys. 5. Hot-row contention / counters. Sharded counters, Redis INCR periodic flush, CRDT counters. 6. Query tuning case. Slow ORDER BY createdat LIMIT 20 with a filter: composite index (userid, createdat DESC), avoid OFFSET, check plan for sort node. 7. Node performance. Event loop blocking (CPU work → worker threads), streaming big responses, connection pooling (PgBouncer), graceful shutdown (SIGTERM drain)."},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"07 · Auth & Security","id":"","text":""},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"07 · Auth & Security","id":"","text":""},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"Easy","id":"easy","text":"1. Authentication vs authorisation? 2. Hashing vs encryption? Hashing is one-way (use bcrypt/argon2 with salt); encryption is reversible. 3. What is XSS / CSRF / SQL injection? Script injection into pages / forged cross-site requests using the user's cookies / unsanitised input in queries (use parameterised queries). 4. HTTPS why? Confidentiality, integrity, server authentication."},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"Medium","id":"medium","text":"1. Session cookies vs JWT. Cookies (HttpOnly, Secure, SameSite) server session easy revocation; JWT stateless but hard to revoke → short-lived access token rotating refresh token. 2. Refresh-token rotation & reuse detection. Issue new refresh on use, invalidate old; if an old one reappears, revoke the whole family. 3. OAuth 2.0 / OIDC (Google, Apple, Facebook). Authorization Code PKCE; validate state, nonce, ID-token signature/audience; link accounts by verified email. 4. OTP login. Hash OTPs, short TTL, attempt limits, per-identity per-IP rate limits, constant-time compare. 5. Sanitising rich text. Allow-list sanitiser, never dangerouslySetInnerHTML unsanitised. Here: the editor has its own sanitiser and safeThumbnail blocks non-image data URLs. 6. Per-user data isolation on the client. Here: lib/session namespaces storage per user and SessionBoundary remounts the tree on user change, tested in test:session."},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"Hard","id":"hard","text":"1. Threat-model a login file-upload service (STRIDE). Brute force, credential stuffing, token theft, SSRF via URL fetch, zip bombs, content-type confusion, path traversal. 2. Design secure password reset. Single-use hashed tokens, expiry, no user enumeration, invalidate sessions after reset. 3. Where do you store tokens in an SPA? Memory HttpOnly refresh cookie beats localStorage (XSS-readable). Discuss BFF pattern. 4. CSP design. Nonce-based script-src, frame-ancestors, report-only rollout. 5. Supply-chain security. Lockfiles, npm ci, provenance, Dependabot, pin CI actions, least-privilege tokens. 6. Secrets management & rotation. Vault/KMS, no secrets in the repo (.gitignore excludes .env), short-lived credentials."},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"08 · Testing, CI/CD & Deployment","id":"","text":""},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"08 · Testing, CI/CD & Deployment","id":"","text":""},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Easy","id":"easy","text":"1. Unit vs integration vs e2e? Many fast unit tests, fewer integration, few e2e (test pyramid). 2. What makes a test good? Deterministic, isolated, fast, tests behaviour not implementation. 3. What is CI/CD?"},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Medium","id":"medium","text":"1. How is this repo tested? npm run test:editor (55 tests: tokenizer, formatter idempotency, sanitiser, reading-mode clock) and npm run test:session (21 tests: per-user isolation). Run with npm test. 2. Property-based / invariant tests. Tokens re-concatenate to source; formatter is idempotent; wpm recalculation matches elapsed time. 3. Mocking strategy. Mock at boundaries (network, time), not internals; fake timers for debounce/rAF. 4. Environment config. Build-time NEXTPUBLIC vs runtime server env; one image, many environments requires runtime config for server values only. 5. Docker multi-stage builds. Deps → build → slim runtime, non-root user, healthcheck (see Dockerfile)."},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Hard","id":"hard","text":"1. Zero-downtime deploys. Rolling/blue-green/canary, readiness probes, connection draining, backwards-compatible DB migrations. 2. Feature flags & safe rollout. Percentage rollouts, kill switch, cleanup debt. 3. Observability. Structured logs with request IDs, RED metrics, distributed tracing, frontend RUM (web-vitals), source maps in Sentry, alert on SLO burn rate not raw errors. 4. Rollback strategy. Immutable artefacts, DB expand/contract so N-1 still works, automated smoke test after deploy. 5. Testing flaky e2e. Network isolation, stable selectors (roles/labels), waiting on conditions not timeouts, quarantine owner. 6. Performance budget in CI. Lighthouse CI, bundle-size limits, fail the PR on regression."},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Release checklist for this project","id":"release-checklist-for-this-project","text":"npm ci → npm run typecheck → npm test → npm run lint → npm run build → smoke npm start → verify /, /dashboard, /reader, /read load. See docs/DEPLOYMENT.md."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"09 · Behavioral & Project Walkthrough","id":"","text":""},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"09 · Behavioral & Project Walkthrough","id":"","text":"At this level, behavioral rounds can veto an otherwise strong loop. Use STAR, lead with the result, quantify, and show judgement under ambiguity."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Easy","id":"easy","text":"1. Tell me about yourself (90 seconds: who you are → what you built → what you want next). 2. Why this company/role? 3. Your favourite project and why."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Medium","id":"medium","text":"1. Walk through Speed Reader end to end. Problem (people read slowly and retain little) → solution (timed reader quiz analytics) → architecture (Next.js 14, per-user session layer, dependency-free rich editor, Express/Prisma backend) → hard problems → results. 2. Hardest technical problem. E.g. the code formatter: language-agnostic, idempotent, never alters strings/comments, handles collapsed single-line code; or inertia scrolling that yields to inner scrollers. 3. Disagreement with a teammate. Data first, disagree-and-commit, outcome. 4. A bug you shipped. Own it; root cause (e.g. footer painting over a fixed page); prevention (route-level guard test). 5. Prioritisation with deadlines (hackathons: DispatchHub, CredMatch)."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Hard","id":"hard","text":"1. A time you changed direction mid-project. E.g. rolled back the paste-as-code change when it caused regressions; how you decided and communicated. 2. Led without authority / mentored. 3. Made a decision with incomplete data and it was wrong. 4. Ownership beyond scope (set up CI/Docker, docs, tests no one asked for). 5. Raise the bar: how you'd improve engineering quality on a team — review standards, tests, docs, on-call hygiene."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Project talking points (be ready to go 3 levels deep)","id":"project-talking-points-be-ready-to-go-3-levels-deep","text":"Per-user isolation: namespaced storage remount boundary; tested adoption of legacy keys. Editor: own tokenizer/sanitiser/code widget; why not a library (bundle size, control), what you'd reconsider (CRDT collaboration). Reading mode: real-time clock independent of scroll, WPM recalculated on early finish, rail of ≤5 ticks. Trade-offs you accepted: localStorage-first persistence, backend optional (NEXTPUBLICAPIURL empty standalone). What you'd do next: real teams/shared docs (OT/CRDT), server-side search, e2e tests, a11y audit."},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"10 · 8-Week Study Plan & Level Rubric","id":"","text":""},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"10 · 8-Week Study Plan & Level Rubric","id":"","text":"Week Focus Output 1 JS/TS internals, event loop, async 30 JS questions 5 utility implementations 2 DSA: arrays, hashing, two pointers, sliding window, stack 40 problems (15 E / 20 M / 5 H) 3 DSA: trees, graphs, heaps, binary search 40 problems 4 DSA: DP, backtracking, tries mock interview ×2 30 problems 5 React Next.js deep dive, perf, a11y Build/profile one feature, write a perf note 6 System design ×6 (shortener, rate limiter, notifications, feed, chat, docs) One-page design each 7 Backend/DB/security, deployment Write an ADR for this project's deploy 8 Behavioral stories, mocks, revise weak spots 8 STAR stories; 3 full mock loops"},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"Daily rhythm","id":"daily-rhythm","text":"60–90 min DSA · 30 min fundamentals · 30 min design reading · 15 min recall of yesterday's mistakes."},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"How levels are judged (typical)","id":"how-levels-are-judged-typical","text":"Easy questions: must be fast and flawless; hesitation here costs the offer. Medium: clean solution, correct complexity, tests edge cases unprompted. Hard / design: structure, trade-offs, failure modes, and clear communication; a partially optimal solution well explained beats a silent perfect one. Senior signal: you ask clarifying questions, quantify, choose boring technology on purpose, and say what you would monitor."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","id":"","text":""},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","id":"","text":"Questions an interviewer at the ₹2.5 Cr band could ask about this change set. Cover the answer first."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"Easy","id":"easy","text":"1. Why a routes.ts constant instead of string literals? One place to change/grep, typed helpers (story(id)), no dead links. 2. Why /story/[id] rather than state-only? Refresh, share and back-button work; the URL is the source of truth. 3. Why downscale an avatar before storing? localStorage is 5 MB and synchronous; 256px JPEG ≈ 15 KB."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"Medium","id":"medium","text":"4. A user saw someone else as the \"owner\" of their upload — root cause? Authorship was a hash of the content id. Fix: derive it from where the data lives (the uploader's library) with the hash only as a fallback for built-ins. 5. Why inject the owner resolver? contentMeta ← store ← session: importing session from contentMeta creates a cycle. Dependency inversion keeps modules acyclic and testable. 6. Edit modal reuse — trade-offs? Shared form parts remove drift; the cost is coupling both modals to one layout. Keep parts presentational. 7. Validate image uploads how? MIME size check client-side, re-encode through canvas (strips payloads), render only data URLs matching our own format (safeAvatar)."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"Hard","id":"hard","text":"8. Move this to production — what changes? authorId becomes a DB foreign key set server-side from the session (never client-supplied); avatars go to object storage CDN with signed uploads; authorization checked on every mutation. 9. IDOR on edit/delete? Client gating (isCustomStory) is UX only; the API must verify story.ownerId session.userId. 10. Two tabs edit the same story — what happens? Last write wins today; fix with a version/ETag and optimistic concurrency (409 → merge UI). 11. Orphaned media (cover videos in IndexedDB)? Delete on replace/delete only after the save commits; a periodic sweep removes refs no story holds."},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"12 · System Design: Google Docs","id":"","text":""},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"12 · System Design: Google Docs","id":"","text":"The question: design an online collaborative document editor (real-time co-editing, like Google Docs). Full question and walkthrough on Educative: System Design: Google Docs"},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"Overview — key points of the question","id":"overview-key-points-of-the-question","text":"Problem: exchanging files by hand means two people edit local copies, merging is manual and error-prone, and version conflicts and duplicated work follow. What a service like Google Docs gives: real-time collaboration (edit, review, comment together), access from a plain browser, work from anywhere, version history with revert, and often free use. Two architectures: client-server (a central service owns document state) or peer-to-peer (clients sync directly). Commercial products choose client-server for finer control and consistency; so do we. The four stages the problem is solved in: 1. Requirements: functional requirements and infrastructure estimates. 2. Design: components and how they interact. 3. Concurrency: resolving conflicts from simultaneous edits. 4. Evaluation: performance, consistency, availability, scalability. Below is our own solution, worked through those four stages."},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"Stage 1 — Requirements and estimates","id":"stage-1-requirements-and-estimates","text":"Functional (in scope) 1. Create, open, edit and delete documents in the browser. 2. Several people edit the same document at once and see each other's changes within a fraction of a second. 3. See who is in the document (cursors / presence). 4. Version history: see and restore earlier versions. Out of scope for the first version: comments, offline mode, fine-grained sharing UI (we assume a simple owner/editor/viewer role per document). Non-functional Goal Target Latency A remote edit appears in under about 200 ms Availability High: editing continues during a single-node failure Consistency Convergence: everyone ends with the same text. Read-your-writes: your own edit shows at once Durability An acknowledged edit is never lost Estimates (assumptions, stated out loud) Item Assumption Result Daily users 10 million Peak factor 5× Concurrent editors on one doc up to 100 (typically 2–5) Edit rate about 1 edit/second per active editor with 1 million active editors at peak ≈ 1 million small messages/second across the fleet Document size about 100 KB average, 10 docs per user 10 M × 10 × 100 KB ≈ 10 TB of content Bandwidth an edit message is tiny (tens of bytes to a few hundred) far smaller than the content store Takeaway: the hard part is not storage, it is many small, ordered, low-latency messages and keeping each document's edits in one place."},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"Stage 2 — Design","id":"stage-2-design","text":"flowchart LR C1[Client A] <--> WebSocket GW[Gateway / load balancer] C2[Client B] <--> WebSocket GW GW --> WS[Collaboration service - one owner per document] WS --> Q[(Operation log - append only)] WS --> SNAP[(Snapshot store - object storage)] WS --> META[(Metadata DB - relational)] WS --> PRES[(Presence - Redis)] HTTP[Document service - REST] --> META HTTP --> SNAP C1 --> create / open / list HTTP Components and roles Component Role Document service (REST) Create, list, open, delete documents; permissions; returns the latest snapshot plus the operations after it Gateway Terminates WebSockets, authenticates, routes all connections of one document to the same collaboration server (consistent hashing on documentId) Collaboration service Keeps the live document in memory, orders incoming operations, transforms conflicting ones, broadcasts them Operation log Append-only record of every operation (the source of truth between snapshots) Snapshot store Periodic full copies (e.g. every N operations or minutes) in object storage Metadata DB Titles, owners, roles, timestamps — relational, for integrity and queries Presence Cursors and \"who is here\"; short-lived, so an in-memory store is fine Why WebSocket: persistent, two-way, low latency. Polling is too slow; Server-Sent Events are one-way only. Why one owner per document: ordering is the whole problem. If all edits for a document pass through one server, that server can give them a single order. Many documents are spread across many servers. API sketch // REST POST /api/documents // { title } -> { documentId } GET /api/documents/:id // -> { snapshot, baseVersion, opsSince } DELETE /api/documents/:id // WebSocket messages, per document type ClientMsg { type: \"op\"; baseVersion: number; ops: Operation[] } // my edit, based on version N { type: \"cursor\"; position: number }; type ServerMsg { type: \"ack\"; version: number } // your op was applied at version V { type: \"op\"; version: number; ops: Operation[]; author: string } { type: \"presence\"; users: PresenceEntry[] }; Flow of one edit: client applies it locally at once (so typing feels instant) → sends op with the version it was based on → the collaboration server transforms it against any newer operations → appends to the log → acknowledges the sender → broadcasts to the others."},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"Stage 3 — Concurrency (the heart of the problem)","id":"stage-3-concurrency-the-heart-of-the-problem","text":"Two people type at the same moment, each based on the same version. The text must converge and keep each person's intent. Approach Idea Trade-off Last write wins The newest save replaces the older Simple, but loses someone's work. Not acceptable Locking Only one editor at a time Safe, but kills real-time collaboration Operational Transformation (OT) A central server transforms each incoming operation against the ones it missed Preserves intent; fits a central server; transformation rules are intricate CRDT Every character has a unique, ordered id so edits commute No central ordering needed, great for offline/P2P; more metadata per character Our choice: OT with a central server per document, because we already chose client-server and need low metadata overhead. CRDTs are the upgrade path if offline editing becomes a requirement. Worked example. Document: Hello World. A inserts beautiful at position 5. B, at the same time, inserts amazing at position 5 (before seeing A's edit). type Insert { pos: number; text: string; author: string }; // Rewrite b so it can be applied AFTER a has already been applied. function transform(b: Insert, a: Insert): Insert { const bAfterA b.pos > a.pos (b.pos a.pos && b.author > a.author); // tie-break by author id return bAfterA ? { ...b, pos: b.pos a.text.length } : b; } The server receives A first, so A applies unchanged; B is transformed against A and lands after it. Everyone ends with the same text. The tie-break on equal positions makes the result deterministic, which is what guarantees convergence. Version history: snapshots plus the operation log let us rebuild any past version (load the nearest earlier snapshot and replay operations). Old operations can be compacted into new snapshots."},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"Stage 4 — Evaluation","id":"stage-4-evaluation","text":"Quality How the design delivers it Weak spot and mitigation Latency Local apply first, one hop to a server that already holds the document in memory Far-away users: place collaboration servers in several regions and route to the document's home Consistency One ordering point per document; OT gives convergence; ack gives read-your-writes A hot document with 100 editors can saturate its single server: batch operations, cap concurrent editors, compress broadcasts Availability Stateless gateway; collaboration state is rebuildable from log snapshot If the owner server dies, another loads the snapshot and replays the log (a few seconds); clients reconnect and resend un-acked operations Durability Operations are written to the log before being acknowledged; log is replicated Slightly higher ack latency; use group commit Scalability Documents are independent: shard by documentId Rebalancing documents when servers are added: consistent hashing moves only a small share Security Per-document role check at connect time and per operation Revoke access: the server closes that user's socket Failure cases to mention in an interview: client offline mid-edit (queue operations locally, rebase on reconnect), duplicate delivery (operations carry client id sequence number, server ignores repeats), server crash after broadcast but before ack (client resends; duplicate rule handles it). How it connects to Pacewise: our current editor is single-writer and local (see Research › Docs writing tool — strategy and challenges). This page is the path to real-time co-editing: add the WebSocket collaboration service, the operation log, and snapshots, in that order."},{"slug":"interview--12-system-design-google-docs","title":"12 · System Design: Google Docs","folder":"interview","heading":"Self-check questions","id":"self-check-questions","text":"1. Why route every connection of one document to the same server? 2. What does OT do that last-write-wins does not? 3. Why do we apply an edit locally before the server confirms it? 4. How do you rebuild version 120 of a document? 5. What changes if offline editing becomes a requirement?"},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"13 · HTML & CSS","id":"","text":""},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"13 · HTML & CSS","id":"","text":"Interview preparation notes on HTML and CSS fundamentals: semantic HTML, attributes, links, lists and tables, forms, CSS selectors, text/font/background properties, the box model, and positioning. Every example is a complete, runnable snippet; the caption on each shows the file it belongs in (index.html or styles.css). Written in our own words; practice by retyping each example and changing it. How to use: cover the answer, say it aloud, then compare. For every topic also be ready with a common mistake and how to test it in the browser."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"1. Semantic HTML","id":"1-semantic-html","text":"A semantic element tells both the browser and the developer what its content is. <div> and <span> say nothing; <article>, <nav>, <header> do. Element Meaning <header> Introductory content or navigation links (may appear several times, not inside another header/footer/address) <nav> A major block of navigation links (not every link belongs in one) <main> The main content of the document (one per page) <section> A thematic grouping of content, normally with a heading <article> Independent, self-contained content that makes sense on its own (blog post, forum post, product card) <aside> Content only indirectly related to its surroundings (sidebar) <figure> / <figcaption> Self-contained illustration, diagram or code listing with its caption <footer> Authorship, copyright, contact, related links <details> / <summary> Content the user can show or hide, and its visible heading <mark> / <time> Highlighted text / a date or time <!DOCTYPE html> <html lang\"en\"> <head> <meta charset\"utf-8\" /> <meta name\"viewport\" content\"widthdevice-width, initial-scale1\" /> <title>Semantic page</title> <link rel\"stylesheet\" href\"styles.css\" /> </head> <body> <header> <h1>Browser news</h1> <nav> <a href\"/html/\">HTML</a> <a href\"/css/\">CSS</a> <a href\"/js/\">JavaScript</a> </nav> </header> <main> <section> <h2>Most popular browsers</h2> <article> <h3>Google Chrome</h3> <p>A web browser developed by Google, released in 2008.</p> </article> <article> <h3>Mozilla Firefox</h3> <p>An open-source web browser developed by Mozilla.</p> </article> </section> <aside> <h4>Did you know?</h4> <p>A sidebar is related to the page, but not part of its main flow.</p> </aside> </main> <footer> <p>Author: Your Name</p> <p><a href\"mailto:you@example.com\">you@example.com</a></p> </footer> </body> </html> Semantic vs non-semantic. Semantic elements have meaning, describe what their content is, and carry built-in behaviour for browsers, search engines and screen readers. Non-semantic elements (div, span) have no meaning and are styled by class/id. <!-- Non-semantic: the structure is only in class names --> <div class\"header\"> <div class\"nav\">Menu</div> </div> <!-- Semantic: the structure is in the elements --> <header> <nav>Menu</nav> </header> Is <article> inside <section>, or the reverse? Both occur. The definitions (independent content vs thematic grouping) do not dictate nesting; choose what describes your content. Interview answers Why semantic HTML? Accessibility (screen readers can skip to <main> or <nav>), SEO, maintainability, and sensible defaults. section vs div? Use section when the content is a thematic group with a heading; use div purely for styling/layout hooks. Common mistake: putting every link inside <nav>; it is for major navigation blocks only."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"2. Attributes","id":"2-attributes","text":"Attributes give extra information to an element and always go in the opening tag. Attribute Purpose src Source of media (image, video, audio); required for <img> alt Alternative text if the image does not load; used by screen readers width, height Dimensions (set them to avoid layout shift) title Advisory text shown on hover id Unique identifier: one per element, once per page class One or more class names; many elements can share one style Inline CSS href Hyperlink reference (target URL) <img src\"image.jpg\" alt\"Description of the image\" width\"200\" height\"150\" title\"Title of the image\" id\"image1\" class\"img-fluid\" /> Anchor tags. <a href> creates a link. target\"blank\" opens a new tab (add rel\"noopener noreferrer\" for external links). Linking to an id on the same page scrolls to it. <a href\"https://www.example.com\" target\"blank\" rel\"noopener noreferrer\">Visit Example</a> <a href\"#myPara\">Go to paragraph</a> <p id\"myPara\">You scrolled here.</p> Interview answers: id vs class? id is unique and used for one element, anchors and JS hooks; class is reusable for styling. Why alt? Accessibility and fallback. Why rel\"noopener\"? A page opened with blank could otherwise access window.opener."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"3. Lists and tables","id":"3-lists-and-tables","text":"Lists: <ol> ordered (numbered), <ul> unordered (bullets), <dl> description list (<dt> term, <dd> description). Each item of ol/ul is an <li>. <ol> <li>Write HTML</li> <li>Write CSS</li> </ol> <ul> <li>Chrome</li> <li>Firefox</li> </ul> <dl> <dt>HTML</dt> <dd>Structure of a page</dd> <dt>CSS</dt> <dd>Presentation of a page</dd> </dl> Tables: <table> → <tr> rows → <th> header cells / <td> data cells. Group with <thead>, <tbody>, <tfoot>, and title it with <caption>. colspan merges columns, rowspan merges rows. <table border\"1\"> <caption>Team scores</caption> <thead> <tr> <th scope\"col\">Name</th> <th scope\"col\">Age</th> <th scope\"col\">Country</th> </tr> </thead> <tbody> <tr> <td>Harry Depp</td> <td>28</td> <td>Britain</td> </tr> <tr> <td>John Smith</td> <td>35</td> <td>USA</td> </tr> </tbody> <tfoot> <tr> <td colspan\"2\">Total</td> <td>2</td> </tr> </tfoot> </table> <table border\"1\"> <tr> <th colspan\"4\">DIVING</th> </tr> <tr> <td colspan\"2\">cols 1 and 2, row 2</td> <td colspan\"2\">cols 3 and 4, row 2</td> </tr> <tr> <td>col 1</td> <td>col 2</td> <td>col 3</td> <td>col 4</td> </tr> </table> Homework question (asked in interviews): What does the scope attribute do on <th>? It states whether a header applies to a column (col) or a row (row), so screen readers can announce the right header for each cell."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"4. Forms","id":"4-forms","text":"A form collects user input. <form> is the container; its important attributes are action (where the data is sent, usually an API URL), method (GET appends data to the URL and is for retrieving; POST sends it in the request body, for large or sensitive data) and name. Main controls: <input> (many types), <select> with <option>, <textarea> (multi-line), <button>, and <label> (clicking the label focuses its input — link them with for/id). Common input types: text, password, email, number, range, color, checkbox, radio, file, submit, reset, button. <form action\"/api/register\" method\"post\" name\"signup\"> <label for\"name\">Text input:</label> <input type\"text\" id\"name\" name\"name\" required /> <label for\"pw\">Password:</label> <input type\"password\" id\"pw\" name\"password\" minlength\"8\" /> <label for\"age\">Number:</label> <input type\"number\" id\"age\" name\"age\" min\"1\" max\"120\" /> <label for\"email\">Email:</label> <input type\"email\" id\"email\" name\"email\" /> <label for\"volume\">Range:</label> <input type\"range\" id\"volume\" name\"volume\" min\"0\" max\"10\" /> <label for\"colour\">Colour:</label> <input type\"color\" id\"colour\" name\"colour\" /> <label><input type\"checkbox\" name\"terms\" /> Accept terms</label> <label><input type\"radio\" name\"plan\" value\"free\" /> Free</label> <label><input type\"radio\" name\"plan\" value\"pro\" /> Pro</label> <label for\"country\">Country:</label> <select id\"country\" name\"country\"> <option value\"in\">India</option> <option value\"uk\">Britain</option> </select> <label for\"msg\">Message:</label> <textarea id\"msg\" name\"message\" rows\"4\"></textarea> <label for\"file\">File upload:</label> <input type\"file\" id\"file\" name\"file\" /> <button type\"submit\">Submit</button> <button type\"reset\">Reset</button> </form> Interview answers: GET vs POST? GET: data in the URL, cacheable, bookmarkable, for reads. POST: data in the body, not in the URL, for writes. Why <label for>? Larger click target and accessibility. Radio vs checkbox? Radios with the same name allow one choice; checkboxes allow many."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"5. CSS selectors","id":"5-css-selectors","text":"CSS syntax: selector { property: value; }. The selector chooses elements; the declarations style them. CSS keeps presentation separate from content. Selector Example Selects Universal Every element Type p All <p> elements ID #myID The element with that id Class .myClass Elements with that class Pseudo-class a:hover An element in a state (hover, focus, first-child…) Child combinator div > p p that are direct children of div Adjacent sibling h2 p A p immediately after an h2 Attribute [type\"text\"] Elements with that attribute value / Universal selector / { font-family: Arial, sans-serif; } / Type selector / p { color: red; } / ID selector / #myID { font-weight: bold; } / Class selector / .myClass { background-color: yellow; padding: 10px; } / Pseudo-class / a:hover { color: purple; } / Child combinator / div > p { font-style: italic; } / Attribute selector / [type\"text\"] { border: 1px solid blue; margin-bottom: 10px; } / Adjacent sibling / h2 p { margin-top: 20px; } / Direct children of a list / ul > li { list-style-type: square; } <p>This is a paragraph.</p> <p id\"myID\">This paragraph has an ID.</p> <div class\"myClass\"> <p>This paragraph has a class and is a child of a div.</p> </div> <a href\"#\">Hover over me</a> <input type\"text\" placeholder\"Text input\" /> <h2>Heading 2</h2> <p>This paragraph follows an h2.</p> <ul> <li>List item 1</li> <li>List item 2</li> </ul> Specificity (a favourite question). From weakest to strongest: type < class/attribute/pseudo-class < id < inline style < !important. When equal, the later rule wins. Avoid !important; avoid long chains; prefer classes. Linking the files. Put the rules in styles.css and load them with <link rel\"stylesheet\" href\"styles.css\" /> in the <head>."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"6. Text and font properties","id":"6-text-and-font-properties","text":"Property What it does color Text colour (names, hex, rgb(), rgba(), hsl()) text-align left, right, center, justify text-decoration underline, overline, line-through (plus colour/style/line sub-properties) text-transform uppercase, lowercase, capitalize, none line-height Height of a line (unitless is best) text-shadow Offset-x, offset-y, blur, colour text-indent Indent of the first line text-overflow How overflowing text is shown (ellipsis, clip) letter-spacing, word-spacing Space between letters / words font-family Ordered list of fonts, ending with a generic family font-size px, em, rem, % font-weight normal, bold, or 100–900 font-style normal, italic, oblique font-variant, font-stretch Small-caps; condensed/expanded letters body { font-family: Arial, sans-serif; font-size: 16px; line-height: 1.6; color: #333; } h1 { text-align: center; text-transform: uppercase; font-weight: bold; font-size: 2em; color: #009688; text-decoration: underline; letter-spacing: 2px; margin-bottom: 20px; } p { text-align: justify; text-indent: 20px; text-shadow: 2px 2px 3px rgba(0, 0, 0, 0.3); margin-bottom: 20px; } .highlight { background-color: yellow; font-weight: bold; font-style: italic; } <h1>Text Properties Example</h1> <p> Reading is faster when <span class\"highlight\">line height</span> and <span class\"highlight\">font size</span> are chosen with care. </p> Tips: list a fallback in font-family (for example \"Inter\", Arial, sans-serif); prefer rem for sizes so they follow the user's browser settings; use a unitless line-height."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"7. Background properties","id":"7-background-properties","text":"Property Values background-color Named colour, RGB, HSL, hex background-image url('…') background-size Lengths, percentages, contain (fit inside), cover (fill, may crop) background-position Lengths, percentages, top bottom left right center background-repeat repeat (default), repeat-x, repeat-y, no-repeat .background-example { width: 300px; height: 200px; background-color: lightblue; / colour shown if the image is missing / background-image: url(\"example.jpg\"); background-size: cover; background-position: center; background-repeat: no-repeat; } Interview answer: cover vs contain? cover scales until the whole box is filled (may crop); contain scales until the whole image is visible (may leave gaps)."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"8. The box model","id":"8-the-box-model","text":"Every element is a rectangular box with four layers, from inside out: content → padding → border → margin. Width/height size the content area; use absolute units (px, cm) or relative ones (% of the parent, vw/vh of the viewport). box-sizing decides what width means: content-box (default) adds padding and border on top; border-box includes them in the width. Most projects set border-box globally. , ::before, ::after { box-sizing: border-box; } .card { width: 300px; / total width, because of border-box / padding: 16px; / inside the border / border: 2px solid #333; margin: 24px auto; / outside; auto centres horizontally / }"},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"Margin","id":"margin","text":"Space around an element; it does not change the element's own size. Default 0. Units: px, cm, mm, %; auto centres a block horizontally. Values Meaning Example one all four sides margin: 20px; two top and bottom, left and right margin: 20px 30px; three top, left and right, bottom margin: 20px 30px 40px; four top, right, bottom, left (clockwise) margin: 20px 30px 40px 50px; Margin collapsing: when the vertical margins of two adjacent block elements touch, only the larger one remains. .first { margin-bottom: 40px; } .second { margin-top: 20px; }"},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"Border","id":"border","text":"Three parts that go together: width, style (solid, dotted, dashed, double, groove, ridge, inset, outset, none) and colour; plus border-radius for rounded corners. The shorthand is border: width style colour. Without a style, no border shows. .box { border: 10px solid red; } .box-none { border-style: none; } #EG8 { width: 120px; height: 120px; border: 4px solid red; border-radius: 50%; / a square becomes a circle / }"},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"9. Positioning","id":"9-positioning","text":"The position property decides how an element is placed. Value Behaviour static Default; normal document flow; top/left/right/bottom have no effect relative Stays in flow but can be offset from its own normal position with top/left/right/bottom; also becomes the reference for absolute children absolute Removed from the flow; placed relative to the nearest positioned ancestor (or the page if there is none) fixed Placed relative to the viewport; does not move when you scroll (chat button, cookie bar) sticky Behaves like relative until a scroll threshold, then like fixed (sticky headers) .sticky-header { position: sticky; top: 0; / sticks when it reaches the top of the viewport / background: white; } .chat-button { position: fixed; / stays in the corner while scrolling / right: 16px; bottom: 16px; } .card { position: relative; / reference box for the badge / } .card .badge { position: absolute; top: 0; right: 0; / top-right corner of .card / } Interview answers relative vs absolute? Relative keeps its space in the flow and offsets from itself; absolute leaves the flow and offsets from the nearest positioned ancestor. fixed vs sticky? Fixed is always relative to the viewport; sticky is in the flow until the threshold, then sticks within its container. Why does my absolute element jump to the page corner? None of its ancestors is positioned; give the intended parent position: relative. Create a sticky header, a fixed sidebar and a modal are common practical tasks: they use sticky, fixed and fixed a backdrop respectively."},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"10. Self-check","id":"10-self-check","text":"1. Name five semantic elements and one thing each replaces. 2. What is the difference between id and class, and which wins in specificity? 3. What does scope do on a table header? 4. Why use label for? What does method\"post\" change? 5. Write a selector for \"paragraphs that directly follow an h2\". 6. What does box-sizing: border-box change about width? 7. Two blocks: bottom margin 40px and top margin 20px. How big is the gap, and why? 8. Which position value would you use for a header that stays visible while scrolling, but only after you pass it?"},{"slug":"interview--13-html-css","title":"13 · HTML & CSS","folder":"interview","heading":"References","id":"references","text":"MDN Web Docs — HTML elements: https://developer.mozilla.org/en-US/docs/Web/HTML/Element MDN Web Docs — CSS: https://developer.mozilla.org/en-US/docs/Web/CSS MDN — Box model: https://developer.mozilla.org/en-US/docs/Learnwebdevelopment/Core/Stylingbasics/Boxmodel MDN — Mastering margin collapsing: https://developer.mozilla.org/en-US/docs/Web/CSS/CSSboxmodel/Masteringmargincollapsing MDN — position: https://developer.mozilla.org/en-US/docs/Web/CSS/position MDN — Table accessibility (scope): https://developer.mozilla.org/en-US/docs/Learnwebdevelopment/Core/Structuringcontent/Tableaccessibility W3C — HTML specification (semantic elements): https://html.spec.whatwg.org/multipage/semantics.html W3Schools — HTML and CSS tutorials: https://www.w3schools.com/"},{"slug":"interview--readme","title":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","folder":"interview","heading":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","id":"","text":""},{"slug":"interview--readme","title":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","folder":"interview","heading":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","id":"","text":"Aimed at top-paying SDE roles (the ₹2.5 Cr band: Staff-leaning SDE-2/SDE-3 at product and big-tech companies). At that level the bar is: sound fundamentals, clean problem solving, and the ability to design and defend real systems. Every topic below has Easy → Medium → Hard questions with short model answers, and ties back to code in this project so you can speak from experience. # Topic Why it matters at this level 01 JavaScript & TypeScript Every frontend/full-stack loop starts here 02 React Rendering model, state, performance 03 Next.js & Web Platform SSR/CSR, routing, caching, CSS pitfalls, Core Web Vitals 04 Data Structures & Algorithms The gate for every top-tier loop 05 System Design Deciding factor for level and pay 06 Backend, APIs & Databases Express/Prisma, SQL, indexing, transactions 07 Auth & Security Sessions, JWT, OAuth, OWASP 08 Testing, CI/CD & Deployment Production ownership 09 Behavioral & Project Walkthrough Leadership principles, impact, depth in your own work 11 This release: ownership, routing, photos Defending real design decisions 12 System Design: Google Docs Worked collaborative-editing design: requirements, WebSocket, OT, evaluation 13 HTML & CSS Semantic HTML, forms, selectors, box model, positioning, with runnable code 10 Study Plan 8-week schedule and how the levels are scored How to use: cover the answer, say yours out loud, then compare. For every Medium/Hard question, also state the trade-off and the failure mode — that is what separates senior answers from mid-level ones."},{"slug":"leadership-principles--readme","title":"Leadership principles","folder":"leadership-principles","heading":"Leadership principles","id":"","text":""},{"slug":"leadership-principles--readme","title":"Leadership principles","folder":"leadership-principles","heading":"Leadership principles","id":"","text":"How well-known leadership principles read when they are applied to building Pacewise. The headings follow each company's own published list, so they are easy to recognise and to use in interview answers. Every sentence underneath is original and written for this platform: its readers, its quizzes, its docs and its search. Amazon's Leadership: sixteen principles, each with what it means for Pacewise. Google's Leadership: ten principles, each with what it means for Pacewise."},{"slug":"leadership-principles--readme","title":"Leadership principles","folder":"leadership-principles","heading":"How to use these pages","id":"how-to-use-these-pages","text":"1. Read the principle as a question about a real decision in the project, not as a slogan. 2. Use the \"In Pacewise\" lines as true examples: each one points at something that exists in the code or the docs. 3. In an interview, pick the example that fits the question, state the decision, the alternative you rejected, and what the result was."},{"slug":"leadership-principles--readme","title":"Leadership principles","folder":"leadership-principles","heading":"A note on sources","id":"a-note-on-sources","text":"The company names appear only to say whose list a heading comes from. The principles are public, the wording here is not copied from them, and nothing on these pages is an official statement of either company."},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Amazon's Leadership Principles","id":"","text":""},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Amazon's Leadership Principles","id":"","text":"The sixteen headings below follow Amazon's published list. The text under each one is original: it says what the principle means when the product is Pacewise, a reading-speed and comprehension platform with quizzes, personal analytics, documentation and a search engine."},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Customer Obsession","id":"customer-obsession","text":"In Pacewise: the customer is a person who wants to read faster and still understand. Every feature is judged by whether it helps that person finish a story and remember it. The speed is chosen on the story's landing page, before the clock starts, so nothing about the reading itself is fiddly. The quiz measures understanding, not only speed, so a high words-per-minute number cannot hide poor comprehension. A loader appears only when a page really takes longer than 150 ms, because a spinner on a fast page is noise the reader never asked for. Question to ask: would the reader notice if this were missing, and would they thank us for it?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Ownership","id":"ownership","text":"In Pacewise: one person owns the whole product, from sign-in and per-user storage to the docs and the search design. There is nobody downstream to hand a half-fixed problem to. The \"two clicks to reach the landing page\" bug was not patched at the button. The cause was a story page that reloaded a story right after it was cleared, and that is where it was fixed. A fix is finished when the user confirms it, not when the code compiles. The hydration error was reported twice for exactly that reason. Documentation is part of the feature: if behaviour changes, the doc changes in the same delivery. Question to ask: if this breaks next month, whose problem is it? If the answer is \"mine\", it deserves a test and a note."},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Invent and Simplify","id":"invent-and-simplify","text":"In Pacewise: invent only where the existing tools do not fit, and then make the result small. The Markdown renderer for the docs has no dependency, supports exactly what the docs need (tables, captioned code, diagrams), and escapes everything first. Several syllabus chapters were merged into one Overview instead of keeping near-empty pages. The select-and-highlight tool was removed from the docs because it added weight without helping anyone read. Question to ask: can this be done with fewer parts, and what would we delete if we had to?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Are Right, A Lot","id":"are-right-a-lot","text":"In Pacewise: be right by checking, not by feeling sure. Pure logic (grading, page timing, the overtime clock, the session isolation) lives in small functions with tests that run in plain Node. Capacity numbers in the search design are written down as assumptions and recomputed, so they can be argued with. When the assistant cannot run the app in a browser, the delivery says so, so the owner knows what still needs a real check. Question to ask: what would prove me wrong, and have I looked for it?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Learn and Be Curious","id":"learn-and-be-curious","text":"In Pacewise: the project has a Research folder and an Interview prep folder because learning is part of the work. Case studies of real systems (a tracker-network design, collaborative editing, search engines) were studied, then written up in the project's own words. Small details were looked up rather than guessed: how a spinner should start, how long a wait is worth hiding, how a blur material behaves. Every new technique earns a short note in the docs so the learning is not lost. Question to ask: what did we not know a month ago that now changes how we build?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Hire and Develop the Best","id":"hire-and-develop-the-best","text":"In Pacewise: there is no hiring yet, so this principle becomes \"make the next contributor good quickly\". The architecture doc ends with a short recipe for adding a per-user feature: one repository class, one line of registration. The docs explain the why of each decision, so a new person learns the thinking and not only the code. Interview prep pages turn the project's own work into practice material. Question to ask: could a newcomer add a feature on day two using only the docs?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Insist on the Highest Standards","id":"insist-on-the-highest-standards","text":"In Pacewise: \"works on my machine\" is not the bar. Motion respects the reduced-motion setting, controls have labels, and icon-only buttons explain themselves on hover. Hydration problems, scroll glitches and layout overlap are treated as defects, not polish. A change ships with tests, a syntax check and an honest list of what was not verified. Question to ask: would this survive a reviewer who wants to find the flaw?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Think Big","id":"think-big","text":"In Pacewise: design for the size the product could reach, even while it is small. The search-engine design assumes a million users and hundreds of millions of documents, and shows that storage is easy while OCR, isolation and ranking are hard. Features are built on seams (a repository per feature, a facade over storage) so a real backend can replace local storage without rewriting the screens. A roadmap in phases keeps the big idea and the next small step visible together. Question to ask: if ten thousand times more people used this tomorrow, what breaks first?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Bias for Action","id":"bias-for-action","text":"In Pacewise: most choices here can be undone, so they are made quickly and shipped in small steps. Work is delivered in short rounds, each one a working build the owner can try and correct. Phase one of search is a tiny bundled index, not a cluster, because it can be replaced later. Slow or irreversible choices (what data is stored about a person, what is deleted) get more thought, because they cannot be walked back. Question to ask: is this decision reversible? If yes, decide now."},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Frugality","id":"frugality","text":"In Pacewise: constraints make the product better. Documentation is bundled at build time, so there is no docs server to pay for. Existing components (cards, buttons, the loader) are reused before new ones are written. Diagrams are hand-written SVG files, not a licensed tool, and heavy libraries load from a CDN only when a diagram opens. Question to ask: what would we build if this had to run on a free tier?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Earn Trust","id":"earn-trust","text":"In Pacewise: trust is kept by being plain about what the product does with a person's data and about what it cannot do. Reading time, test time and documentation time belong to one signed-in user and never mix with another's. Pages end with a \"Limits\" section that names what is not covered. Third-party images and posts were removed when their rights were unclear, instead of hoping nobody would mind. Question to ask: would I be comfortable if the user read exactly how this works?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Dive Deep","id":"dive-deep","text":"In Pacewise: the symptom is never the answer. A story page that flashed its middle before gliding to the top turned out to be page-wide smooth scrolling combined with a kept scroll position. The fix was one instant scroll before paint. A rendering error that survived one fix was traced to style text containing quotes, and fixed at its source in three places. Numbers shown to the user (time per page, totals) are recomputed in tests from known inputs. Question to ask: have I seen the actual cause, or only guessed at it?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Have Backbone; Disagree and Commit","id":"have-backbone-disagree-and-commit","text":"In Pacewise: say so when a request will hurt the product, then build what was decided. Raise the concern with the reason and an alternative, once, in writing. Docs behind a sign-in is an example of a decision made for a clear reason (time can be attributed to a person), then carried out fully. Decisions are recorded in the docs, so a later change is a conscious reversal and not an accident. Question to ask: have I said what I think, and once it is decided, am I building it fully?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Deliver Results","id":"deliver-results","text":"In Pacewise: results are the numbers that show the product works. The key inputs are reading speed that holds up under a quiz, quiz accuracy, time to first useful screen and search latency. Each delivery names what changed, what passed, and what still needs a human to try. Setbacks (a failed test, a bad regular expression) are fixed and re-sent, not hidden. Question to ask: which number moved because of this work?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Strive to be Earth's Best Employer","id":"strive-to-be-earths-best-employer","text":"In Pacewise: read it as \"be the best place to work for the people who build it and the best product for people who use it daily\". The break tracker shows how rest affects effective reading speed, so the product itself encourages healthy pace. Text size, contrast themes and reduced motion are options, not afterthoughts. Writing clear docs and small, testable code lets a contributor grow without fear of breaking everything. Question to ask: will the person using or building this be better off for it a year from now?"},{"slug":"leadership-principles--amazon--01-amazon-leadership-principles","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Success and Scale Bring Broad Responsibility","id":"success-and-scale-bring-broad-responsibility","text":"In Pacewise: as the audience grows, so do the duties. Personal data is stored per user, can be cleared by that user, and a deleted document is removed from search within a day in the design. Only content that may be shared is published, and credits are given where they belong. Cost, energy and bandwidth are watched: small pages, lazy loading, and no needless background work. Question to ask: what does this look like if a million people depend on it? Headings follow the published Amazon list. The explanations are original and specific to Pacewise; they are not an official statement of Amazon."},{"slug":"leadership-principles--amazon--01-customer-obsession","title":"Customer Obsession","folder":"leadership-principles/amazon","heading":"Customer Obsession","id":"","text":""},{"slug":"leadership-principles--amazon--01-customer-obsession","title":"Customer Obsession","folder":"leadership-principles/amazon","heading":"Customer Obsession","id":"","text":"Amazon Leadership Principle 1 of 16."},{"slug":"leadership-principles--amazon--01-customer-obsession","title":"Customer Obsession","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Start from what the customer needs and work backwards; keep their trust above everything, including your interest in competitors."},{"slug":"leadership-principles--amazon--01-customer-obsession","title":"Customer Obsession","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Do you begin with the customer's problem rather than your solution? Can you show a decision where you gave up something for the customer's long-term trust?"},{"slug":"leadership-principles--amazon--01-customer-obsession","title":"Customer Obsession","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you went beyond the brief for a customer. Describe a time customer feedback changed your plan."},{"slug":"leadership-principles--amazon--01-customer-obsession","title":"Customer Obsession","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--01-customer-obsession","title":"Customer Obsession","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Naming the customer vaguely (\"users\") with no evidence of what they actually said or did. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--02-ownership","title":"Ownership","folder":"leadership-principles/amazon","heading":"Ownership","id":"","text":""},{"slug":"leadership-principles--amazon--02-ownership","title":"Ownership","folder":"leadership-principles/amazon","heading":"Ownership","id":"","text":"Amazon Leadership Principle 2 of 16."},{"slug":"leadership-principles--amazon--02-ownership","title":"Ownership","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Act like the owner of the whole outcome, think long term, and never treat a problem as someone else's."},{"slug":"leadership-principles--amazon--02-ownership","title":"Ownership","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you act outside your own lane? Did you pick the long-term fix when a quick patch was easier?"},{"slug":"leadership-principles--amazon--02-ownership","title":"Ownership","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you took on something that was not your job. Describe a long-term decision that cost you short-term results."},{"slug":"leadership-principles--amazon--02-ownership","title":"Ownership","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--02-ownership","title":"Ownership","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Saying \"we\" for everything so your own part is invisible, or blaming another team. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--03-invent-and-simplify","title":"Invent and Simplify","folder":"leadership-principles/amazon","heading":"Invent and Simplify","id":"","text":""},{"slug":"leadership-principles--amazon--03-invent-and-simplify","title":"Invent and Simplify","folder":"leadership-principles/amazon","heading":"Invent and Simplify","id":"","text":"Amazon Leadership Principle 3 of 16."},{"slug":"leadership-principles--amazon--03-invent-and-simplify","title":"Invent and Simplify","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Expect new ideas from your team and from outside it, and keep making things simpler, accepting that new ideas can be misunderstood for a while."},{"slug":"leadership-principles--amazon--03-invent-and-simplify","title":"Invent and Simplify","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you remove complexity rather than add features? Did you adopt an idea that was not invented in your team?"},{"slug":"leadership-principles--amazon--03-invent-and-simplify","title":"Invent and Simplify","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about something you simplified. Describe an unpopular idea you pushed and how you handled doubt."},{"slug":"leadership-principles--amazon--03-invent-and-simplify","title":"Invent and Simplify","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--03-invent-and-simplify","title":"Invent and Simplify","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"A clever solution that is harder to run than the problem it solved. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--04-are-right-a-lot","title":"Are Right, A Lot","folder":"leadership-principles/amazon","heading":"Are Right, A Lot","id":"","text":""},{"slug":"leadership-principles--amazon--04-are-right-a-lot","title":"Are Right, A Lot","folder":"leadership-principles/amazon","heading":"Are Right, A Lot","id":"","text":"Amazon Leadership Principle 4 of 16."},{"slug":"leadership-principles--amazon--04-are-right-a-lot","title":"Are Right, A Lot","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Good judgment built on instinct that you actively test: seek other views and try to prove your own belief wrong."},{"slug":"leadership-principles--amazon--04-are-right-a-lot","title":"Are Right, A Lot","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you look for evidence against your plan? Can you describe a call you got wrong and what you changed?"},{"slug":"leadership-principles--amazon--04-are-right-a-lot","title":"Are Right, A Lot","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a decision you made with incomplete data. Describe a time you changed your mind."},{"slug":"leadership-principles--amazon--04-are-right-a-lot","title":"Are Right, A Lot","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--04-are-right-a-lot","title":"Are Right, A Lot","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Never having been wrong, or only being wrong in a way that makes you look good. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--05-learn-and-be-curious","title":"Learn and Be Curious","folder":"leadership-principles/amazon","heading":"Learn and Be Curious","id":"","text":""},{"slug":"leadership-principles--amazon--05-learn-and-be-curious","title":"Learn and Be Curious","folder":"leadership-principles/amazon","heading":"Learn and Be Curious","id":"","text":"Amazon Leadership Principle 5 of 16."},{"slug":"leadership-principles--amazon--05-learn-and-be-curious","title":"Learn and Be Curious","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Never finished learning; curious about new possibilities and willing to act on them."},{"slug":"leadership-principles--amazon--05-learn-and-be-curious","title":"Learn and Be Curious","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did curiosity lead to a concrete result? How do you learn something new fast?"},{"slug":"leadership-principles--amazon--05-learn-and-be-curious","title":"Learn and Be Curious","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about something you taught yourself recently. Describe a time curiosity solved a real problem."},{"slug":"leadership-principles--amazon--05-learn-and-be-curious","title":"Learn and Be Curious","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--05-learn-and-be-curious","title":"Learn and Be Curious","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Listing courses and certificates with no result they produced. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--06-hire-and-develop-the-best","title":"Hire and Develop the Best","folder":"leadership-principles/amazon","heading":"Hire and Develop the Best","id":"","text":""},{"slug":"leadership-principles--amazon--06-hire-and-develop-the-best","title":"Hire and Develop the Best","folder":"leadership-principles/amazon","heading":"Hire and Develop the Best","id":"","text":"Amazon Leadership Principle 6 of 16."},{"slug":"leadership-principles--amazon--06-hire-and-develop-the-best","title":"Hire and Develop the Best","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Raise the bar with every hire and promotion, spot exceptional people, and take coaching seriously."},{"slug":"leadership-principles--amazon--06-hire-and-develop-the-best","title":"Hire and Develop the Best","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you make others better, not just yourself? Did you hold a high bar when it was inconvenient?"},{"slug":"leadership-principles--amazon--06-hire-and-develop-the-best","title":"Hire and Develop the Best","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about someone you coached. Describe a hiring or promotion decision where you held the bar."},{"slug":"leadership-principles--amazon--06-hire-and-develop-the-best","title":"Hire and Develop the Best","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--06-hire-and-develop-the-best","title":"Hire and Develop the Best","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Only describing your own work in a question about developing people. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--07-insist-on-the-highest-standards","title":"Insist on the Highest Standards","folder":"leadership-principles/amazon","heading":"Insist on the Highest Standards","id":"","text":""},{"slug":"leadership-principles--amazon--07-insist-on-the-highest-standards","title":"Insist on the Highest Standards","folder":"leadership-principles/amazon","heading":"Insist on the Highest Standards","id":"","text":"Amazon Leadership Principle 7 of 16."},{"slug":"leadership-principles--amazon--07-insist-on-the-highest-standards","title":"Insist on the Highest Standards","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Keep standards that others may call unreasonable, keep raising them, and fix problems so they stay fixed."},{"slug":"leadership-principles--amazon--07-insist-on-the-highest-standards","title":"Insist on the Highest Standards","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you fix the root cause? Did you refuse to ship something that was not good enough?"},{"slug":"leadership-principles--amazon--07-insist-on-the-highest-standards","title":"Insist on the Highest Standards","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you raised the quality bar. Describe a defect you stopped from reaching customers."},{"slug":"leadership-principles--amazon--07-insist-on-the-highest-standards","title":"Insist on the Highest Standards","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--07-insist-on-the-highest-standards","title":"Insist on the Highest Standards","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Perfectionism with no judgment about what matters, or standards you never actually enforced. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--08-think-big","title":"Think Big","folder":"leadership-principles/amazon","heading":"Think Big","id":"","text":""},{"slug":"leadership-principles--amazon--08-think-big","title":"Think Big","folder":"leadership-principles/amazon","heading":"Think Big","id":"","text":"Amazon Leadership Principle 8 of 16."},{"slug":"leadership-principles--amazon--08-think-big","title":"Think Big","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"A small view limits results; set a bold direction that inspires others and look for new ways to serve customers."},{"slug":"leadership-principles--amazon--08-think-big","title":"Think Big","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you aim past the obvious next step? Did you bring others along with the vision?"},{"slug":"leadership-principles--amazon--08-think-big","title":"Think Big","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about the boldest idea you proposed. Describe how you scaled a small idea."},{"slug":"leadership-principles--amazon--08-think-big","title":"Think Big","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--08-think-big","title":"Think Big","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Big words with no first step or no way to measure success. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--09-bias-for-action","title":"Bias for Action","folder":"leadership-principles/amazon","heading":"Bias for Action","id":"","text":""},{"slug":"leadership-principles--amazon--09-bias-for-action","title":"Bias for Action","folder":"leadership-principles/amazon","heading":"Bias for Action","id":"","text":"Amazon Leadership Principle 9 of 16."},{"slug":"leadership-principles--amazon--09-bias-for-action","title":"Bias for Action","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Speed matters. Many decisions can be reversed, so do not over-study them; take calculated risks."},{"slug":"leadership-principles--amazon--09-bias-for-action","title":"Bias for Action","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you move with partial data? Did you separate reversible from irreversible decisions?"},{"slug":"leadership-principles--amazon--09-bias-for-action","title":"Bias for Action","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you acted without all the information. Describe a calculated risk you took."},{"slug":"leadership-principles--amazon--09-bias-for-action","title":"Bias for Action","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--09-bias-for-action","title":"Bias for Action","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Rushing a decision that could not be undone, or waiting for certainty that never comes. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--10-frugality","title":"Frugality","folder":"leadership-principles/amazon","heading":"Frugality","id":"","text":""},{"slug":"leadership-principles--amazon--10-frugality","title":"Frugality","folder":"leadership-principles/amazon","heading":"Frugality","id":"","text":"Amazon Leadership Principle 10 of 16."},{"slug":"leadership-principles--amazon--10-frugality","title":"Frugality","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Do more with less; limits breed resourcefulness, and there is no credit for a bigger team or budget."},{"slug":"leadership-principles--amazon--10-frugality","title":"Frugality","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did a constraint push you to a better idea? Did you avoid spending that did not help the customer?"},{"slug":"leadership-principles--amazon--10-frugality","title":"Frugality","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you delivered with fewer resources. Describe a cost you cut without hurting quality."},{"slug":"leadership-principles--amazon--10-frugality","title":"Frugality","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--10-frugality","title":"Frugality","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Cheapness that damages the customer or the team. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--11-earn-trust","title":"Earn Trust","folder":"leadership-principles/amazon","heading":"Earn Trust","id":"","text":""},{"slug":"leadership-principles--amazon--11-earn-trust","title":"Earn Trust","folder":"leadership-principles/amazon","heading":"Earn Trust","id":"","text":"Amazon Leadership Principle 11 of 16."},{"slug":"leadership-principles--amazon--11-earn-trust","title":"Earn Trust","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Listen closely, speak candidly, treat people with respect, be openly self-critical and measure yourself against the best."},{"slug":"leadership-principles--amazon--11-earn-trust","title":"Earn Trust","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you admit a mistake first? Did you give or take hard feedback well?"},{"slug":"leadership-principles--amazon--11-earn-trust","title":"Earn Trust","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you had to rebuild trust. Describe a hard conversation you had with a colleague."},{"slug":"leadership-principles--amazon--11-earn-trust","title":"Earn Trust","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--11-earn-trust","title":"Earn Trust","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"A weakness answer that is secretly a strength. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--12-dive-deep","title":"Dive Deep","folder":"leadership-principles/amazon","heading":"Dive Deep","id":"","text":""},{"slug":"leadership-principles--amazon--12-dive-deep","title":"Dive Deep","folder":"leadership-principles/amazon","heading":"Dive Deep","id":"","text":"Amazon Leadership Principle 12 of 16."},{"slug":"leadership-principles--amazon--12-dive-deep","title":"Dive Deep","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Work at every level, know the details, check often, and doubt a story when the numbers disagree with it."},{"slug":"leadership-principles--amazon--12-dive-deep","title":"Dive Deep","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you go into logs, data or code yourself? Did you notice a metric and an anecdote that did not match?"},{"slug":"leadership-principles--amazon--12-dive-deep","title":"Dive Deep","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time the data did not match what people believed. Describe a problem you traced to its root."},{"slug":"leadership-principles--amazon--12-dive-deep","title":"Dive Deep","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--12-dive-deep","title":"Dive Deep","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Quoting a dashboard without being able to explain how the number is produced. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--13-have-backbone-disagree-and-commit","title":"Have Backbone; Disagree and Commit","folder":"leadership-principles/amazon","heading":"Have Backbone; Disagree and Commit","id":"","text":""},{"slug":"leadership-principles--amazon--13-have-backbone-disagree-and-commit","title":"Have Backbone; Disagree and Commit","folder":"leadership-principles/amazon","heading":"Have Backbone; Disagree and Commit","id":"","text":"Amazon Leadership Principle 13 of 16."},{"slug":"leadership-principles--amazon--13-have-backbone-disagree-and-commit","title":"Have Backbone; Disagree and Commit","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Challenge decisions respectfully even when it is uncomfortable, then commit fully once a decision is made."},{"slug":"leadership-principles--amazon--13-have-backbone-disagree-and-commit","title":"Have Backbone; Disagree and Commit","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you disagree with evidence, not ego? Once overruled, did you really commit?"},{"slug":"leadership-principles--amazon--13-have-backbone-disagree-and-commit","title":"Have Backbone; Disagree and Commit","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you disagreed with your manager. Describe a decision you disagreed with and still carried out."},{"slug":"leadership-principles--amazon--13-have-backbone-disagree-and-commit","title":"Have Backbone; Disagree and Commit","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--13-have-backbone-disagree-and-commit","title":"Have Backbone; Disagree and Commit","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Disagreeing silently, or committing in words while holding back in practice. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--14-deliver-results","title":"Deliver Results","folder":"leadership-principles/amazon","heading":"Deliver Results","id":"","text":""},{"slug":"leadership-principles--amazon--14-deliver-results","title":"Deliver Results","folder":"leadership-principles/amazon","heading":"Deliver Results","id":"","text":"Amazon Leadership Principle 14 of 16."},{"slug":"leadership-principles--amazon--14-deliver-results","title":"Deliver Results","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Focus on the inputs that matter, deliver on time with the right quality, and rise above setbacks."},{"slug":"leadership-principles--amazon--14-deliver-results","title":"Deliver Results","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you deliver despite an obstacle? Can you tie your actions to a measurable result?"},{"slug":"leadership-principles--amazon--14-deliver-results","title":"Deliver Results","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a project that nearly failed and how you finished it. Describe your biggest measurable result."},{"slug":"leadership-principles--amazon--14-deliver-results","title":"Deliver Results","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--14-deliver-results","title":"Deliver Results","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Effort and activity described instead of an outcome. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--15-strive-to-be-earth-s-best-employer","title":"Strive to be Earth's Best Employer","folder":"leadership-principles/amazon","heading":"Strive to be Earth's Best Employer","id":"","text":""},{"slug":"leadership-principles--amazon--15-strive-to-be-earth-s-best-employer","title":"Strive to be Earth's Best Employer","folder":"leadership-principles/amazon","heading":"Strive to be Earth's Best Employer","id":"","text":"Amazon Leadership Principle 15 of 16."},{"slug":"leadership-principles--amazon--15-strive-to-be-earth-s-best-employer","title":"Strive to be Earth's Best Employer","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"Make the workplace safer, more productive, more diverse and fairer; lead with empathy and care about people's growth."},{"slug":"leadership-principles--amazon--15-strive-to-be-earth-s-best-employer","title":"Strive to be Earth's Best Employer","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you create conditions where others could grow? Did you include voices that were missing?"},{"slug":"leadership-principles--amazon--15-strive-to-be-earth-s-best-employer","title":"Strive to be Earth's Best Employer","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a time you improved your team's environment. Describe how you supported someone's career."},{"slug":"leadership-principles--amazon--15-strive-to-be-earth-s-best-employer","title":"Strive to be Earth's Best Employer","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--15-strive-to-be-earth-s-best-employer","title":"Strive to be Earth's Best Employer","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Treating it as perks and culture events rather than how people are led. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--16-success-and-scale-bring-broad-responsibility","title":"Success and Scale Bring Broad Responsibility","folder":"leadership-principles/amazon","heading":"Success and Scale Bring Broad Responsibility","id":"","text":""},{"slug":"leadership-principles--amazon--16-success-and-scale-bring-broad-responsibility","title":"Success and Scale Bring Broad Responsibility","folder":"leadership-principles/amazon","heading":"Success and Scale Bring Broad Responsibility","id":"","text":"Amazon Leadership Principle 16 of 16."},{"slug":"leadership-principles--amazon--16-success-and-scale-bring-broad-responsibility","title":"Success and Scale Bring Broad Responsibility","folder":"leadership-principles/amazon","heading":"In one line","id":"in-one-line","text":"As an organisation grows its actions reach further; think about secondary effects on communities and the world and leave things better."},{"slug":"leadership-principles--amazon--16-success-and-scale-bring-broad-responsibility","title":"Success and Scale Bring Broad Responsibility","folder":"leadership-principles/amazon","heading":"What an interviewer listens for","id":"what-an-interviewer-listens-for","text":"Did you consider side effects beyond the immediate goal? Did you give back or leave a system better?"},{"slug":"leadership-principles--amazon--16-success-and-scale-bring-broad-responsibility","title":"Success and Scale Bring Broad Responsibility","folder":"leadership-principles/amazon","heading":"Questions you may be asked","id":"questions-you-may-be-asked","text":"Tell me about a decision where you weighed its wider impact. Describe a time you left something better than you found it."},{"slug":"leadership-principles--amazon--16-success-and-scale-bring-broad-responsibility","title":"Success and Scale Bring Broad Responsibility","folder":"leadership-principles/amazon","heading":"Build your story (STAR)","id":"build-your-story-star","text":"1. Situation: one or two sentences of context. 2. Task: what you were responsible for. 3. Action: what you did, in the first person. 4. Result: a number or a clear outcome, and what you learned."},{"slug":"leadership-principles--amazon--16-success-and-scale-bring-broad-responsibility","title":"Success and Scale Bring Broad Responsibility","folder":"leadership-principles/amazon","heading":"Watch out for","id":"watch-out-for","text":"Only talking about impact on your own team. All principles: Amazon's Leadership Principles."},{"slug":"leadership-principles--amazon--readme","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Amazon's Leadership Principles","id":"","text":""},{"slug":"leadership-principles--amazon--readme","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Amazon's Leadership Principles","id":"","text":"Amazon says it uses these principles every day, from discussing a new idea to deciding how to solve a problem, and interviews are built around them. This folder has one page for each of the 16 principles, written in plain words for interview preparation. Read the official wording on Amazon's own page: https://www.amazon.jobs/content/en/our-workplace/leadership-principles."},{"slug":"leadership-principles--amazon--readme","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"The 16 principles","id":"the-16-principles","text":"# Principle In one line 1 Customer Obsession Start from what the customer needs and work backwards; keep their trust above everything, including your interest in competitors. 2 Ownership Act like the owner of the whole outcome, think long term, and never treat a problem as someone else's. 3 Invent and Simplify Expect new ideas from your team and from outside it, and keep making things simpler, accepting that new ideas can be misunderstood for a while. 4 Are Right, A Lot Good judgment built on instinct that you actively test: seek other views and try to prove your own belief wrong. 5 Learn and Be Curious Never finished learning; curious about new possibilities and willing to act on them. 6 Hire and Develop the Best Raise the bar with every hire and promotion, spot exceptional people, and take coaching seriously. 7 Insist on the Highest Standards Keep standards that others may call unreasonable, keep raising them, and fix problems so they stay fixed. 8 Think Big A small view limits results; set a bold direction that inspires others and look for new ways to serve customers. 9 Bias for Action Speed matters. Many decisions can be reversed, so do not over-study them; take calculated risks. 10 Frugality Do more with less; limits breed resourcefulness, and there is no credit for a bigger team or budget. 11 Earn Trust Listen closely, speak candidly, treat people with respect, be openly self-critical and measure yourself against the best. 12 Dive Deep Work at every level, know the details, check often, and doubt a story when the numbers disagree with it. 13 Have Backbone; Disagree and Commit Challenge decisions respectfully even when it is uncomfortable, then commit fully once a decision is made. 14 Deliver Results Focus on the inputs that matter, deliver on time with the right quality, and rise above setbacks. 15 Strive to be Earth's Best Employer Make the workplace safer, more productive, more diverse and fairer; lead with empathy and care about people's growth. 16 Success and Scale Bring Broad Responsibility As an organisation grows its actions reach further; think about secondary effects on communities and the world and leave things better."},{"slug":"leadership-principles--amazon--readme","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"How to use these pages","id":"how-to-use-these-pages","text":"1. Read the one-line meaning, then the questions. 2. Pick one real story per principle from your own work. One story can serve two or three principles, but do not reuse the same one for every answer. 3. Write each story as Situation, Task, Action, Result, with a number in the result. 4. Say \"I\", not \"we\", for the Action. Interviewers score what you did. 5. Practise out loud: about two minutes per story."},{"slug":"leadership-principles--amazon--readme","title":"Amazon's Leadership Principles","folder":"leadership-principles/amazon","heading":"Quick map: which principles go together","id":"quick-map-which-principles-go-together","text":"Theme Principles Customers and quality Customer Obsession, Insist on the Highest Standards, Deliver Results Thinking and judgment Are Right, A Lot; Dive Deep; Think Big; Invent and Simplify Speed and resources Bias for Action, Frugality, Ownership People and trust Earn Trust, Hire and Develop the Best, Strive to be Earth's Best Employer, Have Backbone; Disagree and Commit Growth and responsibility Learn and Be Curious, Success and Scale Bring Broad Responsibility"},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"Google's Leadership Principles","id":"","text":""},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"Google's Leadership Principles","id":"","text":"The ten headings below follow the \"ten things\" list that Google published about itself. The text under each is original and shows what the idea means when you are building Pacewise."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"1. Focus on the user and all else will follow.","id":"1-focus-on-the-user-and-all-else-will-follow","text":"In Pacewise: a reader opens the app to understand a text faster, so every screen should serve that and nothing else. The story page puts speed, a time estimate and three clear actions where the reader's eyes already are. The numbers a reader sees (words per minute, time left, time per page) are about their own reading, not about the product. When a layout choice and a feature request pull apart, the reader's attention wins."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"2. It's best to do one thing really, really well.","id":"2-its-best-to-do-one-thing-really-really-well","text":"In Pacewise: the one thing is practising and measuring reading with comprehension. Quizzes, analytics and notes all exist to answer one question: did reading get faster and better? Features that do not help that answer wait. The docs site is a reference for builders, kept separate from the reading experience. Depth beats breadth: one reader with accurate timing, rather than five half-working modes."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"3. Fast is better than slow.","id":"3-fast-is-better-than-slow","text":"In Pacewise: speed is the product, so the app must not be slow itself. A page that loads in under 150 ms shows no loader at all, and a slower page gets one centred spinner. Documentation is built ahead of time and pages scroll with eased inertia, so reading feels immediate. The search design budgets about 150 ms end to end and splits the budget across each step."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"4. Democracy on the web works.","id":"4-democracy-on-the-web-works","text":"In Pacewise: a crowd's quiet signals are a useful input, used carefully. In the search design, links between a person's own documents act like votes, with a small weight and a damping factor so no single page dominates. What a reader opens and finishes can nudge ranking, but it never overrides a plain text match. The stack relies on open tools and open formats, so contributors are not locked in."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"5. You don't need to be at your desk to need an answer.","id":"5-you-dont-need-to-be-at-your-desk-to-need-an-answer","text":"In Pacewise: people read on phones, so the product has to work in a hand. Documentation opens from a QR code on a phone, after signing in. Layouts collapse for narrow screens, and extras such as the side rail are hidden where they would crowd the page. Touch targets are round, large and clearly labelled."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"6. You can make money without doing evil.","id":"6-you-can-make-money-without-doing-evil","text":"In Pacewise: if the product ever earns revenue, the rules are set before it does. Nothing paid can change what a reader finds or how a result is ranked. Anything sponsored is labelled as such, and nothing interrupts reading. Personal reading data is not sold, and plans can be cancelled as easily as they are started."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"7. There's always more information out there.","id":"7-theres-always-more-information-out-there","text":"In Pacewise: useful text is not only plain notes. The search design reaches into PDFs, scanned pages and photographs by extracting text, with OCR where a page has no text layer. Results point to the exact page and highlight the matched words. The Research folder keeps adding new material, so the knowledge base grows with the product."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"8. The need for information crosses all borders.","id":"8-the-need-for-information-crosses-all-borders","text":"In Pacewise: readers use many languages, and speed is not the same across them. Text is normalised and its language detected before it is indexed. Reading-speed targets are personal, not tied to one language's average. Interface text and docs are written plainly, which also makes them easier to translate."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"9. You can be serious without a suit.","id":"9-you-can-be-serious-without-a-suit","text":"In Pacewise: the tone is relaxed and the work is exact. Docs are written in plain language with real code, real numbers and real limits. Tests run in plain Node with no setup, so checking something is easy and therefore done. A joke in a commit message is fine; an untested change is not."},{"slug":"leadership-principles--google--01-google-leadership-principles","title":"Google's Leadership Principles","folder":"leadership-principles/google","heading":"10. Great just isn't good enough.","id":"10-great-just-isnt-good-enough","text":"In Pacewise: a working feature is the start of the next improvement. The speed wheel moved to where the decision actually happens. The clock now keeps counting after zero to show how late a reader is, because \"time is up\" alone said too little. Loaders were refined step by step: contrast, centring, start-up delay and timing, each one a small honest improvement. The search design lists its own weak points and the signal that will tell us when to change it. Headings follow the published Google list. The explanations are original and specific to Pacewise; they are not an official statement of Google."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"Pacewise — Research README","id":"","text":""},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"Pacewise — Research README","id":"","text":"One page that records what was asked, what was built, what went wrong, what was learned, and why — across the whole working conversation on the Pacewise frontend. Written for the project owner (Harsh). Scope: the speed-reader Next.js app, its public notes site (QR code), the documents site, and the quiz system. How complete this is: the full text of the earliest part of the conversation was compacted before this file was written, so those early items are recorded from the conversation summary (marked summary), while everything from the doc-page work onward is recorded from the actual exchanges and code (marked direct). Nothing here is invented to fill gaps; where a detail is not known it says so."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"1. Project in one paragraph","id":"1-project-in-one-paragraph","text":"Pacewise is a speed-reading and comprehension trainer: read a story at a chosen pace, take a quiz, get results and analytics, keep history, streaks and a daily-consistency calendar, upload your own stories (text, PDF, images) and edit them. It is a Next.js 14 (App Router) TypeScript (strict) Tailwind frontend with a deliberately object-oriented, per-user storage layer, a development login with 100 demo accounts, and (new in this stretch) a public, no-login notes and documents site reachable by scanning each user's QR code. Design language (\"the homepage language\") that every new screen must follow: font-display headings with tight tracking, rounded-[32px] surfaces, brand blue #306fdb, floating-label fields, Apple-like restraint (glass navbar, pill buttons, generous spacing)."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"2. Working rules the owner set (and why they matter)","id":"2-working-rules-the-owner-set-and-why-they-matter","text":"Rule Consequence in every round \"Do not change anything else\" Each change is additive and scoped; shared components are extended with optional props, never rewritten. Follow the homepage design language everywhere New UI reuses tokens (bg-canvas, bg-canvas-raised, text-ink, text-ink-muted, border-overlay/10), 32px radii, display type. Docs must stay updated docs/QUIZANDPROFILE.md is the running feature document; new features are appended to it. Deliver as a zip speed-reader-frontend.zip after each round (excluding nodemodules, .next). Writes in English/Hinglish Replies stay short, plain and direct. Work is not run in the owner's browser by the assistant The assistant verifies by tests, syntax checks and isolated rendering; real-browser confirmation is the owner's."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"3. Timeline of requests (what was asked, in order)","id":"3-timeline-of-requests-what-was-asked-in-order","text":""},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"3.1 Earlier stretch (summary)","id":"31-earlier-stretch-summary","text":"1. Replace the \"Change photo\" action with a QR code; add a Notes tab in the profile (CN, OS, OOP, DBMS: how each is used in Pacewise, with tradeoffs). 2. Fix the wrong PDF owner (an uploaded PDF showed another person as its owner). 3. Make the QR link open the Vercel home address (\"pick home address for qr code link\"). 4. Analytics / Apple-style restyles: results page typography, graph container widths, Efficiency / Dashboard / History restyle, mobile responsiveness, audience images. 5. Result-page and quiz upgrades (six screenshots): standard widths for Accuracy and Pace graphs; remove the Apple-style pause button; \"Time per question\" list with lazy loading (10 at a time); correct total test time (from \"Begin quiz\" to Done/Finish); show when each test was started in history; quiz button with green stroke, white background and liquid effect; progress-bar sound like Apple; hover on a calendar day shows reading and test time; sign-in/sign-up page in the same design language. 6. Strategic questions: relevance of the software for a 2.5 Cr-package profile \"if backend, monitoring and best engineering practices are integrated\", plus a PDF-editor-like feature, rated out of 10; then \"micro-level\" security, distributed-systems thinking, YouTube-scale architecture, and algorithm design for a test/revision notifier. (Answered in chat; the research-grade version of that answer is in §7 and docs/research/01-….) 7. Deployment confusion: a Vercel deployment URL showed \"Ready\" but did not show the update while the main domain did; the owner asked for the exact location and data flow of the updated link. 8. Public notes by QR: scanning the QR must show the notes without login, every doc as a web page, a navbar like the landing page, the same hamburger menu minus personal data, and a menu that contains every docs folder."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"3.2 This stretch (direct)","id":"32-this-stretch-direct","text":"9. Doc-page upgrade (docs pages only): OOP class diagram must behave like GitHub's Mermaid viewer (pan arrows, zoom, reset, expand, copy, drag); navbar hides on scroll-down and returns on scroll-up; a new Research section in the hamburger menu; bigger text in code boxes; highlighter typography tools. 10. Search bar (a Uiverse design) added to the docs navbar, then centred in the navbar. 11. Exact diagram and code rendering: the diagram must match GitHub's image (orthogonal edges, proper arrows); every code sample must be colour-highlighted with indentation kept, showing where the code lives (file path) and which principle it demonstrates. 12. Quiz JSON compatibility: the GATE CS1 2026 question file (65 questions) was rejected by the quiz. Also: docs search must search all page content (not only folder names); remove the select-and-highlight feature from docs. 13. Quiz extras: code inside questions must show as code with indentation; the search bar must support dark mode; the quiz schema must accept optional chapter, topic, year of appearance (previous-year question) and a note shown after the test. 14. Hydration error on the notes/docs pages (reported twice; the first fix was wrong). 15. This document."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"4. What was built (by area)","id":"4-what-was-built-by-area","text":""},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"4.1 Per-user session layer (OOP, summary code reviewed)","id":"41-per-user-session-layer-oop-summary-code-reviewed","text":"UserScopedRepository<T> (abstract, Template Method): the base class owns key building, defensive JSON parsing, fallback to an empty value and writing; subclasses supply feature(), emptyValue() and optional deserialize(). ListRepository<TItem> (abstract, second and last level): array-valued features (HistoryRepository, BookmarkRepository, AchievementRepository, CustomStoryRepository, SearchHistoryRepository). StreakRepository, DailyActivityRepository (object/map values). UserNamespace (value object, private constructor forUser): the only place that knows the key format srt:v2:u:<id>:<feature>. KeyValueStore interface with BrowserKeyValueStore and MemoryKeyValueStore (Dependency Inversion; tests use the memory store). UserSession (aggregate/facade, composition): one repository per feature, all bound to one namespace at construction; clearAllData() clears all polymorphically. SessionManager (registry observer), IdentityProvider / DevStoreIdentityProvider, LegacyDataMigrator, ScopedTokenStore. Full explanation and the class diagram: docs/OOPARCHITECTURE.md."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"4.2 Quiz and results (summary direct)","id":"42-quiz-and-results-summary-direct","text":"Timing: quizStartedAt at \"Begin quiz\", quizFinishedAt at Done/Finish; per-question dwell time summed across revisits; results show total test time separately from the average. Daily activity gained testMs, so the consistency calendar hover shows reading time and test time. Results page: Time-per-question list with \"Show 10 more / Show less\". New question kinds (direct): select-all-that-apply (correctAnswer: [1,3]) and typed number (options: [], numeric answer; whole numbers exact, decimals ±0.01 unless tolerance is given). Grading lives in lib/grading.ts (questionKind, isAnswered, isCorrectAnswer), used by the quiz, results and timing list. Code in questions (direct): lib/questionText.ts splits a question into prose and code (Markdown fences, or runs of code-looking lines); components/Quiz/QuestionText.tsx shows code with indentation, colours and horizontal scroll; multi-line options render as code too. Optional labels (direct): chapter, topic, year (aliases pyqYear, yearOfAppearance), note. Chapter/topic/year appear as chips above the question; the note appears on the results page. None are required; a malformed year is reported, never silently fixed. Sample and tests: scripts/fixtures/gate-cs1-2026.json, scripts/quiz.test.ts."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"4.3 Public notes and documents site (summary direct)","id":"43-public-notes-and-documents-site-summary-direct","text":"Route /notes/<userId> and /notes/<userId>/docs/<slug> bypass the login gate and the app navbar (lib/publicRoutes.ts, isPublicPath). Documents are bundled at build time (scripts/build-docs.mjs → lib/docs/generated.ts, a titles-only index.generated.ts for client menus, and search.generated.ts for search) so it works on Vercel with no runtime file access. The credentials CSV is deliberately not bundled. A dependency-free Markdown→HTML renderer (lib/docs/markdown.ts) escapes everything first, then emits only its own tags; links resolve between docs; headings get anchors; fences become captioned code blocks or diagram holders. Hamburger menu: Notes, Documents (each folder expandable), a separate Research section, and \"Open Pacewise\". Navbar hides on scroll-down and returns on scroll-up (documents only). QR links always use the production domain https://pacewise-delta.vercel.app (override with NEXTPUBLICSITEURL); the QR encoder is a custom implementation (lib/qr.ts) verified by decoding."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"4.4 Diagrams and code on doc pages (direct)","id":"44-diagrams-and-code-on-doc-pages-direct","text":"components/Notes/MermaidViewer.tsx: drag to pan, arrow pad, zoom in/out (Ctrl/⌘ scroll), reset (fit), full-screen expand, copy source; follows the site theme; falls back to the source text if rendering fails. Mermaid and the ELK layout load from a CDN on demand, which produces GitHub's look (orthogonal edges, line hops). lib/docs/highlight.ts: tiny tokenizer for ts/js/c/bash/json/css/nginx/yaml; fenced blocks can carry title\"path/to/file.ts\" principle\"…\" , shown as a caption bar (path language Copy) and a \"Principle\" footer. Large ASCII trees stay plain but larger. Full-text search (components/Notes/DocSearch.tsx): index of every section; results show document › section with a highlighted snippet and jump to the section; loaded only when first used; centred pill that widens on hover/focus and follows the site theme."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"5. Challenges and findings (problem → cause → fix → lesson)","id":"5-challenges-and-findings-problem-cause-fix-lesson","text":"# Problem Root cause (finding) Fix Lesson 1 QR code failed to decode for longer links (version 7) The \"reserved modules\" check also skipped alignment patterns (only finder-overlap positions must be skipped) Corrected the reserved-area logic; verified by decoding with OpenCV Verify encoders by decoding, not by eye 2 A PDF appeared to belong to another user Large PDFs exceed localStorage quota; the write failed silently, and the ownership record lived in the same write, so it was lost; the app then fell back to the signed-in user Ownership moved to a small separate list (customStoryClaims); SessionManager.findCustomStoryOwner checks it first; test added Never store ownership in the same write as large content; treat storage failures as first-class 3 Vercel deployment URL did not show the update, but the domain did Each deployment has its own permanent URL for that build; the production domain points at the latest promoted production deployment; deployment URLs can also be protected Share the production domain (and use it in QR links) Deployment URL per-build preview; domain what users see 4 Type errors under the lightweight type-check Wrapper components did not declare className/style/children; notFound() return typing Declared props explicitly; added return null after notFound() Explicit prop types on wrappers 5 Doc diagram showed raw source, not a diagram The viewer imported the mermaid npm package, which the owner's machine had not installed; the error was caught and the fallback source was shown Load Mermaid ELK from a CDN on demand (no install needed) Don't make a feature depend on an install step the user may not have run 6 Diagram looked different from GitHub (curved, tangled edges) Default layout is dagre with curved edges; GitHub's picture uses ELK orthogonal routing Register @mermaid-js/layout-elk and use layout: \"elk\" (falls back to dagre if it fails); reproduced and screenshot-compared locally Compare against the reference image, not memory 7 Search bar ignored dark mode The pill used Tailwind dark: variants, but this app switches theme with data-theme on <html>, not the dark class Styled with :root[data-theme\"dark\"] rules Match the app's own theming mechanism 8 Quiz rejected the GATE JSON Importer understood only single-choice (needed ≥2 options and one numeric index); the file has array answers and empty-option typed-number questions Added the two question kinds end-to-end (import, quiz UI, grading, results, editor, export) Parse the real file first; design the schema from real data 9 Hydration error \"Text content does not match server-rendered HTML\" (first fix wrong) Two causes. (a) The \"Shared by …\" name came from browser storage, which the server cannot see (fixed first). (b) The real, persistent cause: inline <style>{css}</style> blocks containing \" characters — React's server renderer HTML-escapes text inside <style> (\" → &quot;) but browsers do not decode entities in <style>, so server and client text differed Insert CSS via dangerouslySetInnerHTML in all three style blocks (doc content, search, quiz code) In React, never put CSS with quotes/</& as <style> children; and when a fix doesn't remove an error, look for a second cause 10 Highlighting tools requested then removed Feature scope changed Removed toolbar, saved marks and author highlight styling; deleted the annotation engine Remove dead code with the feature"},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"6. Key insights (the short list)","id":"6-key-insights-the-short-list","text":"1. Isolation should be structural, not procedural. Per-user data is safe because a repository can only be built with one UserNamespace, not because every call site remembers to pass a user id. 2. Storage fails quietly. localStorage quota errors, private-mode access errors and SSR have no window; every read/write needs a defensive path, and critical metadata must not share a write with bulky data. 3. Server and client must render byte-identical first HTML. Anything from browser storage, time, randomness or locale must be read after mount; inline <style> text with quotes is a trap. 4. Public pages need a different trust model. The QR notes site shows no personal data, bypasses login, bundles docs at build time, and excludes the demo-credentials CSV on purpose. 5. Design from the real input. The GATE file revealed two question kinds the schema lacked; a schema should be a superset of real data, with new fields optional and aliases tolerated. 6. Match the reference by measurement. Diagram fidelity (ELK vs dagre) and QR validity (decode test) were settled by reproducing and comparing, not by assumption. 7. Make features not depend on setup steps. CDN loading removed the \"run npm install\" failure mode. 8. Use the app's own mechanisms. Theme via data-theme, tokens via CSS variables, surfaces via rounded-[32px] — new UI should be indistinguishable from old. 9. Additive change is how \"don't change anything else\" is honoured. Optional props, optional JSON fields, new files — old behaviour is untouched and tests prove it (editor 55, session 23, presence 8, docs 8, quiz 8). 10. Name the principle where the code lives. Documentation that points to path principle (Template Method, Composition, Value Object…) is verifiable: the reader can open the file."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"7. Research notes (summaries of the research notes in docs/research/)","id":"7-research-notes-summaries-of-the-research-notes-in-docsresearch","text":""},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"7.1 Scaling, security, and the revision notifier","id":"71-scaling-security-and-the-revision-notifier","text":"State must leave the browser: one source of truth per user behind an API; progress is write-heavy (partition by user), stories and notes are read-heavy (CDN cache). Cheap security that prevents most incidents: hashed passwords, short-lived tokens, per-user authorisation on every query, rate limits on login and upload, validation at every boundary; uploads go straight to object storage via signed URLs, the server keeps only metadata owner id. Monitoring: structured logs, request metrics (latency, errors), alerts on error rate, not single failures. Notifier (spaced repetition): after each test schedule the next review by score — below 50% next day; 50–80% in 3 days; above 80% in 7 days, doubling each time — with a scheduler that sends at most one reminder per user per day. Decision: keep the client-side design for now; when adding a backend move state first, then uploads, then reminders. Context of the original discussion (summary): relevance for a 2.5 Cr-package profile if a backend with monitoring and engineering best practices is added, YouTube-scale thinking, and algorithm design for the notifier. The honest framing: the engineering judgement shown (isolation, defensive storage, tests, documentation) matters more than raw scale claims."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"7.2 Uploaded PDF ownership bug — see §5 #2.","id":"72-uploaded-pdf-ownership-bug-see-5-2","text":""},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"7.3 Vercel deployments vs domain — see §5 #3.","id":"73-vercel-deployments-vs-domain-see-5-3","text":""},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"8. Intentions — at what level this is being built","id":"8-intentions-at-what-level-this-is-being-built","text":"Level Intention Evidence in the codebase Product A polished, Apple-grade reading trainer whose design is consistent on every screen Design tokens, 32px surfaces, homepage typography reused everywhere Engineering craft Readable, principled OOP with SOLID and named patterns, each linked to a file docs/OOPARCHITECTURE.md with captioned code samples Quality Behaviour proven by tests, not claimed 102 automated tests across five suites Reliability Fail soft: quota errors, SSR, private mode, missing CDN Defensive repositories; diagram fallback; guarded storage Security & privacy Isolation by construction; public pages carry no personal data; secrets not bundled UserNamespace, public-route design, CSV excluded Portfolio / career A showable system for senior full-stack roles: documentation site reachable by QR, architecture write-ups, research notes Notes site, docs site, research section Future scale A clear path from client-only to backend (state → uploads → reminders), with monitoring and a spaced-repetition notifier §7.1 Extensibility Drop in any block-level diagram or new quiz field without code changes mermaid blocks; optional quiz schema"},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"9. How to use the new authoring features (quick reference)","id":"9-how-to-use-the-new-authoring-features-quick-reference","text":"Documents (docs//.md) Diagram: a fenced block with language mermaid becomes the interactive viewer. Code with context: ts title\"lib/session/UserSession.ts\" principle\"Composition over inheritance\" . Other writing tools: underline, strike, bold italic. (text now shows as plain text.) New folder new menu group; a folder named research appears under Research. After editing docs run node scripts/build-docs.mjs (also runs on predev/prebuild). Quiz JSON { \"question\": \"…\\n(code may be included with \\\\n and indentation, or in a fence)\", \"options\": [\"A\", \"B\", \"C\", \"D\"], \"correctAnswer\": 1, \"explanation\": \"Why.\", \"chapter\": \"Operating Systems\", \"topic\": \"Deadlock\", \"year\": 2026, \"note\": \"Shown after the test.\" } Select-all: \"correctAnswer\": [0, 2]. Typed number: \"options\": [], \"correctAnswer\": 4.25 (optionally \"tolerance\"). chapter, topic, year, note are all optional."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"10. Known limitations and honest caveats","id":"10-known-limitations-and-honest-caveats","text":"The assistant has not run the app in the owner's browser; every browser-level behaviour (drag/zoom feel, scroll-hide navbar, search dropdown, hydration) is verified by reasoning, isolated rendering and tests only. Diagrams need internet access (CDN). Offline or CSP-restricted deployments would see the source text instead; bundling Mermaid locally is the alternative. Code detection in plain-text questions is heuristic; one-line code without line breaks is left as prose. Use fences for certainty. Docs search looks at titles, headings and body text but is a simple word-match (no typo tolerance or ranking beyond title > heading > body). Public documents are public to anyone with the link: do not put secrets in docs/. Notes shared via QR show the owner's name only when the viewing browser has that user stored locally. Next.js 14.2.5 is flagged as outdated by the dev overlay; upgrading is a separate task."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"11. References","id":"11-references","text":"Framework and web platform Next.js — Text content does not match server-rendered HTML (hydration errors): https://nextjs.org/docs/messages/react-hydration-error Next.js App Router documentation: https://nextjs.org/docs/app React — hydrateRoot and hydration mismatches: https://react.dev/reference/react-dom/client/hydrateRoot React — useSyncExternalStore: https://react.dev/reference/react/useSyncExternalStore MDN — Web Storage API and quota behaviour: https://developer.mozilla.org/en-US/docs/Web/API/WebStorageAPI MDN — <style> element (raw text content): https://developer.mozilla.org/en-US/docs/Web/HTML/Element/style Tailwind CSS — dark mode (class vs media strategies): https://tailwindcss.com/docs/dark-mode Vercel — Deployments and domains: https://vercel.com/docs/deployments/overview and https://vercel.com/docs/projects/domains Diagrams Mermaid documentation (class diagrams, configuration): https://mermaid.js.org/ Mermaid layouts (ELK): https://mermaid.js.org/config/layouts.html Eclipse Layout Kernel (ELK): https://eclipse.dev/elk/ GitHub — Creating diagrams (Mermaid in Markdown): https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-diagrams QR codes ISO/IEC 18004 (QR code symbology) and the free summary at https://www.qrcode.com/en/about/standards.html Reed–Solomon error correction (background): https://en.wikipedia.org/wiki/Reed%E2%80%93Solomonerrorcorrection Object-oriented design Gamma, Helm, Johnson, Vlissides — Design Patterns (Template Method, Observer, Facade, Registry-style access) Robert C. Martin — SOLID principles (Single responsibility, Open/closed, Liskov, Interface segregation, Dependency inversion) Eric Evans — Domain-Driven Design (Value Object, Aggregate Root) Project documents: docs/OOPARCHITECTURE.md, docs/QUIZANDPROFILE.md, docs/DEPLOYMENT.md, docs/PRODUCTIONCHECKLIST.md Learning science and revision scheduling Ebbinghaus — forgetting curve: https://en.wikipedia.org/wiki/Forgettingcurve Wozniak — SM-2 spaced-repetition algorithm: https://super-memory.com/english/ol/sm2.htm Roediger & Karpicke (2006) — test-enhanced learning (retrieval practice improves retention) Security and distributed systems OWASP Cheat Sheet Series (authentication, session management, file upload): https://cheatsheetseries.owasp.org/ OWASP Top 10: https://owasp.org/www-project-top-ten/ Kleppmann — Designing Data-Intensive Applications (partitioning, caching, queues, monitoring) Google SRE Book — monitoring distributed systems (alert on symptoms and error rates): https://sre.google/sre-book/monitoring-distributed-systems/ Case studies and saved posts (embedded in the docs site) Apple AirTag case study — LinkedIn post: https://www.linkedin.com/feed/update/urn:li:share:7520840668794118144 (Research › Apple AirTag case study) 10 algorithms behind system design — LinkedIn post: https://www.linkedin.com/feed/update/urn:li:share:7521638052172288001 (Syllabus › Insights) System design post — LinkedIn: https://www.linkedin.com/feed/update/urn:li:share:7514296223722467328 (Syllabus › System Design) 8 hidden system design problems — Shalini Goyal: https://lnkd.in/p/g35wJwn2 (Syllabus › Challenges) System design posts 1–3 — LinkedIn: https://www.linkedin.com/feed/update/urn:li:share:7519179549264343041 , https://www.linkedin.com/feed/update/urn:li:share:7518813190181343233 , https://www.linkedin.com/feed/update/urn:li:share:7518811245807005696 (System design folder) Quiz content GATE CS1 2026 question set provided by the owner (65 questions), kept as scripts/fixtures/gate-cs1-2026.json."},{"slug":"research--00-pacewise-research-readme","title":"Pacewise — Research README","folder":"research","heading":"12. Verification record (what was actually run)","id":"12-verification-record-what-was-actually-run","text":"npm test: editor 55, session 23, presence 8, docs 8, quiz 8 — all passing at the last run. Docs renderer: escaping, link safety, tables, nested lists, fences, diagram holders, anchors, captioned code (indentation kept, tokens, principle). Quiz: the full GATE file imports with no issues; multi-select exact-set grading; numeric tolerance; optional labels; code-in-question splitting verified on questions 27, 34 and 39 of that file. Rendering checks in headless Chromium: the OOP diagram with ELK in dark theme matched the GitHub reference; the captioned code block rendered with colours, indentation, path, language and principle footer. Syntax checks (esbuild) across every .ts/.tsx/.css; strict tsc on the library files touched. Not verified by the assistant: behaviour inside the owner's browser and live Vercel deployment. End of document."},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Scaling, security and the test notifier","id":"","text":""},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Scaling, security and the test notifier","id":"","text":""},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Question","id":"question","text":"What would it take to run Pacewise with a real backend at large scale, safely, and how should the \"take a test / revise\" reminder work?"},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Findings","id":"findings","text":"State must leave the browser. Today progress, sessions and stories live in localStorage; a backend needs one source of truth per user, behind an API. Reads dominate. Story pages and notes are read far more than written, so they suit a CDN plus a cache; user progress is write-heavy and suits a database with per-user partitioning. Security basics that cost little and prevent most incidents: hashed passwords, short-lived tokens, per-user authorisation on every query, rate limits on login and upload, and input validation on every boundary. Uploads (PDFs) go straight to object storage with a signed URL; the server stores only metadata and the owner id. Monitoring: structured logs, request-level metrics (latency, errors), and alerts on error rate rather than on single failures."},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Notifier algorithm","id":"notifier-algorithm","text":"Use spaced repetition: after each test, schedule the next review at an interval that grows when the score is good and shrinks when it is poor. Score Next review Below 50% next day 50–80% in 3 days Above 80% in 7 days, then double each time A scheduler job picks users whose next-review time has passed and sends one reminder per user, never more than one a day."},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Decision","id":"decision","text":"Keep the current client-side design for now; when adding a backend, move state first, then uploads, then reminders."},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Uploaded PDF showed the wrong owner","id":"","text":""},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Uploaded PDF showed the wrong owner","id":"","text":""},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Question","id":"question","text":"A PDF uploaded by one person appeared to belong to someone else. Why?"},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Findings","id":"findings","text":"Large PDFs exceed the browser's localStorage quota, so the save failed silently. The record saying \"this story belongs to user X\" was written in the same step, so it was lost too. With no owner on record, the app fell back to whoever was signed in."},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Fix","id":"fix","text":"Ownership is now kept in a separate small list (customStoryClaims) that always fits. SessionManager.findCustomStoryOwner checks that list before trusting anything else. A test covers the oversized-PDF case."},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Decision","id":"decision","text":"Never store ownership in the same write as large content."},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Vercel deployments versus the domain","id":"","text":""},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Vercel deployments versus the domain","id":"","text":""},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Question","id":"question","text":"Why did a specific deployment URL not show the update while the main domain did?"},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Findings","id":"findings","text":"Every deploy gets its own permanent URL (like pacewise-xxxx.vercel.app) showing exactly that build. The production domain always points at the latest production deployment. A deployment can be Ready but not promoted, or built from a branch, so its URL and the domain can differ. Deployment URLs may also be protected by Vercel authentication, so they can look \"not available\" to visitors."},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Decision","id":"decision","text":"Share the production domain (and use it in the QR code); treat deployment URLs as per-build previews."},{"slug":"research--04-apple-airtag-case-study","title":"Apple AirTag case study","folder":"research","heading":"Apple AirTag case study","id":"","text":""},{"slug":"research--04-apple-airtag-case-study","title":"Apple AirTag case study","folder":"research","heading":"Apple AirTag case study","id":"","text":"A case study of how Apple AirTag works as a system, saved from a LinkedIn post so it can be revisited. It is useful as a worked example of designing a large, privacy-sensitive, crowd-powered location network."},{"slug":"research--04-apple-airtag-case-study","title":"Apple AirTag case study","folder":"research","heading":"The post","id":"the-post","text":"::linkedin urn:li:share:7520840668794118144 1636 \"Apple AirTag case study (LinkedIn post)\""},{"slug":"research--04-apple-airtag-case-study","title":"Apple AirTag case study","folder":"research","heading":"Source","id":"source","text":"LinkedIn post: https://www.linkedin.com/feed/update/urn:li:share:7520840668794118144"},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"Docs writing tool — strategy and challenges","id":"","text":""},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"Docs writing tool — strategy and challenges","id":"","text":"How the Pacewise rich-text writing tool (the \"Google Docs\"-style editor used for stories) is designed, what was hard, and what is deliberately left for later. The code samples are taken from this repository, with their file path and the principle each one shows. The structure of the comparison with online collaborative editors (requirements first, then scale, then protocol choice, then conflict handling) follows the general approach found in public system-design material; everything below is written from this project's own code and decisions."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"1. Requirements we set for ourselves","id":"1-requirements-we-set-for-ourselves","text":"Kind Requirement Core Create, read, update and delete rich documents in the browser; import and export common formats Core Rich text, blocks, images, tables, and real code blocks with highlighting and auto-indent Non-functional Never lose typing (autosave crash recovery); never run untrusted HTML; per-user isolation Non-functional Works offline in the browser; feels instant (no round trip per keystroke) Out of scope (for now) Real-time multi-user editing, permissions, comments, server-side version history The most important decision: the document model is the product, not the HTML in the page. HTML from the browser is untrusted input; it is parsed, sanitized and turned into an immutable, typed model, and everything else (stats, export, reading text) reads that model."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"2. Strategy in one picture","id":"2-strategy-in-one-picture","text":"Ribbon / shortcuts ─► Command registry ─► EditorSurface (contenteditable, history, paste/drop) │ getHtml() ▼ RichDocument.fromHtml (always sanitizes) ─► typed Blocks │ ┌───────────────┬───────────────┼────────────────┬──────────────┐ ▼ ▼ ▼ ▼ ▼ Exporters Stats Reading text Autosave Edit lock (txt/md/html/docx) (debounced) (per document) │ DocumentStore ─► KeyValueStore UserNamespace (per-user session layer)"},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"3. Decisions and the code that implements them","id":"3-decisions-and-the-code-that-implements-them","text":""},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"3.1 Untrusted input is sanitized at the only door","id":"31-untrusted-input-is-sanitized-at-the-only-door","text":"private constructor( readonly html: string, readonly meta: DocumentMeta, readonly page: PageSettings ) {} / Entry point for UNTRUSTED html: always sanitizes. / static fromHtml(html: string, meta: DocumentMeta defaultMeta(), page: PageSettings DEFAULTPAGE): RichDocument { return new RichDocument(sharedSanitizer.sanitize(html), meta, page); } Challenge: pasted content (from Word, web pages, other editors) carries scripts, event handlers and odd styles. Decision: allow-list sanitizer, applied in the factory, so no code path can skip it."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"3.2 New export formats without touching the blocks","id":"32-new-export-formats-without-touching-the-blocks","text":"export interface BlockVisitor<R> { paragraph(block: ParagraphBlock): R; heading(block: HeadingBlock): R; list(block: ListBlock): R; code(block: CodeBlock): R; image(block: ImageBlock): R; table(block: TableBlock): R; rule(block: RuleBlock): R; pageBreak(block: PageBreakBlock): R; footnotes(block: FootnotesBlock): R; } export interface DocumentExporter { readonly id: string; readonly label: string; readonly extension: string; export(doc: RichDocument, resolveImage?: ImageResolver): ExportResult Promise<ExportResult>; } Challenge: DOCX is a zip of XML parts, and Markdown/plain text need different list numbering. Decision: one visitor per format, a shared numbering helper, and a small zip writer instead of a heavy dependency."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"3.3 Never lose the last keystrokes","id":"33-never-lose-the-last-keystrokes","text":"schedule(value: T): void { this.pending value; this.hasPending true; this.set(\"dirty\"); if (this.timer) clearTimeout(this.timer); this.timer setTimeout(() > this.flush(), this.delayMs); } flush(): void { if (this.timer) { clearTimeout(this.timer); this.timer null; } if (!this.hasPending) return; const v this.pending as T; this.hasPending false; this.pending undefined; this.set(\"saving\"); try { this.write(v); this.set(\"saved\"); } catch (e) { this.set(\"error\", e); } } Challenge: writing on every keystroke is wasteful; writing only on pause risks losing text when the tab closes. Decision: debounce (about 800 ms) plus an explicit flush, and a visible status (dirty / saving / saved / error)."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"3.4 Two tabs must not overwrite each other","id":"34-two-tabs-must-not-overwrite-each-other","text":"acquire(): boolean { const cur this.read(); if (cur && cur.owner ! this.owner && cur.until > this.now()) return false; this.write(); // Re-read: if another tab wrote between our check and write, the last writer wins. if (this.read()?.owner ! this.owner) return false; if (!this.beat && typeof setInterval ! \"undefined\") this.beat setInterval(() > this.write(), this.leaseMs / 3); return true; } Challenge: the classic lost-update problem across tabs. Decision: a renewable lease stored per document; the second tab becomes read-only instead of silently clobbering."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"3.5 Per-user isolation comes for free from the session layer","id":"35-per-user-isolation-comes-for-free-from-the-session-layer","text":"The editor's DocumentStore borrows the active user's UserNamespace, so another user's documents are unreachable by key construction (see docs/OOPARCHITECTURE.md). Nothing in the session layer was edited to add the editor."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"4. Why real-time co-editing is deliberately not built yet","id":"4-why-real-time-co-editing-is-deliberately-not-built-yet","text":"Public system-design material on collaborative editors converges on the same ladder, and it is the roadmap here too: Question Options Our position How do clients get updates? HTTP polling → Server-Sent Events → WebSocket WebSocket is the right fit (bidirectional, low latency); it needs a separate stateless service behind a queue How are concurrent edits merged? Last-write-wins → Operational Transformation (OT) → CRDTs Last-write-wins loses intent; OT preserves intent but is complex and costly with many editors; CRDTs trade metadata size for simpler merging Where does state live? Metadata in a relational DB, content in object storage Matches the \"drive-like storage\" goal in the syllabus How is history kept? Snapshots, operation logs, or both Snapshots first (simple, fast to restore); logs later Decision: ship a very good single-writer editor first (it is the part users touch every minute), keep the document model operation-friendly, and add co-editing only with a backend."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"5. Challenges and what we learned","id":"5-challenges-and-what-we-learned","text":"# Challenge What we did Lesson 1 Contenteditable behaves differently across browsers Wrapped it in one facade (EditorSurface); React only talks to the facade Hide platform quirks behind one object 2 Unsafe pasted HTML Allow-list sanitizer in the only factory Make the safe path the only path 3 Undo/redo with custom blocks (code, tables, images) Own bounded history of snapshots plus a selection memento Native undo breaks with custom widgets 4 Code blocks need real editing rules A DOM-free engine for indent, brackets and comments, under a thin widget Keep rules testable without a browser 5 Large images blow the browser's storage quota Downscale to a maximum size and store images separately from text Storage fails quietly; budget for it 6 Many export formats Strategy Visitor, one class per format Open/Closed pays off at the second format 7 Lost updates between tabs Lease-based edit lock Prefer locks that expire 8 Losing text on tab close Debounced autosave flush crash recovery Save on pause and on exit"},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"6. How the docs site itself uses the same ideas","id":"6-how-the-docs-site-itself-uses-the-same-ideas","text":"The public documentation pages follow the same philosophy: Markdown is escaped first, then only the renderer's own tags are produced, so a document cannot inject HTML; diagrams and code blocks are special, validated holders; and writing tools are plain text conventions (highlight, underline, fenced code with title\"…\" principle\"…\"). See docs/QUIZANDPROFILE.md."},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"7. Related documents","id":"7-related-documents","text":"docs/TEXTEDITOR.md — full design, OOP, CN, OS and DBMS notes for the editor docs/OOPARCHITECTURE.md — the per-user session layer the editor relies on Research README — the record of challenges and insights across the project"},{"slug":"research--05-docs-writing-tool-strategy-and-challenges","title":"Docs writing tool — strategy and challenges","folder":"research","heading":"8. References (public sources, no text copied)","id":"8-references-public-sources-no-text-copied","text":"WebSocket protocol — RFC 6455: https://www.rfc-editor.org/rfc/rfc6455 Server-Sent Events — HTML Standard: https://html.spec.whatwg.org/multipage/server-sent-events.html Ellis & Gibbs (1989), Concurrency control in groupware systems — the origin of Operational Transformation Shapiro et al. (2011), Conflict-free Replicated Data Types — CRDTs OWASP — XSS Prevention Cheat Sheet: https://cheatsheetseries.owasp.org/cheatsheets/CrossSiteScriptingPreventionCheatSheet.html MDN — contenteditable and Selection API: https://developer.mozilla.org/en-US/docs/Web/API/Selection General system-design write-up on collaborative document editing (requirements → protocol → conflict handling), used only as a reference for the structure of the discussion"},{"slug":"research--readme","title":"Research","folder":"research","heading":"Research","id":"","text":""},{"slug":"research--readme","title":"Research","folder":"research","heading":"Research","id":"","text":"Findings from investigating the questions behind Pacewise: what it takes to scale it, why a bug happened, and how deployment really works. Each note states the question, what was found, and the decision taken. Pacewise — Research README: the full record of requests, challenges, findings, insights, intentions and references Scaling, security and the test notifier Uploaded PDF showed the wrong owner Vercel deployment URL versus the domain Docs writing tool — strategy and challenges: editor design decisions with code from the repo Apple AirTag case study: embedded LinkedIn post The project syllabus (chapters 1–8, starting with the Pacewise sub-systems) is in the Syllabus section of the menu: Pacewise syllabus. Every note ends with the decision, so you can read just the last section when short on time."},{"slug":"syllabus--03-methodologies--01-tools-and-technology","title":"Tools and Technology","folder":"syllabus/03-methodologies","heading":"Tools and Technology","id":"","text":""},{"slug":"syllabus--03-methodologies--01-tools-and-technology","title":"Tools and Technology","folder":"syllabus/03-methodologies","heading":"Tools and Technology","id":"","text":"Content for this section will be added here."},{"slug":"syllabus--04-cn-os-oops-dbms-utilization","title":"Core CSE","folder":"syllabus","heading":"Core CSE","id":"","text":""},{"slug":"syllabus--04-cn-os-oops-dbms-utilization","title":"Core CSE","folder":"syllabus","heading":"Core CSE","id":"","text":"Content for this chapter will be added here."},{"slug":"syllabus--05-challenges","title":"Challenges","folder":"syllabus","heading":"Challenges","id":"","text":""},{"slug":"syllabus--05-challenges","title":"Challenges","folder":"syllabus","heading":"Challenges","id":"","text":"Content for this chapter will be added here."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"System Design 2","id":"","text":""},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"System Design 2","id":"","text":""},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"Pacewise Search Engine — system design case study","id":"pacewise-search-engine-system-design-case-study","text":"Design a search engine that finds anything inside a user's own notes, docs, PDFs and images, in under 200 ms. This chapter takes the Google case study (the 2013 IJCTE paper and the \"Google search architecture\" post) and applies the same crawl → index → rank → serve skeleton to Pacewise. The big differences are that Pacewise search is private (each user searches only their own content) and its input is not just web pages — it is notes, scanned PDFs and photos of handwriting."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"1. What Google teaches us","id":"1-what-google-teaches-us","text":"Google component (from the paper) What it does Pacewise equivalent URL server distributed crawlers Decide what to fetch and download pages Not needed. Content arrives by upload or import, so an event queue replaces the crawler Store server repository Compress and store every fetched page Object store for originals, plus a doc store for extracted text docID One number per page docId per file, chunkId per page or section inside it Indexer → \"hits\" Per word: position, font size, capitalisation Per word: position, heading level (the font-size analogue), field (title, body, OCR) Barrels → sorter → inverted index Forward index re-sorted by word Same idea, handled by the search engine's segments Lexicon DumpLexicon Word list kept in memory Lexicon used for spell correction and autocomplete Anchors file Link text, valuable for pages that cannot be indexed as text, such as images Doc-to-doc links and image captions become anchor text PageRank, PR(A) (1-d) d·Σ PR(Ti)/C(Ti), d 0.85 Importance from backlinks Small-weight \"link rank\" over the links between a user's docs 500 servers per query Index partitioned by docID, so every query fans out One shard per query, partitioned by userId (see section 6) Top-k, caches, nearest data centre Keep latency low Same: top-k, result cache, regional replicas The post's summary still holds: crawling finds content, indexing makes it understandable, searching ranks and shows it. We keep the last two and replace crawling with an ingestion pipeline."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"2. Requirements","id":"2-requirements","text":"Functional Full-text search across notes, docs, quiz questions, text inside digital PDFs, text inside scanned PDFs and text inside images. Results show the file, the page number and a highlighted snippet, and open the reader at that page. Typo tolerance, synonyms, phrase search, filters such as type:pdf and in:folder, and autocomplete. A newly added note is searchable within seconds. A scanned PDF is searchable by title immediately and by content once OCR finishes. Non-functional p95 query latency under 200 ms, p99 under 400 ms. Strict tenant isolation: a query can never return another user's content. Highly available reads. Brief delay in indexing is acceptable, a wrong or missing result is not. Deleting a file removes it from search within 24 hours. Out of scope: web crawling, ads, sponsored results, cross-user search."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"3. Capacity estimates","id":"3-capacity-estimates","text":"These are assumptions, written down so each design decision can be checked against them. Quantity Assumption Result Users 1,000,000 Documents 200 per user 200 M docs Mix 70% text, 20% PDF, 10% image 140 M text · 40 M PDF · 20 M images Words text 1,500 · PDF 16,000 (40 pages) · image 60 ≈ 850 B words Raw text 6 bytes per word ≈ 5 TB Inverted index about 35% of raw text ≈ 1.8 TB, ×3 replicas ≈ 5.4 TB Vectors (phase 3) 300-word chunks → 2.8 B chunks, product-quantised to 48 B ≈ 136 GB Queries 10 per user per day 10 M/day ≈ 116 QPS average, plan for 1,000 QPS peak New files 3 per user per day 3 M/day ≈ 35 per second OCR volume 15% of 24 M PDF pages 0.3 M images per day ≈ 3.9 M pages/day ≈ 45 CPU cores average, 150 at peak Shards at most 40 GB each ≈ 50 primaries What the numbers tell us: the index fits comfortably on a few dozen machines, so the hard parts are not storage. They are OCR throughput, tenant isolation, freshness and ranking quality."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"4. High-level architecture","id":"4-high-level-architecture","text":"!Pacewise search engine — high-level architecture Two independent paths meet in the search cluster. The online path answers queries and must be fast. The offline path turns files into searchable chunks and must be reliable and elastic. Because they only share the index, a surge of uploads can never slow down searching."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"5. Ingestion: documents, PDFs and images","id":"5-ingestion-documents-pdfs-and-images","text":"!Ingestion pipeline for notes, PDFs and images 1. Store first. The original goes to object storage and an event is published. If everything downstream fails, the file is safe and can be reprocessed. 2. Route by content, not by file name. Detect the type using the MIME type and magic bytes. 3. Notes and docs. Parse headings and links, then keep the heading level as a ranking weight. 4. PDFs. Check each page for a text layer. If a page has enough characters it is extracted with layout (page number and bounding boxes). If not, it is rasterised at about 300 dpi and sent to OCR. A single PDF can mix both, so the decision is per page. 5. Images. Deskew, denoise and boost contrast, then OCR. Keep the confidence score. Optionally add a caption or an image embedding so that \"whiteboard photo of the load balancer\" can match without any text in it. 6. Normalise, chunk, analyse. Unicode NFKC, language detection, then chunks of about 300 words with 15% overlap that respect page and heading boundaries. Every chunk remembers its docId, page and bounding boxes, so a result can highlight the exact place. 7. Index in bulk. Write the chunk to the shard chosen by hash(userId) and the chunk text to the doc store. type PageResult { page: number; text: string; source: \"text-layer\" \"ocr\"; confidence: number }; const MINCHARSPERPAGE 40; export async function extractPdf(pdf: PdfDocument): Promise<PageResult[]> { const results: PageResult[] []; for (let page 1; page < pdf.pageCount; page) { const layer await pdf.textLayer(page); if (layer.text.trim().length > MINCHARSPERPAGE) { results.push({ page, text: layer.text, source: \"text-layer\", confidence: 1 }); continue; } const bitmap await pdf.rasterise(page, { dpi: 300 }); const ocr await ocrQueue.run(bitmap); // slow lane, autoscaled results.push({ page, text: ocr.text, source: \"ocr\", confidence: ocr.confidence }); } return results; } Operational rules that matter Two lanes. Text goes through a fast lane, OCR through a slow lane with its own workers. A 400-page scanned book never delays a one-line note. Idempotency. Each job is keyed by fileHash pipelineVersion, so retries and duplicate events are harmless. Back-pressure. Autoscale OCR workers on queue lag. Failed jobs retry with exponential backoff and then land in a dead-letter queue for inspection. Progressive availability. Index the title and metadata first. The user sees the file immediately with an \"indexing\" badge, and content becomes searchable as pages finish. Deduplication. An exact hash catches identical uploads. A near-duplicate fingerprint (simhash) catches the same document exported twice, and only one copy is ranked."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"6. Index design","id":"6-index-design","text":"!Inverted index and tenant routing The structure is the one Google described: a forward index (document → words) re-sorted into an inverted index (word → documents). A multi-word query intersects the posting lists. In the example above, \"online\" appears in documents 13, 28, 49, 54 and 99, \"shopping\" in 13, 23, 49 and 57, so only 13 and 49 match both. Each posting stores more than a document number: term frequency, positions (for phrase and proximity matching) and a field flag, so a match in a title counts more than a match in an OCR'd footnote. Decision: partition by userId, not by docId. Partition by docId (Google) Partition by userId (Pacewise) Shards touched per query All of them One Tail latency Slowest shard decides One shard, one replica Tenant isolation A filter on every shard Physical boundary plus a filter Weak spot None for web search A very large user makes a hot shard The weak spot is handled by splitting a heavy tenant across a few sub-shards (userId docBucket), which keeps the single-shard rule for 99.9% of users. Replicas serve reads and are placed in the nearest region, and a copy of the index in each region is what keeps latency low, as in the Google post. Buy or build? The inverted index, BM25 and vector search are solved problems. Use a Lucene-based engine such as OpenSearch for them and spend engineering time where Pacewise is different: the ingestion pipeline, tenant routing and ranking."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"7. Query flow","id":"7-query-flow","text":"!Query flow with latency budget 1. Normalise and parse — lowercase, split filters from words. 2. Spell and synonyms — the lexicon plus edit distance corrects \"algorthm\"; a small synonym table maps \"OS\" to \"operating system\". 3. Cache lookup — key is userId normalised query index version. Including the index version means a new upload invalidates stale results without any manual purge. 4. Route to the user's shard in the nearest region. 5. BM25F lexical retrieval — top 100 chunks, with title ×3, heading ×2, body ×1. 6. Vector retrieval (phase 3) — top 100 chunks by meaning, so \"how does a load balancer pick a server\" finds a note that never uses those words. 7. Fuse and re-rank with Reciprocal Rank Fusion plus the signals below. 8. Snippets — take the best chunk, show the page number, and draw OCR bounding boxes over the matched words. type Ranked { chunkId: string; rank: number }; const K 60; // dampens the gap between rank 1 and rank 2 export function reciprocalRankFusion(lists: Ranked[][]): Map<string, number> { const fused new Map<string, number>(); for (const list of lists) { for (const { chunkId, rank } of list) { fused.set(chunkId, (fused.get(chunkId) ?? 0) 1 / (K rank)); } } return fused; }"},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"8. Ranking","id":"8-ranking","text":"!Ranking signals Retrieval decides what could match. Ranking decides what comes first. Starting weights, to be tuned rather than trusted: Signal Weight Why BM25F text match 0.50 Core relevance, field-weighted Phrase and proximity 0.15 Words close together mean a better match (Google keeps hit positions for the same reason) Personal behaviour 0.12 What this user opens, saves and reads for long Doc link rank 0.10 Docs that many other docs link to are probably central Freshness 0.08 Recent notes win ties Anchor text 0.05 Words in links pointing at a doc describe it better than the doc itself Penalties apply for duplicates, very low OCR confidence and near-empty pages. The link rank is the paper's PageRank, run on the small graph of one user's docs: export function linkRank( links: Map<string, string[]>, // docId → docs it links to iterations 20, d 0.85, ): Map<string, number> { const ids [...links.keys()]; let rank new Map(ids.map((id) > [id, 1 / ids.length])); for (let i 0; i < iterations; i) { const next new Map(ids.map((id) > [id, (1 - d) / ids.length])); for (const [from, targets] of links) { if (targets.length 0) continue; const share (rank.get(from) ?? 0) / targets.length; for (const to of targets) next.set(to, (next.get(to) ?? 0) d share); } rank next; } return rank; } How we know ranking is good. Offline: NDCG@10 and MRR on a labelled set of real queries and the doc the user eventually opened. Online: click-through on the first three results, zero-result rate, time to first click, reformulation rate (searching again immediately means the first answer failed) and p95 latency. Every ranking change ships behind an A/B test."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"9. Pacewise today and the path to this design","id":"9-pacewise-today-and-the-path-to-this-design","text":"Phase What exists Why it is enough Trigger to move on 0 — now A build-time full-text index bundled with the docs site, searched in the browser Tens of pages, no server cost Content becomes user-generated 1 Postgres full-text search with trigram typo tolerance, plus an OCR queue One datastore, easy to operate Queries over 50 ms or index over 100 GB 2 OpenSearch, routed by userId, with autocomplete and filters Proper relevance, horizontal scale Users want \"find by meaning\" 3 Hybrid lexical vector, learning-to-rank from clicks Best relevance Tuning from real data Each phase is shippable and the interfaces (search(userId, query, filters)) stay the same, so the move is a migration, not a rewrite."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"10. Failure modes and security","id":"10-failure-modes-and-security","text":"Problem What happens Mitigation OCR workers fall behind Scanned files wait Autoscale on queue lag, text lane is separate, UI shows \"indexing\" A shard replica dies Reads shift to another replica 3 replicas, health checks, automatic promotion Bad OCR text Garbage terms, false matches Confidence threshold, penalty, keep original image for display Poison file crashes a parser Same job retried forever Retry limit, dead-letter queue, per-file timeout and memory cap Hot tenant One shard overloaded Sub-shard the tenant, rate-limit per user Cache serves stale data User cannot find new note Index version is in the cache key Cross-tenant leak Worst case userId filter added server-side from the auth token, never from the client; shard routing as a second boundary; automated test that queries as user A for user B's unique word Deleted file still searchable Privacy issue Tombstone immediately, hide at query time, purge segments within 24 hours Also: encrypt originals and index at rest, use short-lived signed URLs for file access, and run OCR in a sandboxed worker because PDF and image parsers are a common attack surface."},{"slug":"syllabus--06-system-design--02-system-design-2","title":"System Design 2","folder":"syllabus/06-system-design","heading":"11. Why this design is senior-level","id":"11-why-this-design-is-senior-level","text":"It starts from numbers (section 3) and shows that storage is not the bottleneck, then spends effort on the real ones. It changes the Google design where the problem differs — tenant partitioning instead of docID partitioning, an ingestion pipeline instead of a crawler — rather than copying it. It makes explicit trade-offs: build versus buy, per-page OCR decision, progressive availability, fast lane versus slow lane. It treats correctness and privacy (tenant isolation, deletion) as first-class, not as an afterthought. It defines how success is measured and a migration path from what exists today. Credit: structure and the Google component names follow Lavania, Jain, Gupta and Sharma, \"Google: A Case Study (Web Searching and Crawling)\", IJCTE Vol. 5 No. 2, 2013, and the \"Google search architecture\" newsletter post; the numbers, the Pacewise design and the diagrams are original to this document."},{"slug":"syllabus--07-research-references","title":"Research References","folder":"syllabus","heading":"Research References","id":"","text":""},{"slug":"syllabus--07-research-references","title":"Research References","folder":"syllabus","heading":"Research References","id":"","text":"Content for this chapter will be added here."},{"slug":"syllabus--08-insights","title":"Insights","folder":"syllabus","heading":"Insights","id":"","text":""},{"slug":"syllabus--08-insights","title":"Insights","folder":"syllabus","heading":"Insights","id":"","text":"Content for this chapter will be added here."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"Overview","id":"","text":""},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"Overview","id":"","text":"The Pacewise project at a glance, followed by the chapters of the syllabus."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"1. Sub-systems","id":"1-sub-systems","text":"A. Authentication B. Session Handling C. Drive-like Server Storage D. Google Docs E. Book-Flip PDF with Editing Tool F. PDF Merger G. Search Engine H. PDF Search Engine I. Quiz J. Progress & History Tracking K. Analytics for Everything L. Scheduling Algorithm M. Recommendation Based on Interest N. Feed Generation O. Sharing Options with People: Like, Dislike, Follow, Comment and All Other Features P. Mail Sharing Features Q. QR-Based Document Sharing with Anyone R. Notification System S. 1-2 Click T. Progress & History Tracking"},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"III. Hard","id":"iii-hard","text":""},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"A. Advanced PDF Editing & Annotation Engine","id":"a-advanced-pdf-editing-annotation-engine","text":"i. Scope: Adding text, images, other PDFs, code, markings and shapes to pages; persisting and downloading edited documents. iii. Note: Rendering, coordinate mapping, page order and export correctness are the key challenges."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"B. Advanced Reading Engine","id":"b-advanced-reading-engine","text":"i. Scope: Normal scroll and book-flip modes, guided/self-paced reading, WPM controls and smooth page navigation. iii. Note: Complex document layouts, reading synchronization and performance increase its difficulty."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"C. OCR & Document Intelligence","id":"c-ocr-document-intelligence","text":"i. Scope: PDF text extraction, scanned documents, handwritten-note understanding and visual understanding integration. iii. Note: Accuracy for handwriting recognition and poor-quality scans is particularly challenging."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"D. Full-Document Search & Indexing","id":"d-full-document-search-indexing","text":"i. Scope: Finding relevant content from a search query, navigating to the correct page, indexing OCR text and keeping the index up to date after document changes."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"E. Adaptive Learning & Revision Engine","id":"e-adaptive-learning-revision-engine","text":"i. Scope: Scheduling based on learning pace, revision of earlier syllabus, weekly tests and performance-based recommendations. ii. Difficulty: Hard iii. Note: The real difficulty arises when recommendations are validated against measurable learning improvement."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"F. Multi-User Collaboration & Identity","id":"f-multi-user-collaboration-identity","text":"i. Scope: Multiple sessions, permissions, SSO, shared documents, data isolation and concurrent editing. iii. Note: SSO integration itself can be comparatively straightforward; reliable permissions and concurrent editing are more difficult."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"G. Content Platform Infrastructure","id":"g-content-platform-infrastructure","text":"i. Scope: Drive-like server storage, user-specific documents, feed generation, content deduplication, duplicate-page comparison and copyright-related similarity signals. iii. Note: Reliable storage, access control and scalable feed/indexing make it complex."},{"slug":"syllabus--readme","title":"Overview","folder":"syllabus","heading":"Chapters","id":"chapters","text":"Each chapter is its own page in the Syllabus section of the menu. Core CSE comes first. 1. Core CSE 2. Methodologies Tools and Technology 3. Challenges 4. System Design System Design 2 — the Pacewise search-engine case study (5 SVG diagrams) 5. Insights For related material see the Research section."},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"Social Media","id":"","text":""},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"Social Media","id":"","text":"LinkedIn posts saved to revisit, all embedded on this one page. Each one links back to the original."},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"System design post 1","id":"system-design-post-1","text":"::linkedin urn:li:share:7519179549264343041 1615 \"System design post 1 (LinkedIn)\" Original: https://www.linkedin.com/feed/update/urn:li:share:7519179549264343041"},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"System design post 2","id":"system-design-post-2","text":"::linkedin urn:li:share:7518813190181343233 1552 \"System design post 2 (LinkedIn)\" Original: https://www.linkedin.com/feed/update/urn:li:share:7518813190181343233"},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"System design post 3","id":"system-design-post-3","text":"::linkedin urn:li:share:7518811245807005696 1846 \"System design post 3 (LinkedIn)\" Original: https://www.linkedin.com/feed/update/urn:li:share:7518811245807005696"},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"System design post 4","id":"system-design-post-4","text":"::linkedin urn:li:share:7514296223722467328 1531 \"System design post 4 (LinkedIn)\" Original: https://www.linkedin.com/feed/update/urn:li:share:7514296223722467328"},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"10 algorithms behind system design","id":"10-algorithms-behind-system-design","text":"::linkedin urn:li:share:7521638052172288001 1699 \"10 algorithms behind system design (LinkedIn)\" Original: https://www.linkedin.com/feed/update/urn:li:share:7521638052172288001"},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"Apple AirTag case study","id":"apple-airtag-case-study","text":"::linkedin urn:li:share:7520840668794118144 1636 \"Apple AirTag case study (LinkedIn)\" Original: https://www.linkedin.com/feed/update/urn:li:share:7520840668794118144"},{"slug":"system-design--social-media","title":"Social Media","folder":"system-design","heading":"8 hidden system design problems","id":"8-hidden-system-design-problems","text":"Original post: https://lnkd.in/p/g35wJwn2"}];
